// 结构：BEIBAO[现代名]={o:原书名, c:内容, g:分类}
// ============================================================

const BEIBAO = {
  "丁香":{o:"丁香",c:"燥，暖胃，补肾 \n辛温纯阳。泄肺温胃，大能疗肾，壮阳事，暖阴户。治胃冷壅胀，呕哕呃逆（丹溪曰∶ \n人之阴气，以胃为养。土伤则木挟相火，直冲清道而上作咳逆。古人以为胃寒，用丁香、柿 \n蒂，不能清痰利气，惟助火而已。按∶呃逆有痰阻、气滞、食塞，不得升降者；有火郁下焦 \n者；有伤寒汗、吐，下后，中气大虚者；有阳明内热失下者；有痢疾大下，胃虚而阴火上冲 \n者。时珍曰∶当视虚实阴阳，或泄热，或降气，或温，或补，或吐，或下，可也。古方单用 \n柿蒂，取其苦温降气。《济生》加丁香、生姜，取其开郁散痰。盖从治之法，亦尝有收效者 \n矣。朱氏但执以寒治热，矫枉之过矣） 癖奔豚，腹痛口臭（丹溪曰∶脾有郁火，溢入肺中，",g:"温里药"},
  "三七":{o:"三七",c:"\\x一名山漆\\x \n泻，散瘀，定痛 \n甘苦微温。散血定痛。 \n治吐血衄血，血痢血崩，目赤痈肿（醋磨涂即散，已破者为末掺之）。为金疮杖疮要药 \n（杖时先服一二钱，则血不冲心；杖后敷之，去瘀消肿易愈。大抵阳明、厥阴血分之药，故 \n治血病）。 \n此药近时始出，军中恃之。从广西山洞来者，略似白芨、地黄，有节，味微甘，颇似人 \n参。以末掺猪血中，血化为水者真（近出一种，叶似菊艾，而劲浓有岐尖，茎有赤棱，夏秋 \n开黄花，蕊如金丝，盘纽可爱，而气不香，根大如牛蒡，味甘极。《易繁衍》云是三七，治 \n金疮折伤血病甚效，与南中来者不同）。",g:"止血药"},
  "三棱":{o:"荆三棱",c:"泻，行气，破血，消积 \n苦平。色白属金（皮黑肉白），入肺金血分，破血中之气（亦通肝经聚血），兼入脾经。 \n散一切血瘀、气结，疮硬食停，老块坚积（乃坚者削之。从血药则治血，从气药则治气。须 \n辅以健脾补气药良。昔有人患症瘕死，遗言开腹取之，得病块如石。文理五色，削成刀柄。 \n因砍三棱，柄消成水，乃知此药可疗症瘕），消肿止痛，通乳堕胎。功近香附而力峻，虚者 \n慎用。 \n色黄体重，若鲫鱼而小者良。醋浸、炒，或面裹、煨。",g:"活血化瘀药"},
  "丝瓜":{o:"丝瓜",c:"泻热凉血，宣通经络 \n甘平（苏颂曰冷）。凉血解毒，除风化痰，通经络，行血脉（老者筋络贯穿，象人经络， \n故可借其气以引之），消浮肿，稀痘疮（出不快者，烧存性，入朱砂，蜜水调服）。治肠风崩 \n漏，疝痔痈疽，滑肠下乳。",g:"清热药"},
  "丹参":{o:"丹参",c:"补心，生血，去瘀 \n气平而降（《本经》∶微寒。宏景曰∶性应热）。味苦色赤，入心与包络。破宿血，生新 \n血（瘀去然后新生），安生胎（养血），堕死胎（去瘀），调经脉（风寒湿热，袭伤营血，则 \n经水不调。先期属热，后期属寒。又有血虚、血瘀、气滞、痰阻之不同。大抵妇人之病，首 \n重调经，经调则百病散），除烦热，功兼四物（一味丹参散，功同四物汤），为女科要药。 \n治冷热劳，骨节痛，风痹不随（手足缓散，不随人用。经曰∶足受血而能步、掌受血 \n而能握），肠鸣腹痛，崩带症瘕（音“征加”。症者有块可征，瘕者假也，移动聚散无常，皆 \n血病），血虚血瘀之候。又治目赤、疝痛、疮疥、肿毒，排脓生肌（郑奠一曰∶丹参养神定",g:"活血化瘀药"},
  "丹砂":{o:"丹砂",c:"重，镇心，定惊，泻热 \n体阳性阴（内含阴汞），味甘而凉，色赤属火（性反惊者，离中虚有阴也。味不苦而甘 \n者，火中有土也）。泻心经邪热（心经血分主药），镇心清肝，明目发汗（汗为心液），定惊 \n祛风，辟邪（胡玉少卿多恶梦，遇推官胡用之，胡曰∶昔常患此，有道士教戴灵砂而验。逐 \n解髻中绛囊授之，即夕无梦）解毒（胎毒、痘毒宜之），止渴安胎（《博救方》∶水煮一两， \n研，酒服，能下死胎。李时珍曰∶同远志、龙骨之类养心气；同丹参、当归之类养心血；同 \n地黄、枸杞之类养肾；同浓朴，川椒之类养脾；同南星、川乌之类祛风。多服反令人痴呆）。 \n辰产，明如箭镞者良（名箭镞砂）。细研，水飞三次用（生用无毒，火炼则有毒",g:"解表药"},
  "乌梅":{o:"乌梅",c:"涩肠，敛肺 \n酸涩而温。脾、肺血分之果，敛肺（肺欲收，急食酸以收之）涩肠，涌痰消肿，清热解 \n毒，生津止渴，醒酒杀虫。 \n治久咳泻痢（梁庄肃公血痢，陈应之用乌梅、胡黄连、灶下土等分为末，茶调服而愈。 \n曾鲁公血痢百余日，国医不能疗，应之用盐梅肉研烂，合腊茶入醋服，一啜而安）。瘴疟（诸 \n症初起者，皆禁用）霍乱，吐逆反胃，劳热骨蒸（皆取其酸收），安蛔厥（蛔虫上攻而眩仆。 \n虫得酸则伏，仲景有蛔厥乌梅丸），去黑痣，蚀恶肉（痈疮后生恶肉，烧梅存性，研末敷之）。 \n多食损齿伤筋（经曰∶酸走筋，筋病无多食酸）。 \n白梅功用略同。治痰厥僵仆，牙关紧闭（取肉揩擦牙龈，涎出即开。盖酸先入筋，齿软 \n则易开。若",g:"收涩药"},
  "乌梢蛇":{o:"乌梢蛇",c:"宣，去风湿 \n功用同白花蛇，而性善无毒。不吃物。眼光至死不枯。以尾细能穿百钱者佳。重七钱至 \n一两者为上，十两至一镒者中，大者力减。去头与皮、骨，酒煮或酥炙用。",g:"祛风湿药"},
  "乌臼木":{o:"乌臼木",c:"泻热毒 \n苦凉、性沉而降。利水通肠，功胜大戟。疗疔肿，解砒毒（极能泻下。凡患肿毒，中砒 \n毒者，不拘根、皮、枝、叶，捣汁多饮，得大利即愈。虚人忌用）。 \n子，可作烛。",g:"泻下药"},
  "乌药":{o:"乌药",c:"宣，顺气 \n辛温香窜，上入脾、肺，下通肾经。能疏胸腹邪逆之气。 \n一切病之属气者皆可治。气顺则风散，故用以治中气、中风（厥逆、痰壅、口噤、脉伏 \n，身温为中风，身冷为中气。又有痰为中风，无痰为中气。《局方》治此，亦用乌药顺气散 \n。许学士云∶暴怒伤阴，暴喜伤阳，忧愁不已，气多厥逆。往往得中气之证，不可作中风治 \n），及膀胱冷气，小便频数，反胃吐食，宿食不消，泻痢霍乱，女人血凝气滞。小儿蛔蛔， \n外如疮疖疥疠，皆成于血逆，理气亦可治之。疗猫、犬百病。气虚、气热者忌用（时珍曰∶ \n四磨汤治七情郁结上气喘急者，降中兼收，泻中兼补也。方用人参、乌药、沉香、槟榔，各 \n浓磨汁七分合煎。缩泉丸，用同益智、",g:"理气药"},
  "乌骨鸡":{o:"乌骨鸡",c:"补虚劳 \n甘平。鸡属木，而骨黑者属水，得水木之精气，故能益肝肾，退热补虚。治虚劳消渴， \n下痢噤口（煮汁益胃），带下崩中，肝、肾血分之病。鬼击卒死者，用其血涂心下效（《睽车 \n志》∶夏侯弘捉得一小鬼，问∶所持何物？曰∶杀人以此矛戟，中心腹者，无不辄死。弘曰 \n∶治此有方否？鬼曰∶以乌鸡敷之即瘥）。骨肉俱黑者良，舌黑者骨肉俱黑。男用雌，女用 \n雄（女科有乌鸡丸，治百病）。",g:"其他"},
  "乳香":{o:"乳香",c:"\\x一名熏陆香\\x \n宣，活血，伸筋 \n香窜入心，苦温补肾，辛温通十二经。能去风伸筋（筋不伸者，敷药加用），活血调气， \n托里护心（香彻疮孔，能使毒瓦斯外出，不致内攻），生肌止痛。治心腹诸痛，口噤耳聋，痈 \n疽疮肿，产难折伤（皆取其活血止痛）。亦治癫狂（以能去风散瘀。灵苑辰砂散，辰砂一两， \n乳香、枣仁各五钱，酒下。恣饮沉醉，听睡一二日勿动，惊醒则不可治。《本事》加人参一 \n两，名宁志膏）。出诸番。如乳头、明透者良（市人多以枫香伪之）。性粘难研，水飞过，用 \n钵坐热水中研之，或用灯心同研则易细。",g:"活血化瘀药"},
  "云母":{o:"云母",c:"补中 \n甘平属金，色白入肺。下气补中，坚肌续绝。治劳伤疟痢，疮肿痈疽（同黄丹熬膏贴之 \n。《千金翼》∶用敷金疮。青城山人康道丰，有云母粉方，能治百病）。有五色，以色白光 \n莹者为上。古人亦有炼服者（云母入火，经时不焦，入土不腐，故云服之长生）。使泽泻。 \n恶羊肉。",g:"其他"},
  "五倍子":{o:"五倍子",c:"涩，敛肺 \n咸酸。其性涩，能敛肺；其气寒，能降火。生津化痰，止嗽止血，敛汗（郑赞寰曰∶焙 \n研极细，以自己漱口水调敷脐上，治盗汗如神）解酒，疗消渴泄痢，疮癣五痔，下血脱肛， \n脓水湿烂，子肠坠下，散热毒，消目肿（煎水洗之），敛疮口（热散，疮口自敛）其色黑， \n能染须（丹溪曰∶倍子属金与水，噙之善收顽痰，解热毒。黄昏咳嗽，乃火浮肺中，不宜用 \n凉药，宜五倍、五味，敛而降之。《医学纲目》云∶王元圭虚而滑精，屡与加味四物汤，吞 \n河间秘真丸及珍珠粉丸，不止。后用五倍子一两，茯苓二两，丸服遂愈。此则倍子敛涩之功， \n敏于龙骨、蛤粉也。昂按∶凡用秘涩药，能通而后能秘。此方用茯苓倍于五倍，一泻一收， \n是",g:"收涩药"},
  "五加皮":{o:"五加皮",c:"宣，去风湿，补，壮筋骨 \n辛顺气而化痰，苦坚骨而益精，温祛风而胜湿。逐肌肤之瘀血，疗筋骨之拘挛（肾得其 \n养，则妄水去而骨壮；肝得其养，则邪风去而筋强）。 \n治五缓虚羸（五脏筋脉缓纵。《千金方》补云∶五月五日采茎，七月七日采叶，九月九 \n日采根，合为末，治五劳）阴痿囊湿，女子阴痒（湿生虫），小儿脚弱，明目愈疮。酿酒尤 \n良（王纶曰∶风病饮酒，能生痰火，惟五加浸酒益人）。 \n茎青，节白，花赤，皮黄，根黑，上应五车之精。芬香、五叶者佳。远志为使。恶玄参 \n。",g:"祛风湿药"},
  "五味子":{o:"五味子",c:"补肺肾，涩精气。 \n性温。五味俱备（皮甘、肉酸，核中苦辛，都有咸味）酸咸为多，故专收敛肺气而滋肾 \n水（气为水母。经曰∶肺欲收，急食酸以收之。王好古曰∶入手太阴血分、足少阴气分）。 \n益气生津（肺主气，敛故能益，益气故能生津。夏月宜常服，以泻火而益金），补虚明目， \n强阴涩精（仲景八味丸，加之补肾。盖内核似肾，象形之义）退热敛汗，止呕住泻，宁嗽定 \n喘（感风寒而喘嗽者当表散，宜羌、防、苏、桔；痰壅气逆而喘嗽者当清降，宜二陈及苏子 \n降气汤；水气逆而喘嗽者，宜小青龙半夏茯苓汤；气虚病久而喘嗽者，宜人参五味）除烦渴， \n消水肿，解酒毒，收耗散之气，瞳子散大。嗽初起脉数有实火者忌用（丹溪曰∶五味收肺",g:"收涩药"},
  "五灵脂":{o:"五灵脂",c:"宣，行血，止痛 \n甘温纯阴，气味俱浓。入肝经血分。通利血脉，散血和血，血闭能通（生用），经多能 \n止（炒用）。治血痹血积，血眼血痢，肠风崩中，一切血病（《图经》云∶血晕者，半炒半生， \n末服一钱），心腹血气，一切诸痛。又能除风化痰，杀虫消积（诸痛皆属于木，诸虫皆生于 \n风），治惊、疳、疟、疝，蛇、蝎、蜈蚣伤。血虚无瘀者忌用（五灵脂一两，雄黄五钱，酒 \n调服，滓敷患处，治毒蛇咬伤。李仲南曰∶五灵脂治崩中，非正治之药。乃去风之剂，冲、 \n任经虚，被风袭伤营血，以致崩中暴下，与荆芥、防风治崩义同。方悟古人识见深远如此。 \n时珍曰∶此亦一说，但未及肝虚血滞，亦自生风之意。按∶冲为血海，任主胞胎。任脉通",g:"活血化瘀药"},
  "五谷虫":{o:"五谷虫",c:"\\x即粪蛆\\x \n泻热，疗疳 \n寒。治热病谵（音占，妄语）妄，毒痢作吐，小儿疳积疳疮。漂净晒干，或炒，或 ，为 \n末用。",g:"其他"},
  "井泉水":{o:"井泉水",c:"补 \n将旦首汲，曰井华水；出瓮未放，曰无根水，无时初出，曰新汲水。解热闷烦渴（凡热 \n病不可解者，新汲水浸青色衣服互熨之炒。心闷汗出，新汲水蜜和饮炒），煎补阴之药宜之 \n（井以有地脉山泉者为上；从江湖渗来者次之；其城市近沟渠污秽者，咸而有碱。煮粥煎茶， \n味各有异，以之入药，其可无择乎？）。",g:"其他"},
  "人中白":{o:"人中白",c:"泻火 \n咸平。降火散瘀，治肺瘀鼻衄（刮人中白，新瓦火上逼干，调服即止），劳热消渴，痘 \n疮倒陷，牙疳口疮。即溺 ， 研用（以蒙馆童子便桶、山中老僧溺器刮下者，尤佳）。",g:"清热药"},
  "人中黄":{o:"人中黄",c:"泻热 \n甘寒入胃。清痰火，消食积，大解五脏实热。治天行热狂，痘疮血热，黑陷不起。纳甘 \n草末于竹筒中，紧塞其孔，冬月浸粪缸中。至春取出洗，悬风处阴干，取甘草用（亦有用皂 \n荚末者，竹须削去青皮）。一云即粪缸多年黄 ， 存性用。",g:"消食药"},
  "人乳":{o:"人乳",c:"补虚，润燥 \n甘咸。润五脏，补血液，止消渴，泽皮肤，治风火证（昂按∶老人便秘，人乳最良）。 \n本血所化，目得血而能视，用点赤涩多泪（热者，黄连浸点）。然性寒滑，脏寒胃弱人不宜 \n多服（时珍曰∶人乳无定性。其人和平，饮食冲淡，其乳必平。其人躁暴，饮酒食辛，或有 \n火病，其乳必热。又有孕之乳，为忌乳，最有毒，小儿食之吐泻，成疳魃之病，内亦损胎。 \n昂按∶乳乃阴血所化，生于脾胃，摄于冲任。未受孕则下为月水，既受孕则留而养胎，已产 \n则变赤为白，上为乳汁，以食小儿，乃造化之玄微也。服之益气血，补脑髓，乃谓以人养人 \n也。然能滑肠、湿脾、腻膈，天设之以为小儿，非壮者所当常服。唯制为粉，则有益无损， \n又",g:"补虚药"},
  "人参":{o:"人参",c:"大补元气，泻火 \n生甘苦微凉（甘补阳，微苦微寒，又能补阴），熟甘温。大补肺中元气（东坦曰∶肺主 \n气，肺气旺，则四脏之气皆旺，精自生而形自盛。十剂曰补可去弱，人参羊肉之属是也。人 \n参补气，羊肉补形），泻火（得升麻补上焦，泻肺火；得茯苓补下焦，泻肾火；得麦冬泻火 \n而生脉；得黄 、甘草，乃甘温退大热。东垣曰∶参、 、甘草，泻火之圣药，合用名黄 \n汤。按烦劳则虚而生热，得甘温以益元气，而邪热自退，故亦谓之泻），益土（健脾）、生金 \n（补肺）。明目，开心益智，添精神，定惊悸（邪火退，正气旺，则心肝宁而惊悸定），除烦 \n渴（泻火故除烦、生津故止渴），通血脉（气行则血行，贺汝瞻曰∶生脉散用之者，以其通",g:"补虚药"},
  "人牙":{o:"人牙",c:"宣，发痘 \n咸温有毒。治痘疮倒 （《痘疹论》∶出不快而黑陷者， 猪血调下一钱；服凉药而血 \n涩倒陷者，麝香酒调服。时珍曰∶欲其窜入肾经，发出毒瓦斯，盖劫剂也。若伏毒在心，不省 \n人事，气虚色白、痒塌无脓，及热痱紫泡之证，只宜补虚解毒。苟误服此，则郁闷声哑，反 \n成不救）。 退火毒，研用。",g:"清热药"},
  "仙茅":{o:"仙茅",c:"燥，补肾命 \n辛热有小毒。助命火，益阳道，明耳目，补虚劳。 \n治失溺无子，心腹冷气不能食（温胃），腰脚冷痹不能行（暧筋骨）。相火盛者忌服。 \n叶如茅而略阔，根如小指，黄白多涎。竹刀去皮，切，糯米泔浸，去赤汁，出毒用。忌 \n铁（唐，婆罗门始进此方，当时盛传，服之多效。照前制，阴干，蜜丸，酒服。禁牛乳、牛 \n肉。许真君书曰∶甘能养肉，苦能养气，咸能养骨，酸能养筋，滑能养肤，和苦酒服之必效 \n）。",g:"补虚药"},
  "代赭石":{o:"代赭石",c:"重，镇虚逆，养阴血 \n苦寒。养血气，平血热，入肝与心包，专治二经血分之病，吐衄崩带，胎动产难，小儿 \n慢惊（赭石半钱，冬瓜仁汤调服），金疮长肉（仲景治伤寒汗吐下后，心下痞硬、噫气，用 \n代赭旋复汤。取其重以镇虚逆，赤以养阴血也。今人用治膈噎甚效）。 红醋淬，水飞用。 \n干姜为使。畏雄、附。",g:"平肝息风药"},
  "伏龙肝":{o:"伏龙肝",c:"重，调中，止血，燥湿，消肿 \n辛温。调中止血、去湿消肿。治咳逆反胃，吐衄崩带，尿血遗精，肠风痈肿（醋调涂）， \n脐疮（研敷）丹毒（腊月猪脂或鸡子白调敷），催生下胎（《博救方》子死腹中，水调三钱服， \n其土当儿头上戴出）。斧心多年黄土，一云灶额内火气，积久结成如石，外赤中黄。研细， \n水飞用。",g:"化湿药"},
  "何首乌":{o:"何首乌",c:"平补肝肾，涩精 \n苦坚肾，温补肝，甘益血，涩收敛精气。添精益髓，养血祛风（治风先治血，血活则风 \n散），强筋骨，乌髭发（故名首乌），令人有子，为滋补良药。气血太和，则劳瘦风虚、崩带 \n疮痔、瘰 痈肿诸病自已（营血调则痈肿消。赤者，外科呼为疮帚）止恶疟（益阴补肝，疟 \n疾要药，而本草不言治疟。时珍曰∶不寒不燥功在地黄、天冬诸药之上）。 \n有赤、白二种。夜则藤交，一名六藤，有阴阳交合之象。赤雄入血分，白雌入气分。以 \n大如拳、五瓣者良，三百年者大如栲栳，服之成地仙。凡使赤、白各半泔浸，竹刀刮皮切片 \n，用黑豆与首乌拌匀，铺柳甑，入砂锅，九蒸九晒用。茯苓为使。忌诸血、无鳞鱼、莱菔、 \n葱、蒜、铁器（",g:"补虚药"},
  "使君子":{o:"使君子",c:"补脾，杀虫，消积 \n甘温。健脾胃，除虚热，杀脏虫。 \n治五疳便浊，泻痢疮癣，为小儿诸病要药（《经疏》曰∶五疳便浊，泻痢腹虫，皆由脾 \n胃虚弱，因而乳停食滞、湿热瘀塞而成。脾胃健，则积滞消，湿热散，水道利，而前证尽除 \n矣。时珍曰∶凡能杀虫之药，多是苦辛，独使君子、榧子，甘而杀虫。每月上旬，虫头向上 \n，中旬头横，下旬向下。《道藏》云∶初一至初五，虫头向上。凡有虫病者，每月上旬，空 \n心食数枚，虫皆死而出也。按∶地黄、胡麻皆杀虫）。 \n出闽蜀，五瓣有 ，内仁如榧。亦可煨食，久则油，不可用。忌饮热茶，犯之作泻。",g:"驱虫药"},
  "侧柏叶":{o:"侧柏叶",c:"补阴，凉血 \n苦涩微寒（《本草》微温）。养阴滋肺而燥土最清血分，为补阴要药。 \n止吐衄崩淋，肠风尿（血）痢（血），一切血证，去冷风湿痹，历节风痛（肢节大痛， \n昼静 \n夜剧，名白虎历节风。亦风寒湿所致）。涂汤火伤（捣烂水调涂），生肌杀虫，炙罨冻疮，汁 \n乌髭发。 \n取侧者（丹溪曰∶多得月令之气，随月建方取），或炒或生用。桂、牡蛎为使。恶菊花。 \n宜酒（万木皆向阳，柏独四指，受金之正气，坚劲不凋，多寿之木，故元旦饮椒柏酒以辟邪） \n。",g:"止血药"},
  "僵蚕":{o:"僵蚕",c:"轻，宣，去风，化痰 \n辛咸微温。僵而不腐，得清化之气，故能治风化痰，散结行经（蚕病风作僵，故因以治 \n风，能散相火逆结之痰）。其气味俱薄，轻浮而升，入肺、肝、胃三经。治中风失音，头风 \n齿痛，喉痹咽肿（炒为末，姜汤调下一钱，当吐出顽痰），丹毒瘙痒（皆风热为病），瘰 结 \n核，痰疟血病，崩中带下（风热乘肝），小儿惊疳，肤如鳞甲（由气血不足，亦名胎垢，煎 \n汤浴之）。下乳汁，灭瘢痕。苦诸症由于血虚而无风寒客邪者勿用。以头蚕色白条直者良。 \n糯米泔浸一日，待桑涎浮出，漉起焙干，拭净肉、毛、口、甲，捣用。恶桑螵蛸、茯苓、茯 \n神、桔梗、萆 。 \n蚕茧，甘温。能泻膀胱相火，引清气上朝于口，止消渴（蚕与马",g:"平肝息风药"},
  "兔矢":{o:"兔矢",c:"\\x一名明月砂\\x \n宣，明目，杀虫 \n杀虫明目，治痨瘵五疳，痘后生翳。 \n兔肝泻肝热，故能明目。 \n兔肉治消渴（《海上方》∶澄汁冷冻饮料），小儿食之稀痘疮（陶弘景曰∶孕妇食之，令儿缺 \n唇。保寿堂兔血丸，令小儿永不出痘，虽出亦稀。腊八日取生兔刺血，和荞麦面，加雄黄四 \n五分，和丸，如绿豆大。初生小儿，乳汁送下二三丸，遍身发出红点，此其验也）。",g:"驱虫药"},
  "冬瓜":{o:"冬瓜",c:"\\x又名白瓜\\x \n泻热，补脾 \n寒泻热，甘益脾。利二便，消水肿（冬瓜任吃效），止消渴（苗、叶皆治消渴），散热毒 \n痈肿（切片敷之。丹溪曰∶冬瓜性急而走，久病阴虚者忌之。昂按∶冬瓜日食常物，于诸瓜 \n中尤觉宜人，且味甘而不辛，何以见其性急而走乎？）。 \n子，补肝明目（凡药中所用瓜子，皆冬瓜子也）。",g:"其他"},
  "冬葵子":{o:"冬葵子",c:"滑肠，利窍 \n甘寒淡滑。润燥利窍，通营卫，滋气脉，行津液，利二便，消水肿（用榆皮等分煎服）， \n通关格，下乳滑胎。 \n秋葵复种，经冬至春作子者，名冬葵子。根、叶同功。春葵子亦滑，不堪入药。 \n蜀葵花，赤者治赤带，白者治白带，赤者治血燥，白者治气燥。亦治血淋、关格，皆取 \n其寒润滑利之功也。",g:"其他"},
  "冰":{o:"冰",c:"泻热 \n甘寒。太阴之精，水极似土。伤寒阳毒热甚昏迷者，以一块置膻中（两乳中间）良。解 \n烧酒毒（陈藏器曰∶盛夏食冰，与气候相反，冷热相激，却致诸疾。宋徽宗食冰太过，病脾 \n疾，国医不效。杨介进大理中丸，上曰∶服之屡矣。介曰∶病因食冰，臣请以冰煎此药，治 \n受病之源也，果愈）。",g:"其他"},
  "冰片":{o:"冰片",c:"\\x一名龙脑香\\x \n宣，通窃，散火 \n辛温。香窜善走能散，先入肺，传于心脾而透骨，通诸窍，散郁火。治惊痫痰迷（东垣 \n曰∶风病在骨髓者宜之。若在血脉肌肉，反能引风入骨，如油入面），目赤肤翳（乳调日点 \n数次。王节斋曰∶冰片大辛热，用之点眼，取其拔出火邪。盖火郁发之，从治法也。世人误 \n以为寒，而常用之。遂致积热害目，故云眼不点不瞎者，此也），耳聋鼻息（鼻中息肉，点 \n之自入，皆通窍之功），喉痹舌出（散火），骨痛齿痛（治骨），痘陷（猪心血作引，酒服或 \n紫草汤服，引入心经能发之）产难，三虫五痔（王纶曰∶世人误以为寒，不知辛散性甚，似 \n乎凉耳。诸香皆属阳，岂有香之至者，而反寒乎？昂幼时曾问家叔",g:"开窍药"},
  "决明子":{o:"决明子",c:"泻肝，明目 \n甘苦咸平。入肝经，除风热。治一切目疾，故有决明之名。又曰∶益肾精（瞳子神光属 \n肾。日华曰∶明目甚于黑豆，作枕治头风）。 \n状如马蹄决明。捣碎煎。恶大麻仁。",g:"清热药"},
  "刀豆":{o:"刀豆",c:"宣，下气 \n甘平。温中止呃（ 存性服），胜于柿蒂。",g:"温里药"},
  "刘寄奴草":{o:"刘寄奴草",c:"泻，破血，止血 \n苦温。破血通经，除症下胀，止金疮血。多服令人吐利。 \n一茎直上，叶尖长、糙涩，花白芯黄，如小菊花，有白絮如苦 絮，子细长亦似苦 子 \n。茎、叶、花、子皆可用（刘裕，小字寄奴。微时，曾射一蛇，明日，见童子林中捣药，问 \n之，答曰∶吾王为刘寄奴所伤，合药敷之。裕曰∶王何不杀之？童曰∶寄奴，王者，不可杀 \n也。叱之不见，乃收药回。每遇金疮，敷之立愈）。",g:"活血化瘀药"},
  "刺蒺藜":{o:"蒺藜子",c:"平补肝肾 \n苦温补肾，辛温泻肺气而散肝风，益精明目（肝以散为补，凡补肝药，皆能明目）。 \n治虚劳腰痛，遗精带下，咳逆肺痿，乳闭症瘕，痔漏阴 （音颓），肾、肝、肺三经之 \n病，催生堕胎（刺蒺藜主恶血，故能破症下胎）。 \n沙苑蒺藜 绿色似肾（故补肾）。炒用（亦可代茶）。 \n刺蒺藜 三角有刺。去刺，酒拌蒸（风家宜刺蒺藜，补肾则沙苑者为优）。余功略同（瑞 \n竹堂方∶齿牙打动者，蒺藜根烧灰敷之）。",g:"平肝息风药"},
  "前胡":{o:"前胡",c:"宣，解表，泻，下气，治风痰 \n辛以畅肺解风寒，甘以悦脾理胸腹，苦泻厥阴（肝）之热，寒散太阳（膀胱）之邪（微 \n寒，一云微温）。性阴而降，功专下气，气下则火降而痰消（气有余便是火，火则生痰）。能 \n除实热。 \n治痰热哮喘，咳嗽呕逆，痞膈霍乱，小儿疳气，有推陈致新之绩。明目安胎。无外感者 \n忌用（按∶柴胡、前胡均是风药。但柴胡性升、前胡性降，为不同。肝胆经风痰，非前胡不 \n能除）。 \n皮白肉黑，味甘、气香者良。半夏为使。恶皂角。忌火。",g:"化痰止咳平喘药"},
  "升麻":{o:"升麻",c:"轻，宣，升阳，解毒 \n甘辛微苦。足阳明、太阴（胃、脾）引经药（参、 上行，须此引之），亦入手阳明、 \n太阴（大肠、肺）。表散风邪（引葱白，散手阳明风邪；同葛根，能发阳明之汗；引石膏， \n止阳明头痛齿痛），升发火郁，能升阳气于至阴之下。引甘温之药上行，以补卫气之散而实 \n其表（柴胡引少阳清气上行，升麻引阳明清气上行，故补中汤用为佐使。若下元虚者，用此 \n升之。则下元愈虚，又当慎用）。 \n治时气毒疠，头痛（阳明头痛，痛连齿颊）寒热，肺痿吐脓，下痢后重（后重者，气滞 \n也。气滞于中，必上行而后能下降。有病大小便秘者，用通利药而罔效，重加升麻而反通。 \n丹溪曰∶气升则水自降。经曰∶地气上为云，天气下为",g:"解表药"},
  "半夏":{o:"半夏",c:"燥湿痰，润肾燥，宣通阴阳 \n辛温有毒，体滑性燥，能走能散，能燥能润。和胃健脾（去湿），补肝（辛散）润肾， \n除湿化痰，发表开郁，下逆气，止烦呕，发音声，利水道（燥去湿，故利水；辛通气，能化 \n液，故润燥。丹溪谓∶二陈汤能使大便润而小便长），救暴卒（葛生曰∶凡遇五绝之病，用 \n半夏末吹入鼻中即活，盖取其能作嚏也。五绝，谓缢死、溺死、压死、魇死、产死也）。 \n治咳逆头眩（火炎痰升则眩），痰厥头痛，眉棱骨痛（风热与痰），咽痛（成无己曰∶半 \n夏辛散，行水气而润肾燥。又局方半硫丸，治老人虚秘，皆取其润滑也。俗以半夏、南星为 \n性燥误矣，湿去则土燥，痰涎不生，非二物之性燥也。古方用治咽痛、喉痹、吐血，非",g:"化痰止咳平喘药"},
  "卫矛":{o:"卫矛",c:"\\x一名鬼箭羽\\x \n泻，破血 \n苦寒（时珍曰∶酸涩）。破陈血，通经落胎，杀虫祛祟。干有三羽，叶似野茶。酥炙用。",g:"活血化瘀药"},
  "卷柏":{o:"卷柏",c:"生用破血，炙用止血 \n生用辛平，破血通经，治症瘕淋结。炙用辛温，止血，治肠风脱肛。 \n生石上，拳挛如鸡足，俗呼万年松。凡使盐水煮半日，井水煮半日，焙用。",g:"活血化瘀药"},
  "厚朴":{o:"浓朴",c:"泻，下气，散满 \n苦降能泻实满，辛温能散湿满（王好古曰∶《别录》言浓朴温中益气，消痰下气。果泄 \n气乎？益气乎？益与枳实、大黄同用，则泻实满，所谓消痰下气是也；与橘皮、苍术同用， \n则除湿满，所谓温中益气是也。与解利药同用，则治伤寒头痛；与泻利药同用，则浓肠胃。 \n大抵味苦性温，用苦则泻，用温则补也。同大黄、枳实，即承气汤。同橘皮、苍术，即平胃 \n散。按∶胀满症多不同，清、补贵得其宜。气虚宜补气，血虚宜补血，食积宜消导，瘀滞宜 \n行痰，挟热宜清热，湿盛宜利湿，寒郁者散寒，怒郁者行气，蓄血者消瘀，不宜专用行散药。 \n亦有服参、 而胀反甚者，以挟食、挟血、挟热、挟寒，不可概作脾虚气弱治也）。入足太",g:"化湿药"},
  "原蚕砂":{o:"原蚕砂",c:"燥湿，去风 \n蚕食而不饮，属火性燥，燥能去风胜湿（经曰∶燥胜风，燥属金，风属木也）其沙辛甘 \n而温。炒黄浸酒，治风湿为病，支节不随，皮肤顽痹，腰脚冷痛，冷血瘀血（史国公药酒中 \n用之）。炒热，熨患处亦良（寇宗 曰∶醇酒三升，拌蚕沙五升，蒸热铺暖室席上，令患冷 \n风气痹人以患处就卧，浓复取汗。不愈，间日再作，须防昏闷）。麻油调敷，治烂弦风眼（目 \n上下胞属脾。脾有风湿，则虫生弦烂。又新瓦炙，为末，少加雄黄，麻油调敷，治蛇串疮。 \n有人食乌梢蛇，浑身变黑，渐生鳞甲，见者惊缩。郑奠一令日服晚蚕沙五钱，尽一二斗，久 \n之乃退）。晚蚕矢也，淘净晒干。",g:"化湿药"},
  "发":{o:"发",c:"\\x一名血余\\x \n补，和血 \n发者血之余。味苦微寒，入足少阴、厥阴（肾、肝）。补阴消瘀，通关格 \n，利二便。治诸血疾（能去心窍之血，故亦治惊痫），血痢血淋，舌血（ 末，茅根汤服） \n鼻血（烧灰吹鼻），转胞不通（烧灰，服），小儿惊热（合鸡子黄，煎为汁服，鸡子能去风痰）。 \n合诸药煎膏，凉血去瘀长肉（发属心，禀火气而上生；眉属肝，禀木气而侧生；须属肾，禀 \n水气而下生。或曰发属肝，禀木气而直生；眉属金，禀金气而横生，金无余气，故短而不长， \n至老金气钝，则眉长矣。昂按∶肺主皮毛，毛亦短而不长者也，何以独无所属乎？毛既为肺 \n之合，自当属肺、属金。眉当属肝、属木，以其侧生象木枝也。此乃臆说，附质明",g:"清热药"},
  "吴茱萸":{o:"吴茱萸",c:"燥，去风寒湿，宣，下气开郁 \n辛苦大热，有小毒。入足太阴（脾）血分，少阴、厥阴（肾、肝）气分（其气燥，故专 \n入肝而旁及脾、肾）。润肝燥脾，温中下气，除湿解郁，去痰杀虫，开腠理，逐风寒。 \n治厥阴头痛（仲景用吴茱萸汤），阴毒腹痛（痛在小腹），呕逆吞酸（俗名醋心。亦有吐 \n酸者，宜降火清痰，用吴萸作响导。蔡中丞苦痰饮，率十日一发，头痛背寒，呕酸不食。得 \n一方，茯苓、吴萸汤泡七次，等分，蜜丸，名吴仙丹。前、后痰方无此者），痞满噎膈（胃 \n冷）。食积泻痢，血痹阴疝，痔疾肠风，香港脚水肿，口舌生疮（为末，醋调贴足心，过夜便 \n愈，能引热下行），冲脉为病，气逆里急（宜此主之）。性虽热，而能引热下行（段",g:"温里药"},
  "商陆":{o:"商陆",c:"大通，行水 \n苦寒有毒（诸家辛酸，时珍苦寒）。沉阴下行，与大戟、甘遂同功。 \n疗水肿胀满（肿属脾，胀属肝。肿则阳气犹行，如单胀而不肿者名臌胀，为木横克土， \n难治。肿胀朝宽暮急为血虚，朝暮俱急为气血两虚。肿胀由心腹而散四肢者吉，由四肢而入 \n心腹者危。男自下而上，女自上而下，皆难治）。瘕疝痈肿。喉痹不通，（薄切醋炒，涂喉中 \n良），湿热也病。泻蛊毒，敷恶疮，堕胎孕，令人见鬼神。 \n取花白者根（赤者伤人，只堪贴脐，入麝三分捣贴，小便利则，肿消），黑豆汤浸蒸用。 \n得蒜良。",g:"泻下药"},
  "土茯苓":{o:"土茯苓",c:"通，祛湿热，补脾胃 \n甘淡而平。阳明（胃、大肠）主药，健脾胃，祛风湿，脾胃健则营卫从，风湿除则筋骨 \n利。利小便，止泻泄。 \n治筋骨拘挛，杨梅疮毒（杨梅疮，古方不载。明·正德间起于岭表，其证多属阳明，厥 \n阴而兼及他经。盖相火寄于厥阴、肌肉属于阳明故也。医用轻粉劫剂，其性燥烈。入阳明劫 \n去痰涎，从口齿出，疮即干愈。然毒瓦斯窜入经络、筋骨，血液枯槁，筋失所养，变为拘挛、 \n痈、漏，竟致废痼。土茯苓能制轻粉之毒，去阳明湿热。用一两为君，苡仁、金银花、防风 \n、木通、木瓜、白藓皮各五分，皂角子四分，气虚加人参七分，血虚加当归七分，名搜风解 \n毒汤），瘰 疮肿（湿郁而为热，营卫不和，则生疮肿。经曰∶",g:"清热药"},
  "地榆":{o:"地榆",c:"涩，止血 \n苦酸微寒。性沉而涩（本草未尝言涩，然能收汗止血，皆酸敛之功也），入下焦，除血 \n热。 \n治吐衄崩中（血虚禁用），肠风（血鲜者为肠风，随感而见也；血瘀者为脏毒，积久而 \n发也。粪前为近血，出肠、胃；粪后为远血，出肺、肝）血痢（苏颂曰∶古方断下多用之。 \n寇宗 曰∶虚寒泻痢，及初起者忌用。苏颂，着《本草图科》）。 \n似柳根，外黑里红。取上截，炒黑用。梢皮行血。得发良。恶麦冬。",g:"止血药"},
  "地浆":{o:"地浆",c:"泻热，解毒 \n甘寒。治泻痢冷、热、赤、白，腹内热毒绞痛。解一切鱼肉、菜、果、药物、诸菌毒（ \n菌，音郡，生朽木湿地上。亦名蕈，音寻，上声），及虫蜞入腹（如误食马蟥蜞入腹，生子 \n为患，用地浆下之），中 （暑热）卒死者（取道上热土围脐，令人尿脐中，以热土大蒜等 \n分，捣水去渣，灌之即活）。以新水沃黄土搅浊，再澄清用（凡跌打损伤，取净土蒸热，以 \n布裹更互熨之，勿大热，恐破肉。虽瘀血凝积，气绝欲死者亦活。宋神宗皇子病螈 ，国医 \n不能治。钱乙进黄土汤而愈。帝问其故，对曰∶以土伏水，水得其平，风自止矣）。",g:"清热药"},
  "地肤子":{o:"地肤子",c:"通，利水，补阴 \n甘苦气寒。益精强阴，入膀胱，除虚热，利小便而通淋（时珍曰∶无阴则阳无以化，亦 \n犹东垣治小便不通，用知、柏滋肾之意。王节斋曰∶小便不禁或频数，古方多以为寒，而用 \n温涩之药。殊不知属热者多，盖膀胱火邪妄动，水不得宁，故不能禁而频数也。故老人多频 \n数，是膀胱血少，阳火偏旺也。治法当补膀胱阴血，泻火邪为主，而佐以收涩之剂，如牡蛎 \n、山茱、五味之类，不可独用。病本属热，故宜泻火。因水不足，故火动而致便数，小便既 \n多，水益虚矣，故宜补血。补血泻火，治其本也。收之涩之，治其标也）。 \n治 疝，散恶疮（煎汤，洗疮疥良）。叶作浴汤，去皮肤风热丹肿，洗眼除雀盲涩痛。 \n叶如蒿，茎赤，子",g:"利水渗湿药"},
  "地骨皮":{o:"地骨皮",c:"泻热凉血，补正气 \n甘淡而寒。降肺中伏火，泻肝、肾虚热，能凉血而补正气。 \n内治五内邪热（热淫于内，治以甘寒。地骨一斤，生地五斤，酒煮服，治带下），吐血 \n尿血（捣鲜汁服），咳嗽消渴（清肺）。外治肌热虚汗，上除头风痛（能除风者，肝、肾同治 \n也。 \n肝有热，则自生风，与外感之风不同，热退则风自息），中平胸胁痛（清肝），下利大、 \n小肠。疗在表无定之风邪，传尸，有汗之骨蒸（李东垣曰∶地为阴，骨为里，皮为表。地骨 \n皮泻肾火，牡丹皮泻包络火，总治热在外，无汗而骨蒸。知母泻肾火，治热在内有汗而骨蒸。 \n四物汤加二皮，治妇人骨蒸。朱二允曰∶能退内潮，人所知也；能退外潮，人实不知。病或 \n风寒散而未尽，",g:"清热药"},
  "地龙":{o:"白颈蚯蚓",c:"泻热，利水 \n蚓，土德而星应轸水。味性咸寒，故能清热；下行故能利水。治温病大热狂言，大腹黄 \n疸，肾风香港脚（苏颂曰∶香港脚必须用之为使）。白颈者，乃老蚯蚓。治大热，捣汁井水调下。 \n入药或晒干为末，或盐化为水，或微炙，或烧灰，各随本方（中其毒者，盐水解之。张 \n将军病蚯蚓咬毒，每夕蚓鸣于体，浓煎盐水浸身，数过而愈）。 \n蚯蚓泥（即蚯蚓屎），甘寒，泻热解毒。治赤白久痢，敷小儿阴囊热肿，肿腮丹毒。",g:"平肝息风药"},
  "墨":{o:"墨",c:"辛温。止血生肌。飞丝、尘芒入目，浓磨点之；点鼻止衄；猪胆汁磨，涂诸痈肿（醋磨 \n亦可）。酒磨服，治胞不下。",g:"其他"},
  "夏枯草":{o:"夏枯草",c:"补阳，散结，消瘿 \n辛苦微寒，气禀纯阳。补肝血，缓肝火，解内热，散结气。 \n治瘿 湿痹，目珠夜痛（楼全善曰∶目珠连目本，即目系也。夜痛及点苦寒药更甚者， \n夜与寒皆阴也，夏枯气禀纯阳；补厥阴血脉，故治此如神，以阳和阴也。按目白珠属阳，故 \n昼痛，点苦寒药则效；黑珠属阴，故夜痛，点苦寒药反剧）。 \n冬至生，夏至枯，故名，用茎叶。",g:"清热药"},
  "夜明砂":{o:"夜明砂",c:"\\x一名天鼠矢\\x \n泻，散血，明目 \n辛寒。肝经血分药。活血消积，治目盲障翳（加石决明猪肝煎，名决明夜灵散，治鸡盲 \n眼）疟 （音奇。小儿鬼）惊疳（蝙蝠及矢，并治惊、疳、疟、痫、厥阴之病），血气腹痛 \n（《经疏》曰∶辛能散内外滞气，寒能除血热气壅，明目之外，余皆可略。吴鹤皋曰∶古人 \n每用虻虫、水蛭治血积，以其善吮血耳。若天鼠矢，乃食蚊而化者也，当亦可以攻血积，《本 \n草》称其下死胎，则其能攻血块也何疑）。同鳖甲烧烟辟蚊。蝙蝠矢也，食蚊，砂皆蚊眼， \n故治目疾。淘净焙用。恶白薇、白蔹。",g:"活血化瘀药"},
  "大戟":{o:"大戟",c:"大泻，通脏腑水湿 \n苦寒有毒。能泻脏腑水湿，行血发汗，利大小便。 \n治十二种水，腹满急痛，积聚症瘕，颈腋痈肿，风毒脚肿，通经堕胎。误服损真气（时 \n珍曰∶痰涎为物，随气升降，无处不到。入心则迷，成癫痫；入肺则塞窍，为咳喘背冷；入 \n肝则胁痛干呕，寒热往来；入经络则麻痹疼痛；入筋骨则牵引隐痛；入皮肉则瘰 痈肿。陈 \n无择并以控涎丹主之，殊有奇效，此乃治痰之本。痰之本，水也，湿也，得气与火。则结为 \n痰。大戟能泄脏腑水湿，甘遂能行经络水湿，白芥子能散皮里膜外痰气，惟善用者能收奇功 \n也。又曰∶钱仲阳谓肾为真水，有补无泻。复云痘症变黑归肾者，用百祥膏下之，非泻肾也 \n，泻其腑，则脏自不实。腑者，膀胱",g:"解表药"},
  "大枣":{o:"大枣",c:"补脾胃，润心肺，和百药 \n甘油。脾经血分药。补中益气，滋脾土，润心肺，调营卫，缓阴血，生津液，悦颜色， \n通九窍，助十二经，和百药。伤寒及补剂加用之，以发脾胃升腾之气。多食损齿（齿属肾， \n土克水），中满证忌之（甘令人满。大建中汤心下痞者，减饧、枣与甘草同例。成无己曰∶ \n仲景治奔豚用大枣者，滋脾土以平肾气也。治水饮胁痛，有十枣汤，益脾土以胜妄水也）。 \n北产肥润者良（昂按∶金华南枣，更胜于北，徽宁所产，亦有佳者）。杀乌、附毒。忌葱、 \n鱼同食。",g:"补虚药"},
  "大腹皮":{o:"大腹皮",c:"泻，下气，通，行水 \n辛泄肺、温和脾。下气行水，通大、小肠。 \n治水肿香港脚，痞胀痰膈，瘴疟霍乱。气虚者忌用。 \n子，似槟榔，腹大形扁（故与槟榔同功）。取皮，酒洗，黑豆汤再洗。煨用（鸠鸟多栖 \n其树，故宜洗净）。",g:"其他"},
  "大蒜":{o:"大蒜",c:"\\x张骞使西域，始得种入中国，故一名葫\\x \n宣，通窍，辟恶 \n辛温。开胃健脾，通五脏，达诸窍（凡极臭极香之物，皆能通窍），去寒湿，解暑气， \n辟瘟疫，消痈肿（捣烂，麻油调敷），破症积，化肉食，杀蛇虫蛊毒。治中暑不醒（捣，和 \n地浆温服），鼻衄不止（捣，贴足心，能引热下行），关格不通（捣，纳肛中，能通幽门）。 \n敷脐能达下焦，消水，利大、小便。切片，灼艾，灸（音九）一切痈疽，恶疮肿核。独头者 \n尤良（李迅曰∶痈疽着灸，胜于诸药。缘热毒中膈，上下不通，必得毒瓦斯发泄，然后解散。 \n初起便用独头大蒜，切片灸之，三壮一易，百壮为率。但头项以上，切不可灸，恐引气上， \n更生大祸也。史源曰∶有灸至八百壮",g:"补虚药"},
  "大蓟":{o:"大小蓟",c:"泻，凉血 \n甘温（《大明》曰凉）。皆能破血下气，行而带补。治吐衄肠痈，女子赤白浊，安胎（凉 \n血之功）。 \n小蓟力微，能破瘀生新，保精养血，退热补虚，不能如大蓟之消痈毒（丹溪曰∶小蓟治 \n下焦结热血淋。《本事方》∶一人冷气入阴囊，肿满疼痛，煎大蓟汁服，立瘥）。 \n两蓟相似，花如髻。大蓟茎高而叶皱，小蓟茎低而叶不皱，皆用根。",g:"止血药"},
  "大青":{o:"大青",c:"泻心胃热毒 \n微苦咸，大寒。解心胃热毒。 \n治伤寒，时疾热狂，阳毒发斑（热甚伤血，里实表虚，则发斑。轻如疹子，重如锦纹。 \n紫黑者，热极而胃烂也，多死。《活人书》∶治赤斑烦痛，有犀角大青汤），黄胆热痢，丹 \n毒喉痹。 \n处处有之。高二三尺，茎圆叶长，叶对节生，八月开小红花成簇，实大如椒，色赤。用 \n茎叶。",g:"其他"},
  "大风子":{o:"大风子",c:"燥痰，外用治疮 \n辛热有毒。取油治疮癣疥癞，有杀虫劫毒之功（丹溪曰∶粗工治大风病，佐以大风油， \n殊不知此物性热，有燥痰之功而伤血，至有病将愈而先失明者）。出南番。子中有仁，白色 \n，久则油黄，不可用。入丸药，压去油。",g:"驱虫药"},
  "大麦芽":{o:"大麦芽",c:"开胃健脾，行气消积 \n咸温。能助胃气上行，而资健运，补脾宽肠，和中下气，消食除胀，散结祛痰（咸能软 \n坚），化一切米、面、果、食积，通乳下胎（《外台方》∶麦芽一升、蜜一升服，下胎神验。 \n薛立斋治一妇人，丧子乳胀，几欲成痈，单用麦芽一二两炒，煎服立消，其破血散气如此。 \n《良方》云∶神曲亦下胎，皆不可轻用）。久服消肾气（王好古曰∶麦芽，神曲，胃虚人宜 \n服之，以伐戊己，腐熟水谷。李时珍曰∶无积而服之，消人元气。与白术诸药，消补兼施， \n则无害也。胃为戊土，脾为己土）。炒用。豆蔻、砂仁、乌梅、木瓜、芍药、五味为使。",g:"补虚药"},
  "大麻仁":{o:"大麻仁",c:"\\x大麻，即作布之麻，俗作火麻\\x \n润燥滑肠 \n甘平滑利。脾、胃、大肠之药，缓脾润燥。治阳明病、胃热汗多而便难（三者皆燥也， \n汗出愈多，则津枯而大便愈燥。张仲景治脾约有麻仁丸。成无己曰∶脾欲缓，急食甘以缓之 \n，麻仁之甘，以缓脾润燥。张子和曰∶诸燥皆三阳病），破积血，利小便，通乳催生。又木 \n谷也，亦能治风。极难去壳，帛裹置沸汤，待冷，悬井中一夜，晒干，就新瓦上 去壳，捣 \n用。畏茯芩、白薇、牡蛎。",g:"其他"},
  "大黄":{o:"大黄",c:"大泻血分湿热，下有形积滞 \n大苦大寒。入足太阴（脾），手足阳明、厥阴（大肠、胃、心包、肝）血分。其性浮而 \n不沉，其用走而不守。若酒浸，亦能引至高之分（仲景太阳门调胃承气汤，大黄注曰酒浸； \n阳明门大承气汤，大黄注曰酒洗；少阳阳明小承气汤，大黄不用酒制，皆有分别。东垣曰∶ \n邪气在上，非酒不至。若用生者，则遗至高之邪热。病愈后，或目赤、喉痹、头痛、膈上热 \n疾生也）。用以荡涤肠胃，下燥结而除瘀热。 \n治伤寒时疾，发热谵语（大肠有燥粪，故谵语，宜下之。谵，音占），温热瘴疟，下痢 \n赤白，腹痛里急，黄胆水肿，症瘕积聚（积久成形谓之积，属阴；聚散无常谓之聚，属阳。 \n积多是血或食或痰，聚多是气），留",g:"泻下药"},
  "天仙藤":{o:"天仙藤",c:"通，活血，消肿 \n苦温。疏气活血。治风劳腹痛，妊娠水肿（有天仙藤散，专治水肿）。 \n叶似葛，圆而小，有白毛，根有须，四时不凋（一云即青木香藤）。",g:"活血化瘀药"},
  "天冬":{o:"天门冬",c:"泻肺火，补肾水，润燥痰 \n甘苦大寒，入手太阴（肺）气分，清金降火，益水之上源（肺为肾母），下通足少阴肾 \n（苦能坚肾，寒能去肾家湿热，故亦治骨痿）。滋肾润燥，止渴消痰（《蒙筌》曰∶肾主津液， \n燥则凝而为痰，得润剂则痰化，所谓治痰之本也），泽肌肤，利二便。 \n治肺痿肿痈（肺痿者，属于风寒咳嗽，短气鼻塞胸胀，久而成痿，有寒痿、热痿二证。 \n肺痈者，热毒蕴结，咳吐脓血，胸中隐痛。痿重而痈稍轻。治痿宜养血、补气、保肺、清火 \n；治痈宜泻热、豁痰、开提、升散。痈为邪实，痿为正虚，不可误治），吐脓吐血（苦泄血 \n滞，甘益元气，寒止血妄行），痰嗽喘促，消渴嗌干（烦渴引饮，多食善饥，为消渴，由火 \n盛津枯）",g:"补虚药"},
  "天南星":{o:"天南星",c:"燥湿，宣，祛风痰 \n味辛而苦，能治风散血（《是斋方》∶南星、防风等分为末，治破伤风、刀伤、扑伤如 \n神，名玉真散。破伤风者，药敷疮口，温酒调下二钱；打伤至死，童便调灌二钱，连进三服 \n必活）；气温而燥，能胜湿除痰；性紧而毒，能攻积拔肿，补肝风虚（凡味辛而散者，皆能 \n补肝，木喜条达故也），为肝、脾、肺三经之药。 \n治惊痫风眩（丹溪曰∶无痰不作眩），身强口噤，喉痹舌疮，结核疝瘕，痈毒疥癣，蛇 \n虫咬毒（调末箍之），破结下气，利水堕胎，性更烈于半夏（与半夏皆燥而毒，故堕胎。半 \n夏辛而能守，南星辛而不守。然古安胎方中，亦有用半夏者）。阴虚燥痰禁用。 \n根似半夏而大，形如虎掌，故一名虎掌。以矾汤或皂",g:"化痰止咳平喘药"},
  "天竹黄":{o:"天竹黄",c:"泻热，豁痰，凉心 \n甘而微寒。凉心经，去风热，利窍豁痰，镇肝明目。功同竹沥，而性和缓，无寒滑之患 \n。治大人中风不语，小儿客忤惊痫为尤宜。出南海。大竹之津气结成（即竹内黄粉），片片 \n如竹节者真。",g:"其他"},
  "天花粉":{o:"天花粉",c:"泻火，润燥，治热 \n酸能生津，甘不伤胃，微苦微寒。降火润燥，滑痰解渴（古方多用治消渴），生肌排脓， \n消肿，行水通经，止小便利，（膀胱热解，则水行而小便不数）。 \n治热狂时疾，胃热疸黄，口燥唇干，肿毒发背，乳痈疮痔。脾胃虚寒者禁用。 \n即栝蒌根，畏恶同。澄粉食，大宜虚热人。",g:"清热药"},
  "天麻":{o:"天麻",c:"宣，祛风 \n辛温，入肝经气分。益气强阴，通血脉，强筋力，疏痰气。 \n治诸风眩掉，头旋眼黑，语言不遂，风湿 （音顽）痹，小儿惊痫（诸风掉眩，皆属肝 \n木。肝病不能荣筋，故见前症。天麻入厥阴而治诸疾，肝气和平，诸疾自瘳）。血液衰少及 \n类中风者忌用（风药能燥血故也。昂按∶风药中须兼养血药，制其燥也。养血药或兼搜风药， \n宣其滞也。古云；治风先治血，血行风自灭）。 \n根类黄瓜，茎名赤箭，有风不动，无风反摇，一名定风草。明亮坚实者佳，湿纸包煨熟 \n，切片，酒浸一宿焙用。",g:"平肝息风药"},
  "太阴玄精石":{o:"太阴玄精石",c:"泻热，补阴 \n太阴之精，咸寒而降。治上盛下虚，救阴助阳，有扶危拯逆之功（正阳丹，用治伤寒壮 \n热。来复丹，用治伏暑热泻）。出解池、通泰积盐处，咸卤所结，青白莹彻，片皆六棱者良 \n。今世用者，多是绛石。",g:"其他"},
  "女贞子":{o:"女贞子",c:"平补肝肾 \n甘苦而平。少阴之精，隆冬不雕。益肝肾，安五脏，强腰膝，明耳目，乌髭发，补风虚 \n，除百病（女贞酒蒸，晒干，二十两，桑椹干十两，旱莲草十两，蜜丸，治虚损百病。如四 \n月即捣桑椹汁，七月即捣旱莲汁，和药，不必用蜜。时珍曰∶女贞子上品妙药，古方罕用何 \n哉）。 \n女贞、冬青，《本草》作二种，实一物也。冬至采佳。酒蒸用（近人放蜡虫于此树）。",g:"补虚药"},
  "姜黄":{o:"姜黄",c:"泻，破血，行气 \n苦辛（《本草》大寒。藏器、《大明》曰热）色黄，入脾兼入肝经。理血中之气，下气破 \n血，除风消肿，功力烈于郁金。 \n治气胀血积，产后败血攻心，通月经，疗扑损。片子者能入手臂，治风寒湿痹（血虚臂 \n痛者勿用。时珍曰∶入臂治痛，其兼理血中之气可知）。 \n出川广（陈藏器曰∶郁金苦寒色赤，姜黄辛温色黄）术味苦色青，三物不同，所用各别。 \n《经疏》曰∶姜黄主治，介乎三棱、郁金之间。时珍曰∶姜黄、郁金、莪术、形状不同， \n大略相近。但郁金入心，专治血；姜黄入脾，兼治血中之气；术入肝，治气中之血，稍为不 \n同。今时以扁如干姜者，为片子姜黄。圆如蝉腹者，为蝉肚郁金，并可染色，术形虽似郁金， \n",g:"活血化瘀药"},
  "威灵仙":{o:"威灵仙",c:"宣，行气，祛风 \n辛泄气，咸泄水（《本草》苦，元素甘），气温属木。其性善走，能宣疏五脏，通行十二 \n经络。 \n治中风痛风，头风顽痹（湿热流于肢节之间，肿属湿，痛属热，汗多属风，麻属气虚， \n木属湿痰死血。十指麻木，亦是胃中有湿痰死血，脾主四肢故也。痛风当分新久，新痛属寒 \n，宜辛温药；久痛属热，宜清凉药。河间所谓暴病非热，久病非寒是也。大法宜顺气、清痰 \n、搜风、散湿、养血、去瘀为要。威灵仙传曰∶一人手足不遂数十年，遇新罗僧曰，得一药 \n可治，入山求之，乃威灵仙也，服之而愈），症瘕积聚，痰水宿脓，黄胆浮肿，大小肠秘， \n风湿痰气，一切冷痛。性极快利，积 不痊者，服之有捷效。然疏泄真气，弱者慎用",g:"祛风湿药"},
  "孩儿茶":{o:"孩儿茶",c:"泻热，生津，涩，收湿 \n苦涩、清上膈热，化痰生津，止血收湿，定痛生肌。涂金疮口疮（硼砂等分），阴疳痔 \n肿。出南番，云是细茶末。纳竹筒，埋土中，日久取出，捣汁熬成。块小、润泽者上，大而 \n枯者次之。",g:"化痰止咳平喘药"},
  "密蒙花":{o:"密蒙花",c:"润肝，明目 \n甘而微寒。入肝经气血分。润肝燥。治目中赤脉、青盲肤翳，赤肿眵（音鸱。眼脂）泪， \n小儿疳气攻眼。产蜀中。叶冬不雕，其花繁密蒙茸，故名。拣净，酒浸一缩，候干，蜜拌蒸 \n，晒三次。",g:"清热药"},
  "密陀僧":{o:"密陀僧",c:"重，镇惊，劫痰，消积 \n辛咸小毒。感银铅之气而结。坠痰镇惊，止血散肿，消积杀虫，疗肿毒，愈冻疮（用桐 \n油调敷），解狐臭（油调搽腋。以馒头蒸热劈开，掺末夹腋下亦佳），染髭须。出银坑难得， \n今用者乃倾银 底。入药煮一伏时。",g:"安神药"},
  "射干":{o:"射干",c:"泻火，解毒，散血，消痰 \n苦寒有毒。能泻实火，火降则血散肿消，而痰结自解，故能消心、脾老血，行太阴（肺 \n、脾）、厥阴（肝）之积痰。 \n治喉痹、咽痛，为要药（擂汁醋和，噙之引涎。《千金方》∶治喉痹，有乌扇膏），治结 \n核瘕疝，便毒疟母（鳖甲煎丸，治疟母用之，皆取其降厥阴相火也）。通经闭，利大肠，镇 \n肝明目。 \n扁竹花根也（叶横铺，如乌羽及扇，故一名乌扇，乌 ），泔水浸一日， 竹叶煮半日 \n用。",g:"清热药"},
  "小麦":{o:"小麦",c:"补 \n味甘微寒。养心除烦，利溲止血（李时珍曰∶《素问》麦属火，心之谷也；郑玄谓属木 \n；许慎谓属金；《别录》云养肝，与郑说合；孙思邈云养心，与《素问》合，当以《素问》 \n为准。按∶麦，秋种夏熟，备受四时之气。南方地暖下湿，不如北产者良。张仲景治妇人脏 \n躁证，悲伤欲绝，状若神灵，用甘麦大枣汤。大枣十枚，小麦一升，甘草一两，每服一两， \n亦补脾气。《圣惠方》∶小麦饭治烦热。少睡，多渴）。 \n面粉甘温。补虚养气，助五脏，浓肠胃，然能壅气作渴，助湿发热。陈者良（寒食日， \n纸袋盛，悬风处，名寒食面，年久不热，入药尤良）。 \n浮小麦（即水淘浮起者）咸凉。止虚汗盗汗，劳热骨蒸（汗为心液，麦为心谷，浮者无",g:"其他"},
  "山慈菇":{o:"山慈菇",c:"泻热，解毒 \n甘微辛，有小毒。功专清热散结。 \n治痈疮疔肿，瘰 结核（醋磨涂）。解诸毒、虫毒、蛇、虫、狂犬伤。 \n根与慈菇、小蒜相类，去毛壳用（玉枢丹中用之。《广笔记》云∶出处州遂昌县洪山， \n无毛，云真者有毛，误也）。",g:"清热药"},
  "山柰":{o:"山柰",c:"宣，温中，辟恶 \n辛温。暖中辟恶。 \n治心腹冷痛，寒湿霍乱，风虫牙痛。 \n生广中，据叶皆如生姜，入合诸香用。",g:"温里药"},
  "山楂":{o:"山查",c:"\\x查，古字作楂\\x \n泻滞气，消积，散瘀，化痰 \n酸甘咸温。健脾行气，散瘀化痰，消食磨积（消油腻、腥膻之积，与麦芽消壳积者不同 \n。凡煮老鸡硬肉，投数枚则易烂，其消肉积可知）。发小儿痘疹，止儿枕作痛（恶露积于太 \n阴，少腹作痛，名几枕痛。沙糖调服）。多食令人嘈烦易饥，反伐脾胃生发之气（破泄太过， \n中气受伤，凡服人参不相宜者，服山楂即解。一补气，一破气也）。有大、小二种，小者入 \n药，一名棠球子。去皮、核用（一云核亦有力，化食磨积）。",g:"消食药"},
  "山茱萸":{o:"山茱萸",c:"补肝肾，涩精气 \n辛温酸涩。补肾温肝（入二经气分）。固精秘气，强阴助阳，安五脏，通九窍（《圣济》 \n云∶如何涩剂以通九窍？《经疏》云∶精气充则九窍通利。昂按∶山茱萸通九窍，古今疑之 \n，得《经疏》一言，而意旨豁然。始叹前人识见深远，不易测识，多有如此类者，即《经疏 \n》一语而扩充之，实可发医人之慧悟也），暖腰膝，缩小便。 \n治风寒湿痹（温肝故能逐风），鼻塞目黄（肝虚邪客，则目黄），耳鸣耳聋（肾虚则耳鸣 \n耳聋，皆固精通窍之功。王好古曰∶滑则气脱，涩剂所以收之，仲景八味丸用之为君，其性 \n味可知矣。昂按∶《别录》、甄权皆云能发汗，恐属误文。酸剂敛涩，何以反发？仲景亦安取 \n发汗之药为君乎？李士材",g:"收涩药"},
  "山茶花":{o:"山茶花",c:"泻，凉血 \n甘微辛寒。色赤，入血分。治吐衄肠风。麻油调末，涂汤火伤。用红者为末，入童便、 \n姜汁、酒调服，可代郁金。",g:"清热药"},
  "山药":{o:"山药",c:"\\x古名薯蓣\\x \n补脾肺，涩精气 \n色白入肺，味甘归脾。入脾、肺二经，补其不足，清其虚热（阴不足则内热，补阴故能 \n清热）。固肠胃，润皮毛，化痰涎，止泻痢（渗湿故化痰止泻。《百一方》∶山药半生半炒， \n米饮下。治噤口痢）。肺为肾母，故又益肾强阴，治虚损劳伤（王履云∶八味丸用之以强阴） \n；脾为心子，故又益心气（子能令母实），治健忘遗精（昂按∶山药性涩，故治遗精泄泻， \n而诸家俱未言涩）。生捣，敷痈疮，消肿硬（山药能消热肿，益补其气，则邪滞自行。丹溪 \n云∶补阳气生者，能消肿硬是也）。色白而坚者入药。",g:"补虚药"},
  "山豆根":{o:"山豆根",c:"泻热，解毒 \n苦寒。泻心火以保金气，去肺，大肠之风热（心火降，则不灼肺而金清。肺与大肠相表 \n里，肺金清，则大肠亦清），消肿止痛。 \n治喉痈喉风，龈肿齿痛（含之咽汁），喘满热咳，腹痛下痢，五痔诸疮。解诸药毒，敷 \n秃疮、蛇狗蜘蛛伤，疗人、马急黄（血热极所致）。 \n苗蔓如豆，经冬不凋。",g:"清热药"},
  "川芎":{o:"芎",c:"补血润燥，宣，行气搜风 \n辛温升浮。为少阳（胆）引经，入手、足厥阴（心包、肝）气分，乃血中气药。助清阳 \n而开诸郁（丹溪曰∶气升则郁自降，为通阴阳血气之使），润肝燥而补肝虚（肝以泻为补， \n所谓辛以散之，辛以补之），上行头目，下行血海（冲脉），搜风散瘀，止痛调经。 \n治风湿在头，血虚头痛（能引血下行，头痛必用之。加各引经药，太阳羌活，阳明白芷 \n，少阳柴胡，太阴苍术，少阴细辛，厥阴吴茱萸。丹溪曰∶诸经气郁，亦能头痛），腹痛胁 \n痛，气郁血郁，湿泻血痢，寒痹筋挛，目泪多涕（肝热），风木为病（诸风掉眩，皆属肝木）。 \n及痈疽疮疡（痈从六腑生，疽从五脏生，皆阴阳相滞而成。气为阳，血为阴，血行脉中， ",g:"活血化瘀药"},
  "巴戟天":{o:"巴戟天",c:"补肾，祛风 \n甘辛微温。入肾经血分、强阴益精，治五劳七伤；辛温散风湿，治风气、香港脚、水肿。 \n根如连珠。击破中紫而鲜洁者，伪也。中虽紫，微有白糁粉色而理小暗者，真也。蜀产 \n佳（山 根似巴戟，但色白，人或醋煮以乱之）。去心，酒浸焙用。复盆子为使。恶丹参。",g:"补虚药"},
  "巴豆":{o:"巴豆",c:"大燥，大泻 \n辛热有大毒。生猛而熟少缓。可升可降，能止能行，开窍宣滞，去脏腑沉寒，最为斩关 \n夺门之将。破痰癖血瘕，气痞食积，生冷硬物所伤，大腹水肿，泻痢惊痫，口 耳聋，牙痛 \n喉痹（缠喉急痹，缓治则死。用解毒丸，雄黄一两，郁金一钱，巴豆十四粒，去皮油，为丸 \n。每服五分，津咽下。雄黄破结气，郁金散恶血，巴豆下稠涎，然系厉剂，不可轻用。或用 \n纸拈蘸巴豆油，燃火刺喉；或捣巴豆，绵裹，随左、右纳鼻中，吐出恶涎，紫血即宽。鼻虽 \n小，生疮无碍）。其毒性又能解毒、杀虫，疗疮疡、蛇蝎诸毒。峻用大可劫病，微用亦可和 \n中。通经烂胎（巴豆禀火烈之气，烂人肌肉。试以少许擦皮肤，即发一泡，况肠胃耶，不可 \n轻",g:"泻下药"},
  "常山":{o:"常山",c:"宣，吐痰，截疟，通，行水 \n辛苦而寒，有毒。能引吐行水，祛老痰积饮（痰有六∶风痰、寒痰、湿痰、热痰、食痰 \n、气痰也。饮有五，流于肺为支饮，于肝为悬饮，于心为伏饮，于经络为溢饮，于肠胃为痰 \n饮也。常山力能吐之，下之），专治诸疟。然悍暴能损真气，弱者慎用（时珍曰∶常山蜀漆， \n韧痰截疟，须在发散表邪及提出阳分之后用之。疟有经疟、脏疟、风、寒、暑、湿、痰、食 \n、瘴、鬼之别，须分阴、阳、虚、实，不可概论。常山蜀漆，得甘草则吐，得大黄则利，得 \n乌梅、穿山甲则入肝，得小麦、竹叶则入心，得秫米、麻黄则入肺，得龙骨、附子则入肾， \n得草果、槟榔则入脾。盖无痰不作疟，一物之功，亦在驱逐痰水而已。李士材曰",g:"其他"},
  "干姜":{o:"干姜、黑姜",c:"燥，回阳，宣，通脉 \n生用辛温，逐寒邪而发表。炮则辛苦大热，除胃冷而守中（辛则散，炮则稍苦，故止而 \n不移，非若附子走而不守）。温经止血（炮黑止吐衄诸血，红见黑则止也），定呕消痰，去脏 \n腑沉寒痼冷。能去恶生新，使阳生阴长，故吐衄下血，有阴无阳者宜之。亦能引血药入气分 \n而生血，故血虚发热、产后大热者宜之（此非有余之热，乃阴虚生内热也，忌用表药寒药。 \n干姜能入肺，利气；能入肝，引血药生血，故与补阴药同用。乃热因热用，从治之法，故亦 \n治目睛久赤）。引以黑附，能入肾而祛寒湿，能回脉绝无阳（仲景四逆、白通、姜附汤，皆 \n用之）。同五味利肺气而治寒嗽（肺恶寒）。燥脾湿而补脾（脾恶湿），通心助阳而补",g:"温里药"},
  "庵子":{o:"庵子",c:"泻，行水，散血 \n苦辛微寒（《别录》微温）。入肝经血分。行水散血，散中有补。 \n治阳痿经涩，腰、膝、骨节重痛，产后血气作痛，闪锉折伤（扑打方多用之）。能制蛇 \n（见之则烂）。 \n叶似菊而薄，茎似艾而粗。薏苡为使。",g:"其他"},
  "延胡索":{o:"延胡索",c:"宣，活血，利气 \n辛苦而温。入手足太阴（肺、脾）、厥阴（心包、肝）经。能行血中气滞，气中血滞， \n通小便，除风痹。 \n治气凝血结，上下内外诸痛（通则不痛），症瘕崩淋，月候不调（气血不和，因而凝滞， \n不以时至），产后血晕，暴血上冲，折伤积血，疝气危急，为活血、利气第一药。然辛温走 \n而不守（独用力迅，宜兼补气血药），通经坠胎，血热、气虚者禁用。 \n根如半夏。肉黄、小而坚者良。酒炒行血，醋炒止血，生用破血，炒用调血。",g:"活血化瘀药"},
  "当归":{o:"当归",c:"补血，润燥，滑肠 \n甘温和血，辛温散内，苦温助心、散寒（诸血属心，凡通脉者，必先补心，当归苦温助 \n心）。入心、肝、脾（心生血，肝藏血，脾统血），为血中之气药。 \n治虚劳寒热，咳逆上气（血和则气降），温疟（厥阴肝邪） 痢（便血曰 ），头痛腰痛， \n心腹诸痛（散寒和气），风痉无汗（痉音擎上声。身强项直，角弓反张曰痉。无汗为刚痉， \n有汗为柔痉。当归辛散风，温和血。产后亦有发痉者，以脱血无以养筋也，宜十全大补汤）， \n痿痹症瘕（筋骨缓纵，足不任地曰痿；风寒湿客于肌肉、血脉曰痹；血凝气聚，按之坚硬曰 \n症；虽坚硬而聚散无常曰瘕，尚未至症也），痈疽疮疡，冲脉为病，气逆里急，带脉为病， \n腹痛腰溶溶如坐",g:"补虚药"},
  "御米壳":{o:"御米壳",c:"\\x即罂粟壳\\x \n涩肠，敛肺，固肾 \n酸涩微寒。敛肺涩肠而固肾。治久嗽泻痢，遗精脱肛，心腹筋骨诸痛（东垣曰∶收涩固 \n气，能入肾，故治骨病尤宜），嗽、痢初起者忌用（丹溪曰∶此是收后药，要先除病根）。一 \n名丽春花，红黄紫白，艳丽可爱。凡使壳，洗去蒂及筋膜，取薄皮。醋炒或蜜炒用（性紧涩 \n，不制多令人吐逆）。得醋、乌梅、陈皮良。罂中有米极细，甘寒润燥，煮粥食，治反胃（加 \n参尤佳）。",g:"收涩药"},
  "急流水":{o:"急流水",c:"通 \n性速而趋，下通二便，风痹药宜之（昔有病小便闭者，众不能瘥。张子和易以急流之 \n水，煎 \n前药一饮而溲。时珍曰∶天下之水，灭火濡枯则同。至于性从地变，质与物迁者，未尝同也）。",g:"其他"},
  "斑蝥":{o:"斑蝥",c:"大泻，以毒攻毒 \n辛寒有毒。外用蚀死肌，敷疥癣恶疮；内用破石淋，拔瘰 疔肿（杨登甫云∶瘰 之毒 \n，莫不有根。大抵治以斑蝥、地胆为主，制度如法，能令其根从小便出，如粉片血块烂肉， \n此其验也。以木通、滑石、灯心辈导之。斑蝥捕得，屁射出，臭不可闻。故奔走下窍，直至 \n精溺之处，能下败物，痛不可当，用须斟酌），下 犬毒（九死一生之候，急用斑蝥七枚， \n去头、翅、足，糯米炒黄，为末酒煎，空心下，取下小狗三四十枚，如数少再服。又方，糯 \n米一勺，斑蝥二十一枚，分三次，炒至青烟为度。去蝥，取米为粉，冷水入清油少许，空心 \n下。取利下毒物，如不利再进。愈后，忌闻钟鼓声，复发则不可治。服之肚痛急者，用靛汁 ",g:"活血化瘀药"},
  "旋覆花":{o:"旋复花",c:"\\x一名金沸草\\x \n泻、下气，消痰 \n咸能软坚，苦辛能下气行水，温能通血脉。入肺、大肠经。消痰结坚痞，唾如胶漆，噫 \n气不除（噫，于介切，俗作嗳。胸中气不畅，故嗳以通之，属不足。亦有挟痰挟火者，属有 \n余。仲景治汗、吐、下后，痞硬噫气，有代赭旋复汤），大肠水肿，去头目风。然走散之药， \n冷利大肠，虚者慎用。 \n类金钱菊，去皮带蕊壳蒸用，根能续筋（筋断者，捣汁滴伤处，用滓敷其上，半月不开 \n，筋自续矣）。",g:"化痰止咳平喘药"},
  "无名异":{o:"无名异",c:"重，和血，行伤 \n咸入血，甘补血。治金疮折伤，痈疽肿毒（醋磨涂），止痛生肌（人受杖时，须服三五 \n钱，不甚痛伤）。生川广。小黑石子也，一包数百枚。",g:"补虚药"},
  "旱莲草":{o:"旱莲草",c:"\\x一名鲤肠，又名金陵草\\x \n补肾 \n甘咸，汁黑。补肾止血，黑发乌髭（《千金》云∶当及时多收，其效甚速。《经疏》云 \n∶性凉不益脾胃，故《千金方》金陵煎丸用姜汁和剂）。 \n苗如旋复，实似莲房，断之有计，须臾而黑。熬膏良。",g:"其他"},
  "昆布":{o:"昆布",c:"功同海藻而少滑，性雄。治水肿瘿瘤，阴 膈噎（含之咽汁）。 \n出登莱者，搓如绳索；出闽越者，大叶如菜。洗去咸味用。",g:"化痰止咳平喘药"},
  "木槿":{o:"木槿",c:"泻热 \n苦凉。活血润燥。治肠风泻血，痢后热渴。作饮服，令人得睡。川产者治癣疮（癣疮有 \n虫，用川槿皮肥皂水浸，时时搽之，或浸汁磨雄黄尤妙）。用根、皮。",g:"活血化瘀药"},
  "木瓜":{o:"木瓜",c:"补，和脾，舒筋，涩，敛肺 \n酸涩而温。入脾、肺血分。敛肺和胃，理脾伐肝，化食（酸能敛，敛则化，与山查同） \n止渴（酸能生津），气脱能收，气滞能和，调营卫，利筋骨，去湿热，消水胀。 \n治霍乱转筋（夏月暑湿，邪伤脾胃。阳不升，阴不降，则挥霍撩乱，上吐下泻，甚则肝 \n木乘脾，而筋为之转也。《食疗》云∶煮汁饮良。时珍曰∶肝虽主筋，而转筋则因风寒湿热 \n，袭伤脾胃所致。转筋必起于足腓，腓，音肥，足肚也，腓及宗筋，皆属阳明。木瓜治转筋 \n，取其理筋以伐肝也。土病则金衰而木盛，故用酸温以收脾肺之耗散，而借其走筋以平肝邪 \n，乃土中泻木以助金也。陶宏景曰∶凡转筋呼木瓜名，写木瓜字，皆愈），泻痢香港脚（脾主 \n",g:"祛风湿药"},
  "木贼":{o:"木贼",c:"轻，发汗，退目翳 \n温微甘苦。中空轻扬，与麻黄同形、性；亦能发汗解肌，升散火郁、风湿，入足厥阴， \n少阳血分。益肝胆。 \n治目疾，退翳膜（翳乃肝邪郁遏，不能上通于目），及疝痛脱肛，肠风痔 ，赤痢崩中 \n诸血病。",g:"解表药"},
  "木通":{o:"木通",c:"\\x古名通草\\x \n轻，通，行水，泻小肠火 \n甘淡轻虚。上通心包，降心火，清肺热（心火降。则肺热清矣），化津液（肺为水源， \n肺热清，则津液化，水道通），下通大、小肠，膀胱，导诸湿热由小便出（故导赤散用之。 \n凡利小便者，多不利大便，以小水愈通，大便愈燥也。木通能入大肠，兼通大便），通利九 \n窍，血脉关节。 \n治胸中烦热，遍身拘痛（杨仁斋云∶遍身隐热、疼痛拘急、足冷，皆伏热伤血。血属于 \n心，宜木通以通心窍，则经络流行也），大渴引饮（中焦火），淋沥不通（下焦火，心与小肠 \n相表里，心移热于小肠，则淋秘），水肿浮大（利小便），耳聋（泄肾火，通窍）目眩，口燥 \n舌干（舌为心苗），喉痹咽痛（火炎上焦",g:"利水渗湿药"},
  "木香":{o:"木香",c:"宣，行气 \n辛苦而温。三焦气分之药，能升降诸气，泄肺气，疏肝气，和脾气（怒则肝气上，肺气 \n调，则金能制木而肝平，木不克土而脾和）。 \n治一切气痛，九种心痛（皆属胃脘，曰寒痛、热痛、气痛、血痛、湿痛、痰痛、食痛、 \n蛔痛、悸痛。盖君心不易受邪，真心痛者，手足冷过腕节，朝发夕死），呕逆反胃，霍乱泻 \n痢，后重（同槟榔用。刘河间曰∶痢疾行血则脓血自愈，调气则后重自除）癃闭，痰壅气结， \n癖症块，肿毒虫毒，冲脉为病，气逆里急。杀鬼物，御瘴雾，去腋臭，宽大肠，消食安胎 \n（气逆则胎不安）。过服损真气（丹溪曰∶味辛气升，若阴火冲上者，反助火邪，当用黄柏 \n知母，少以木香佐之。王好古曰∶《本草》主气劣、气",g:"理气药"},
  "木鳖子":{o:"木鳖子",c:"泻热，外用治疮 \n苦温微甘。有小毒，利大肠。 \n治泻痢疳积，瘰 疮痔，乳痈蚌毒。消肿追毒，生肌除 （音旱，黑斑），专入外科。 \n核扁如鳖，绿色。拣去油者，能毒狗。",g:"其他"},
  "本":{o:"本",c:"宣，去风寒湿 \n辛温雄壮，为太阳经（膀胱）风药，寒郁本经、头痛连脑者必用之（凡巅顶痛，宜 本、 \n防风、酒炒升、柴）。治督脉为病，脊强而厥（督脉并太阳经贯脊）；又能下行去湿，治妇人 \n疝瘕，阴寒肿痛，腹中急痛（皆太阳寒湿），胃风泄泻（夏英公病泄，医以虚治不效。霍翁 \n曰∶此风客于胃也，饮以 本汤而愈。盖 本能除风湿耳），粉刺酒 （音查，和白芷作面 \n脂良）。 \n根紫色似芎 而轻虚，气香味麻。",g:"其他"},
  "杉木":{o:"杉木",c:"宣，散肿胀 \n辛温。去恶气，散风毒。治香港脚肿痛，心腹胀满，洗毒疮（柳子浓纂《救死方》云∶得 \n香港脚夜半痞绝，胁块如石，昏困且死。郑洵美传杉木汤，食顷大下，块散气通。用杉木节一 \n升，橘叶一升，无叶以皮代，大腹槟榔七枚，连子槌碎，童便三升煮，分二服。若一服得快 \n利，即停后服）。有赤、白二种，赤、油斑如野鸡者，作棺尤贵。性直，烧炭最发火药。",g:"其他"},
  "杜仲":{o:"杜仲",c:"补腰膝 \n甘温能补，微辛能润。色紫入肝经气分。润肝燥，补肝虚。子能令母实，故兼补肾。肝 \n充则筋健，肾充则骨强，能使筋骨相着（皮中有丝，有筋骨相着之象）。 \n治腰膝酸痛（经曰∶腰者肾之府，转移不能，肾将惫矣；膝者筋之府，屈伸不能，筋将 \n惫矣。一少年新娶，得脚软病，且痛甚，作香港脚治，不效。孙林曰∶此肾虚也。用杜仲一两 \n，半酒半水煎服，六日全愈。按∶腰痛不已者，属肾虚；痛有定处，属死血；往来走痛，属 \n痰；腰冷身重、遇寒即发，属寒湿；或痛或止，属湿热，而其原多本于肾虚，以腰者肾之府 \n也），阴下湿痒，小便余沥，胎漏（怀孕沥血）胎坠（惯坠胎者，受孕一、两月，用杜仲八 \n两，糯米煎汤浸透，炒断丝",g:"补虚药"},
  "松节":{o:"松节",c:"燥湿，去风 \n松之骨也，坚劲不凋，故取其苦温之性，以治骨节间之风湿（丹溪曰∶能燥血中之湿）。 \n杵碎浸酒良（史国公药酒中用之）。 \n松脂 苦甘性燥。祛风去湿，化毒杀虫，生肌止痛。养生家炼之服食，今熬膏多用之（ \n龋齿有孔，松脂 塞，虫即从脂出）。 \n松毛 酿酒（煮汁代水），亦治风痹香港脚。",g:"祛风湿药"},
  "枇杷叶":{o:"枇杷叶",c:"泻肺降火 \n苦平。清肺和胃而降气，气下则火降痰消（气有余便是火，火则生痰）。治热咳、呕逆、 \n口渴（时珍曰∶火降痰顺，则逆者不逆，呕者不呕，咳者不咳，渴者不渴矣。一妇肺热久嗽 \n，身如火炙，肌瘦将成劳。以枇杷叶、款冬花、紫菀、杏仁、桑皮、木通等分，大黄减半， \n蜜丸樱桃大。食后、夜卧各含化一丸，未终剂而愈）。叶湿重一两，干重三钱为气足，拭净 \n毛（毛射肺，令人咳）。治胃病，姜汁炙；治肺病，蜜炙。",g:"化痰止咳平喘药"},
  "枫脂香":{o:"枫脂香",c:"\\x即白胶香\\x \n宣，调气血 \n苦平。活血解毒，止痛生肌。治血衄咯血，齿痛风疹，痈疽金疮。外科要药。色白微黄 \n，能乱乳香，功颇相近。",g:"清热药"},
  "枳子":{o:"枳子",c:"\\x一名木蜜\\x \n润，解酒 \n甘平。止渴除烦，润五脏，解酒毒（葛根解酒毒，而发散不如枳 。屋外有枳 树，屋 \n内酿酒多不佳。赵以得治酒毒、房劳病热者，加葛根于补气血药中，一贴微汗，反解怠，热 \n如故。知气血虚，不禁葛根之散也，必得枳 方可，偶得干者加入即愈。《东坡集》曰∶杨 \n颖臣病消渴，日饮水数斗，饭亦倍进，小便频数，服消渴药，日甚。延张肱诊之，笑曰∶君 \n几误死，取麝香当门子，以酒濡作十许丸，枳 子煎汤吞之遂愈。问其故，肱曰∶消渴消中 \n，皆脾弱肾败、土不制水而成。今颖臣脾脉极热，肾脉不衰，当由酒果过度，积热在脾，所 \n以多食多饮，饮多溲不得不多，非消非渴也。麝香坏酒果，枳 能胜酒，故假",g:"补虚药"},
  "枳实、枳壳":{o:"枳实、枳壳",c:"泻，破气，行痰。枳实小，枳壳大 \n苦酸微寒。其功皆能破气。气行则痰行喘止，痞胀消（脾无积血；心下不痞；浊气在上 \n，则生腹胀。东垣曰∶枳实治下而主血，枳壳治上而主气），痛刺息，后重除。 \n治胸痹结胸，食积五膈，痰癖症结，呕逆咳嗽，水肿胁胀（肝郁），泻痢淋闭，痔肿肠 \n风。除风去痹（辛散风），开胃健脾。所主略同，但枳实利胸膈，枳壳宽肠胃。枳实力猛（大、 \n小承气汤皆用之。丹溪曰∶枳实泻痰，能冲墙倒壁），枳壳力缓为少异。孕妇及气虚人忌用 \n（按∶《本草》壳、实皆云明目。思之不得其解，然目疾方中多用之，岂以其破浊气？即能 \n升清气乎？《本经》又言枳实益气，想亦同此理也。故浓朴调中，亦有益气明目之文。",g:"补虚药"},
  "枸杞子":{o:"枸杞子",c:"平补而润 \n甘平（《本草》苦寒）。润肺清肝，滋肾益气，生精助阳，补虚劳，强筋骨（肝主筋，肾 \n主骨），去风明目（目为肝窍，瞳子属肾），利大小肠。治嗌干消渴（昂按∶古谚有云，出家 \n千里，勿食枸杞。其色赤属火，能补精壮阳。然气味甘寒而性润，仍是补水之药，所以能滋 \n肾、益肝、明目而治消渴也）。 \n南方树高数尺，北方并是大树。以甘州所产、红润少核者良。酒浸捣用。根名地骨皮（ \n见下）。 \n叶，名天精草，苦甘而凉。清上焦心、肺客热，代茶止消渴（时珍曰∶皆三焦气分之药）。",g:"补虚药"},
  "柏子仁":{o:"柏子仁",c:"补心脾，润肝肾 \n辛甘而润。其气清香，能透心肾而悦脾（昂按∶凡补脾药多燥，此润药而香能舒脾，燥 \n脾药中兼用最良）。养心气，润肾燥，助脾滋肝（王好古曰∶肝经气分药），益智宁神（养心） \n，聪耳明目（甘益血，香通窍），益血止汗（心生血，汗为心液），除风湿。愈惊痫，泽皮肤， \n辟鬼魅。 \n炒研去油，油透者勿用。畏菊花。",g:"安神药"},
  "柴胡":{o:"柴胡",c:"宣，发表和里，退热升阳 \n苦平微寒，味薄气升为阳。主阳气下陷，能引清气上行，而平少阳、厥阴之邪热（肝、 \n胆、心包、三焦相火。时珍曰∶行少阳，黄芩为佐；行厥阴，黄连为佐），宣畅气血，散结 \n调经（昂按∶人第知柴胡能发表，而不知柴胡最能和里。故劳药、血药，往往用之。补中益 \n气汤，逍遥散，皆用柴胡，取其和中，皆非解表）。为足少阳（胆）表药（胆为清净之府， \n无出无入，其经在半表半里，法当和解，小柴胡汤之属是也。若病在太阳，服之太早，则引 \n贼入门；若病入阴经，复服柴胡，则重虚其表。最宜详慎）。 \n治伤寒邪热（仲景有大、小柴胡汤），痰热结实，虚劳肌热（寇宗 曰∶柴胡，《本经》 \n并无一字治劳，《药",g:"解表药"},
  "柿干":{o:"柿干",c:"润肺，涩肠，宁嗽 \n甘平性涩（生柿性寒）。脾、肺血分之药。健脾涩汤，润肺宁嗽，而消宿血。治肺痿热 \n咳，咯血反胃（有人三世病反胃，得一方，柿干同干饭日日食，不饮水，遂愈），肠风痔漏 \n（肺与大肠相表里，脏清则腑热亦除。《泊宅编》∶柿干烧灰饮，服二钱，治下血）。忌蟹。 \n柿霜乃其精液。生津化痰，清上焦心、肺之热为尤佳。治咽喉口舌疮痈。 \n柿蒂止呃逆（古方单用，取其苦温降气。《济生》加丁香、生姜，取其开郁散痰，亦从 \n治之法。《产宝》云∶产后呃逆、烦乱。柿饼一个，煮汁热饮）。",g:"补虚药"},
  "栀子":{o:"栀子",c:"泻心、肺、三焦之火 \n苦寒。轻飘象肺，色赤入心，泻心、肺之邪热，使之屈曲下行，从小便出（海藏曰∶或 \n用为利小便药，非利小便，乃肺清则化行，而膀胱津液之府，得此气化而出也），而三焦之 \n郁火以解，热厥（厥有寒、热二证）心痛以平（丹溪曰∶治心痛，当分新久。若初起因寒、 \n因食，宜当温散。久则郁而成热，若用温剂，不助痛添病乎？古方多用栀子为君，热药为之 \n响导，则邪易伏。此病虽日久，不食不死，若痛止恣食，病必再作也），吐衄、血淋、血痢 \n之病以息（最清胃脘之血。炒黑末服，吹鼻治衄。《本草汇》曰∶治实火之血，顺气为先， \n气行则血自归经；治虚火之血，养正为先，气壮则自能摄血。丹溪曰∶治血不可单行、单",g:"清热药"},
  "栗":{o:"栗",c:"补肾 \n咸温。浓肠胃，补肾气（寇宗 曰∶小儿不可多食。生则难化，熟则滞气。能解羊膻）。",g:"其他"},
  "桂心":{o:"桂心",c:"燥，补阳，活血 \n苦入心，辛走血。能引血、化汗、化脓，内托痈、疽、痘疮（同丁香，治痘疮灰塌）， \n益精明目，消瘀生肌，补劳伤，暖腰膝，续筋骨。 \n治风痹症瘕，噎膈腹满，腹内冷痛，九种心痛（一虫、二疰、三风、四悸、五食、六饮 \n、七冷、八热、九去来痛，皆邪乘于手少阴之络，邪正相激，故令心痛）。",g:"活血化瘀药"},
  "桂枝":{o:"桂枝",c:"轻，解肌，调营卫 \n辛甘而温，气薄升浮。入太阴肺、太阳膀胱经。温经通脉，发汗解肌（能利肺气。经曰 \n∶辛甘发散为阳）。 \n治伤风头痛（无汗能发），中风自汗（有汗能止。中，犹伤也，古文通用，自汗属阳虚。 \n桂枝为君，芍药，甘草为佐。加姜、枣名桂枝汤，能和营实表），调和营卫，使邪从汗 \n出，而汗自止。亦治手足痛风、胁风（痛风有风痰、风湿、湿痰、瘀血、气虚、血虚之异。 \n桂枝用作引经。胁风属肝，桂能平肝。东垣曰∶桂枝横行手臂，以其为枝也。又曰∶气薄则 \n发泄，桂枝上行而解表。气浓则发热，肉桂下行而补肾。王好古曰∶或问桂枝止烦出汗，仲 \n景治伤寒发汗，数处皆用桂枝汤。又曰无汗不得用桂枝，汗多者桂枝甘草",g:"解表药"},
  "桃仁":{o:"桃仁",c:"泻，破血，润燥 \n苦平微甘（孙思邈辛，孟诜温。孙思邈，着《千金方》，孟诜，着《食疗本草》）厥阴（ \n心包、肝）血分药。苦以泄血滞，甘以缓肝气新血（成无己曰∶肝者，血之源，血聚，则肝 \n气燥。肝苦急，宜急食甘以缓之）。通大肠血秘。 \n治热入血室（冲脉），血燥血痞，损伤积血。血痢经闭，咳逆上气（血和则气降），皮肤 \n血热，燥痒蓄血，发热如狂（仲景治膀胱蓄血，有桃仁承气汤即调胃承气汤加桃仁、桂枝。 \n抵当汤，用桃仁、大黄、虻虫、水蛭。水蛭，即马蟥。蛭食血之虫，能通肝经聚血，性最难 \n死。虽炙为末，得水即活，若入腹中，生子为患，田泥和水饮下之。虻虫即蚊虫，因其食血， \n故用以治血）。血不足者禁用。行血",g:"活血化瘀药"},
  "桑寄生":{o:"桑寄生",c:"补筋骨，散风湿 \n苦坚肾，助筋骨而固齿、长发（齿者骨之余，发者血之余）。甘益血，止崩漏而下乳、 \n安胎（三症皆由血虚）。外科散疮疡，追风湿。 \n他树多寄生，以桑上采者为真，杂树恐反有害。茎、叶并用。忌火。",g:"祛风湿药"},
  "桑白皮":{o:"桑白皮",c:"泻肺，行水，十剂作燥，以其行水也 \n甘辛而寒。泻肺火（罗谦甫曰∶是泻肺中火邪，非泻肺气也。火与元气不两立，火去则 \n气得安矣，故《本经》又云益气。东垣曰∶甘，固元气之不足而补虚。辛，泻肺气之有余而 \n止嗽。然性不纯良，不宜多用。钱乙泻白散，桑皮、地骨各一两，甘草五钱，每服二钱，入 \n粳米百粒煎。时珍曰∶桑皮、地骨，皆能泻火从小便出。甘草泻火缓中，粳米清肺养血，乃 \n泻肺诸方之准绳也。一妇，鼻久不闻香臭，后因他疾，缪仲醇为处方，每服桑皮至七八钱， \n服久而鼻塞忽通），利二便，散瘀血，下气行水，止嗽清痰（《发明》曰∶肺中有水，则生痰 \n而作嗽，除水气，正所以泻火邪，实则泻其子也。火退气宁，则补益在",g:"化痰止咳平喘药"},
  "桑螵蛸":{o:"桑螵蛸",c:"补肾 \n甘咸。入肝、肾、命门，益精气而固肾。治虚损阴痿，梦遗白浊，血崩腰痛，伤中疝瘕 \n（肝肾不足），通五淋，缩小便（能通故能缩。肾与膀胱相表里，肾得所养，气化则能出， \n故能通；肾气既固，则水道安常，故又能止也。寇宗 治便数，有桑螵蛸散，桑螵蛸、茯神、 \n远志、菖蒲、人参、当归、龙骨、鳖甲醋炙，各一两，为末。卧时，人参汤下二钱，能补心 \n安神，亦治健忘）。炙，饲小儿，止夜尿。螳螂卵也。桑树产者为好（房长寸许，有子如蛆， \n芒种后齐出，故仲夏螳螂生也。如用他树者，以桑皮佐之，桑皮善行水，能引达肾经）。炙 \n黄，或醋煮汤泡，煨用。畏旋复花（螳螂能出箭镞，螳螂一个，巴豆半个，研敷伤处。微痒 \n且忍",g:"收涩药"},
  "桔梗":{o:"桔梗",c:"宣通气血，泻火散寒，载药上浮 \n苦辛而平。色白属金，入肺（气分）泻热，兼入手少阴心、足阳明胃经。开提气血，表 \n散寒邪，清利头目咽喉，开胸膈滞气。 \n凡痰壅喘促、鼻塞（肺气不利）目赤、喉痹咽痛（两少阴火）、齿痛（阳明风热）口疮、 \n肺痈干咳（火郁在肺）、胸膈刺痛（火郁上焦）、下痢腹痛、腹满肠鸣（肺火郁于大肠），并 \n宜苦梗以开之。为诸药舟楫，载之上浮，能引苦泄峻下之剂。至于至高之分成功（既上行而 \n又能下气何也？肺主气，肺金清，浊气自下行耳），养血排脓，补内漏（故治肺痈。时珍曰∶ \n枳桔汤治胸中痞满不痛，取其通肺利膈下气也。甘桔汤通治咽喉口舌诸病，取其苦辛散寒、 \n甘平除热也。宋仁宗加荆芥、防",g:"化痰止咳平喘药"},
  "梨":{o:"梨",c:"润肠，泻火，清热 \n甘微酸寒。润肺凉心，消痰降火，止渴解酒，利大小肠。治伤寒发热，热嗽痰喘，中风 \n失音（捣汁频服。《圣惠方》梨汁煮粥，治小儿心脏风热昏躁）。切片，贴汤火伤。多食冷利 \n。脾虚泄泻及乳妇、血虚人忌之（生者清六腑之热，熟者滋五脏之阴。实火宜生，虚火宜熟 \n。《泊宅编》有仕宦病消渴，医谓不过三十日死。亟弃官归，途遇一医，令致北梨二担，食 \n尽则瘥。宦如其言，食及五六十枚而病愈。杨吉老介医木甚着，一士有疾，厌厌不聊，往谒 \n之。杨曰∶汝证热已极，气血全消，三年当以疽死，不可为也。士不乐而退，闻茅山一道士 \n，医术通神，但不肯以技自名。乃衣僮仆之服，诣山拜之，愿执役席下，道士喜留，只事",g:"清热药"},
  "棕榈":{o:"棕榈",c:"涩，止血 \n苦能泄热，涩可收脱，烧黑能止血（红见黑则止，不可烧过。棕榈、侧柏、卷柏烧存性 \n，饭丸，止远年下血。亦可煎服）。治吐衄下痢，崩带肠风，失血过多者，初起未可遽用。 \n年久败棕尤良。（与发灰同用更良）。",g:"其他"},
  "椿樗白皮":{o:"椿樗白皮",c:"涩肠，燥湿 \n苦燥湿，寒胜热，涩收敛。入血分而涩血。去肺、胃之陈痰。治湿热为病，泄泻久痢， \n崩带肠风，梦遗便数，有断下之功（痢疾滞气未尽者勿遽用，勉强固涩，必变他证），去疳 \n、樗皮尤良（时珍曰∶椿皮入血气而性涩；樗皮入气分而胜利。凡血分受病不足者宜椿皮； \n气分受病有郁者宜樗皮。《乾坤生意》治疮肿下药，用樗皮水研，服汁取利，是其验矣。昂 \n按∶樗皮止泻痢，终是涩剂。寇氏曰∶一妇年四十余，耽饮无度，多食鱼蟹，积毒在脏，日 \n夜二三十泻，便与脓血杂下，大肠连肛门甚痛。用止血痢药不效，用肠风药益甚，盖肠风有 \n血无脓也。服热药，腹愈痛，血愈下。服冷药，注泻食减。服温平药，则若不知，年余待毙 \n。",g:"化湿药"},
  "楮实":{o:"楮实",c:"平，补，助阳 \n甘寒。助阳气，起阴痿，补虚劳，壮筋骨，明目充肌（时珍曰∶《别录》、《大明》皆 \n云楮实大补益，而《修真秘书》又云久服令人骨痿，《济生秘览》治骨哽用楮实煎汤，岂非 \n软骨之征乎？《本草发明》甚言其功，而云今补药中罕用，惜未之察耳）。 \n取子浸去浮者，酒蒸用。 \n楮皮善行水。治水肿气满（皮可为纸。楮汁和白芨飞面，调糊接纸，永不解脱）。",g:"其他"},
  "榆白皮":{o:"榆白皮",c:"滑，利窍 \n甘滑下降。入大、小肠、膀胱经。行经脉、利诸窍，通二便，渗湿热，滑胎产（或胎死 \n腹中，服汁可下），下有形留着之物。治五淋肿满（《备急方》∶捣屑作粥食，小便利差）喘 \n咳不眠（嵇康《养生论》∶榆令人瞑），疗疥癣秃疮，消赤肿妒乳（乳痈汁不出，内结成肿， \n名妒乳。和陈醋滓调，日六七易效。《十剂》曰∶滑可去着，冬葵子、榆白皮之属是也）。 \n有赤白二种，去粗皮，取白用（采皮为面，荒年当粮可食。香剂以之调和，粘滑胜于胶漆）。",g:"其他"},
  "榧实":{o:"榧实",c:"润肺 \n甘涩。润肺（《本草》未尝言润，然润剂也。故寇氏云∶多食润肠）杀虫（有虫积者， \n宜上旬日日食之，食一斤，虫乃绝）。",g:"驱虫药"},
  "槐实":{o:"槐实",c:"\\x即槐角\\x \n泻风热，凉大肠 \n苦寒纯阴。入肝经气分。疏风热，润肝燥，凉大肠。 \n治烦闷风眩，痔血肠风（粪前有血名外痔，粪后有血名内痔，谷道 肉名举痔，头上有 \n孔名痔 ，疮内有虫名虫痔。大法用槐角、地榆、生地以凉血，芩、连、栀、柏以清热。防 \n风、秦艽以祛风湿，芎、归、人参以和血生血，枳壳以宽肠，升麻以升提。治肠风略同，不 \n宜专用寒凉，须兼补剂收功），阴疮湿痒，明目止泪（清肝，泪为肝热），固齿乌髭（十月上 \n已采，渍牛胆中，阴干百日。食后吞一枚，明目补脑，发白还黑，肠风痔血，尤宜服之）， \n杀虫（根、皮皆能洗痔）堕胎。 \n去单子及五子者，铜槌槌碎，牛乳拌蒸（槐乃虚星之精）。 \n槐花苦凉",g:"清热药"},
  "槟榔":{o:"槟榔",c:"泻气，行水，破胀，攻坚 \n苦温破滞，辛温散邪。泻胸中至高之气，使之下行。性如铁石，能坠诸药至于极下。攻 \n坚去胀，消食行痰，下水除风，杀虫醒酒。 \n治痰癖症结，瘴疠疟痢，水肿香港脚（香港脚冲心，尤须用之，童便、姜汁温酒调服）。治 \n大、小便气秘，里急后重（同木香用，木香能利气）。过服则损真气（岭南多瘴，以槟榔代 \n茶，其功有四∶醒能使醉，醉能使醒，饥能使饱，饱能使饥。然泄脏气，无瘴之地忌用）。 \n鸡心尖长，破之作锦纹者良（程星海曰∶阴毛生虱，也鲜良方，以槟榔煎水洗，即除。 \n又方，以心红擦之亦好）。",g:"驱虫药"},
  "樟脑":{o:"樟脑",c:"宣，通窍，除湿 \n辛热香窜，能于水中发火（置水中焰益炽）。通关利滞，除湿杀虫。置鞋中去香港脚（《集 \n要》曰∶和乌头为末，醋丸弹子大，置足心，微火烘之，汗出为效）熏衣箧，辟疰虫。以樟 \n木切片，浸水煎成。升打得法，能乱冰片。",g:"驱虫药"},
  "橄榄":{o:"橄榄",c:"宣，清肺 \n甘涩而温。肺、胃之果，清咽生津，除烦醒酒，解河豚毒（投入煮佳）及鱼骨鲠（如无 \n橄榄，以核磨水服。橄榄木作舟楫，鱼拨即浮出，物之相畏有如此者）。 \n核，烧灰，敷疰疳良。",g:"其他"},
  "檀香":{o:"檀香",c:"宣，理气 \n辛温。调脾肺，利胸膈，去邪恶，能引胃气上升，进饮食，为理气要药（《内典》云∶ \n旃檀涂身，能除热恼。昂按∶内兴欲念，亦称热恼。盖诸香多助淫火，惟檀香不然，故释氏 \n焚之。道书又以檀为俗香，不可以供上真）。",g:"理气药"},
  "款冬花":{o:"款冬花",c:"润肺，泻热，止嗽 \n辛温纯阳。泻热润肺，消痰除烦。定惊明目。 \n治咳逆上气，喘渴（肺虚挟火），喉痹，肺痿肺痈，咳吐脓血。为治嗽要药（烧烟以筒 \n吸之亦良。百合、款冬等分蜜丸，名百花膏，治咳嗽痰血。凡阴虚劳嗽，通用款冬、紫菀、 \n百部、百合、沙参、生地、麦冬、五味、知、柏、芩、芍。如内热骨蒸，加丹皮、地骨。若 \n嗽而复泻者，为肺移热于大肠，脏腑俱病。嗽而发热不止者，为阴虚火炎，皆难治），寒热 \n虚实，皆可施用（《本草汇》曰∶隆冬独秀，先春开放，得肾之体，先肝之用，故为温肺理 \n嗽之最。大抵咳必因寒，寒为冬气，入肺为逆。款冬非肺家专药，乃使肺邪从肾顺流而出。 \n肺恶寒。郭佩兰，着《本草汇》）。十一",g:"化痰止咳平喘药"},
  "水杨柳":{o:"水杨柳",c:"宣，行气血 \n苦平。痘疮顶陷，浆滞不起者，用枝煎汤浴之（此因气凝血滞，或风寒外束而热，得此 \n暖气透达，浆随暖而行，再用助气血药更效）。 \n枝，煎汁，治黄胆。",g:"理气药"},
  "水银":{o:"水银",c:"重，外用杀虫 \n辛寒，阴毒。功专杀虫。治疮疥虮虱（性滑重，且入肉。头疮切不可用，恐入经络，令 \n人筋骨拘挛），解金、银、铜、锡毒（能杀五金），堕胎绝孕。从丹砂烧 而出。畏磁石、砒 \n霜。得铅则凝，得硫则结，并枣肉入唾研则碎。散失在地者，以花椒、茶末收之。",g:"驱虫药"},
  "沉香":{o:"沉香",c:"重，宣，调气，补阳 \n辛苦性温。诸木皆浮，而沉香独沉，故能下气而坠痰涎（怒则气上，能平则下气）。能 \n降亦能升，气香入脾，故能理诸气而调中（东垣曰∶上至天，下至泉，用为使，最相宜）。 \n其色黑、体阳，故入右肾命门，暖精助阳。行气不伤气，温中不助火。 \n治心腹疼痛，噤口毒痢，症癖邪恶，冷风麻痹，气痢气淋。色黑、沉水者良。香甜者性 \n平，辛辣者热。入汤剂，磨汁用；入丸散，纸裹置怀中，待燥碾之。忌火（鹧鸪斑者，名黄 \n沉；如牛角黑者，名黑沉；咀之软、削之卷者，名黄腊沉，甚难得；浮者，名栈香；半沉者 \n，名煎香；鸡骨香虽沉而心空，并不堪用）。",g:"理气药"},
  "沙参":{o:"沙参",c:"补阴，泻肺火 \n甘苦微寒。味淡体轻，专补肺气，清肺养肝，兼益脾肾（脾为肺母，肾为肺子）。久嗽 \n肺痿，金受火克者宜之，寒客肺中作嗽者勿服（人参补五脏之阳，沙参补五脏之阴，肺热者 \n用之，以代人参）。 \n似人参而体轻松，白实者良，生沙地者长大，生黄土者瘦小。畏防己。反黎芦（北地 \n真者难得。郑奠一曰∶能疗胸痹、心腹痛、邪热结，去皮肤游风、疥癣、恶疮、疝气、崩带） \n。",g:"其他"},
  "没石子":{o:"没石子",c:"涩精，外用染须 \n苦温入肾。须精固气，收阴汗，乌须发。出大食诸番。颗小、纹细者佳。炒研用，虫食 \n成孔者拣去。忌铜、铁器。",g:"收涩药"},
  "没药":{o:"没药",c:"宣，散瘀，定痛 \n苦平（《经疏》云∶应兼辛）。入十二经。散结气，通滞血，消肿定痛生肌（寇宗 曰∶ \n血滞则气壅，气壅则经络满急，故肿且痛），补心胆虚，肝血不足（推陈致新，能生好血）。 \n治金疮杖疮（血肉受伤，故瘀而发热作痛），恶疮痔漏，翳晕目赤（肝经血热），产后血 \n气痛，破症堕胎（乳香活血，没药散血，皆能消肿止痛生肌，故每兼用。疮疽已溃者忌用， \n脓多者勿敷）。出诸南番。赤色、类于琥珀者良。主治与乳香同。",g:"活血化瘀药"},
  "泽兰":{o:"泽兰",c:"通、行血，消水 \n苦泄热，甘和血，辛散郁，香舒脾。入足太阴、厥阴（脾、肝）。通九窍，利关节，养 \n血气，长肌肉，破宿血，调月经，消症瘕，散水肿（防己为使）。 \n治产后血沥腰痛（瘀行未尽），吐血鼻血，目痛头风，痈毒扑损。补而不滞，行而不峻， \n为女科要药（古方泽兰丸甚多）。 \n时珍曰∶兰草、泽兰，一类二种，俱生下湿。紫茎素枝，赤节绿叶，叶对节生，有细齿 \n。但以茎圆节长、叶光有歧者为兰草；茎微方节短、叶有毛者为泽兰。嫩时并可 （音那） \n而佩之，《楚辞》所谓纫秋兰以为佩是也（朱文公《离骚辨证》云∶必花叶俱香，燥湿不变， \n方可刈佩。今之兰蕙，花虽香而叶无气，质弱易萎，不可刈佩），吴人呼为香草，俗",g:"活血化瘀药"},
  "泽泻":{o:"泽泻",c:"通，利水，泻膀胱火 \n甘淡微咸。入膀胱，利小便，泻肾经之火邪，功专利湿行水。 \n治消渴痰饮，呕吐泻痢，肿胀水痞，香港脚疝痛，淋沥阴汗（阴间有汗），尿血泄精（既 \n利水而又止泄精，何也？此乃湿热为病。不为虚滑者言也，虚滑则当用补涩之药），湿热之 \n病。 \n湿热既除，则清气上行。又能养五脏，益气力，起阴气，补虚损，止头旋，有聪耳、明 \n目之功（脾胃有湿热，则头重耳鸣目昏。渗去其湿，则热亦随去，土乃得令，而精气上行。 \n故《本经》列之上品，云聪耳明目，而六味丸用之，今人多以昏目疑之）。多服昏目（小便 \n过利，而肾水虚故也。眼中有水，属膀胱，过利则水涸而火生。张仲景八味丸用泽泻，寇宗 \n谓其接引桂附入",g:"利水渗湿药"},
  "泽漆":{o:"泽漆",c:"通，行水 \n辛苦微寒。消痰退热，止嗽杀虫，利大、小肠。治大腹水肿，益丈夫阴气。 \n生平泽，叶园黄绿，颇类猫睛，一名猫儿眼睛草。茎中有白汁，黏人（时珍曰∶《别录 \n》云是大戟苗，非也。功相类耳）。",g:"驱虫药"},
  "浮石":{o:"浮石",c:"\\x一名海石\\x \n泻火，软坚 \n咸润下，寒降火。色白体轻，入肺清其上源（肺为水之上源）。止渴止嗽，通淋软坚， \n除上焦痰热，消瘿瘤结核（顽痰所结，咸能软坚。俞琰《席上腐谈》云∶肝属木，当浮而反 \n沉；肺属金，当沉而反浮何也？以肝实而肺虚也。故石入水则沉，而南海有沉水之香，虚实 \n之反如此）。水沫日久结成，海中者味咸更良。",g:"清热药"},
  "浮萍":{o:"浮萍",c:"轻，发汗，利湿 \n辛散轻浮。入肺经，达皮肤，能发扬邪汗（丹溪曰∶浮萍发汗，甚于麻黄），止瘙痒、 \n消渴（捣汁服）生于水，又能下水气，利小便。 \n治一切风湿瘫痪（浮萍一味，蜜丸酒服，治三十六种风；浓煮汁浴，治恶疾疮癞遍身）。 \n烧烟辟蚊。 \n紫背者良。",g:"解表药"},
  "海带":{o:"海带",c:"下水消瘿，功同海藻。似海藻而粗，柔弱而长。",g:"其他"},
  "海松子":{o:"海松子",c:"润燥 \n甘温。润肺温胃，散水除风。治咳嗽（松子一两，胡桃二两，炼蜜和服，治肺燥咳嗽） \n虚秘（同柏子仁、麻仁，溶蜡为丸，名三仁丸）。出辽东云南，松须五鬣。",g:"其他"},
  "海桐皮":{o:"海桐皮",c:"宣，祛风湿 \n苦温（《经疏》云∶应兼辛）。入血分。祛风、去湿、杀虫，能行经络达病所。治风蹶顽 \n痹，腰膝疼痛（《传信方》∶海桐、薏苡各二两，芎 、羌活、地骨皮、五加皮各二两，甘 \n草五钱，生地七两，酒二斗浸，此方不得增减。早、中、晚饮，常令醺醺），疳 疥癣，目 \n赤（煎洗）牙虫（煎服，或含漱）。出广南。皮白坚韧，作索不烂。",g:"祛风湿药"},
  "海狗肾":{o:"海狗肾",c:"\\x一名腽肭脐\\x \n补肾，助阳 \n甘咸大热。补肾助阳，治虚损劳伤，阴痿精冷，功近苁蓉、锁阳。出西番，今东海亦有 \n之。似狗而鱼尾。置器中长年湿润，腊月浸水不冻。置睡犬旁，犬惊跳者为真（或曰∶连脐 \n取下故名脐，或曰∶乃腽肭兽之脐也。昂按∶两名不类，恐一是海鱼之肾。一是山兽之脐也 \n。《纲目》以此条入兽部）。",g:"其他"},
  "海藻":{o:"海藻",c:"泻热，软坚痰，消瘿瘤 \n咸润下而软坚，寒行水以泄热。故消瘿瘤、桔核、阴 之坚聚（腹痛曰疝，丸痛曰 ， \n音颓），痰饮香港脚水肿之湿热。消宿食，治五膈。 \n山东海有大叶马尾二种，亦作海菜食，洗去咸水用（昂按∶其用在咸，似不宜过洗）。 \n反甘草（东垣治瘰 、马刀、海藻、甘草并用，盖激之以溃坚也）。",g:"化痰止咳平喘药"},
  "海螵蛸":{o:"海螵蛸",c:"\\x一名乌贼骨\\x \n宣，通血脉 \n咸走血、温和血。入肝、肾血分。通血脉，祛寒湿，治血枯（《内经》∶血枯，治之以 \n乌骨），血瘕，血崩血闭，腹痛环脐，阴蚀肿痛（烧末，酒服），疟痢疳虫，目翳泪出， \n耳出脓（性能燥脓收水。为末，加麝少许掺入），厥阴、少阴（肝、肾）经病。出东海，亦 \n名墨鱼（腹中有墨，书字逾年乃灭。常吐黑水，自罩其身，人即于黑水处取之）。取鱼骨， \n卤浸、炙黄用。恶附子、白芨、白蔹。能淡盐。",g:"收涩药"},
  "海金沙":{o:"海金砂",c:"通淋，泻湿热 \n甘寒淡渗。除小肠、膀胱血分湿热。 \n治肿满、五淋、茎痛。得栀子、牙硝、硼砂，治伤寒热狂（大热利小便，此釜底抽薪之 \n义也）。 \n茎细如线，引竹木上。叶级皱处，有砂黄赤色。忌火。",g:"利水渗湿药"},
  "淡竹叶":{o:"淡竹叶",c:"泻上焦烦热 \n辛淡甘寒。凉心暖脾，消痰止渴。除上焦风邪烦热（叶生竹上，故治上焦。仲景治伤寒 \n发热、大渴，有竹叶石膏汤。乃假其辛寒，以散阳明之邪热也），咳逆喘促，呕哕吐血，中 \n风失音，小儿惊痫。竹生一年以上者，嫩而有力。",g:"其他"},
  "淡豆豉":{o:"淡豆豉",c:"宣，解表，除烦 \n苦泄肺、寒胜热（陈藏器曰∶豆性生平，炒熟、热煮食寒，作豉冷）。发汗解肌，调中 \n下气。治伤寒头痛，烦躁满闷，懊 不眠，发斑呕逆（凡伤寒呕逆烦闷，宜引吐，不宜用下 \n药以逆之。淡豉合栀子，名栀子豉汤，能吐虚烦），血痢温疟（时珍曰∶黑豆性平，作豉则 \n温，既经蒸 ，故能升能散。得葱则发汗，得盐则能吐，得酒能治风，得薤则治痢，得蒜则 \n止血，炒熟又能止汗。孟诜治盗汗，炒香渍酒服。《肘后》∶合葱白煎，名葱豉汤，用代麻黄 \n汤，通治伤寒，发表，亦治酒病）。 \n造淡豉法，用黑大豆水浸一宿，淘净蒸熟，摊匀，蒿复，候上黄衣，取晒，簸净，水拌 \n，干湿得所，安瓮中，筑实。桑叶浓盖，泥封。晒七日",g:"解表药"},
  "淫羊藿":{o:"淫羊藿",c:"\\x一名仙灵脾\\x \n补肾命 \n辛香甘温。入肝肾。补命门（时珍曰∶手足阳明、三焦、命门药），益精气，坚筋骨， \n利小便。 \n治绝阳不兴，绝阴不产，冷风劳气，四肢不仁（手足麻木）。 \n一名仙灵脾。北部有羊，一日百合，食此藿所致，故名。去枝，羊脂拌炒。山药为使。 \n得酒良。",g:"补虚药"},
  "滑石":{o:"滑石",c:"滑，利窍，通，行水，体重，泻火气，轻，解肌 \n滑利窍，淡渗湿，甘益气，补脾胃，寒泻热，降心火。色白入肺，上开腠理而发表（肺 \n主皮毛），下走膀胱而行水，通六腑九窍津液，为足太阳经（膀胱）本药。治中暑积热，呕 \n吐烦渴，黄胆水肿，香港脚淋闭（偏主石淋），水泻热痢（六一散加红曲治赤痢，加干姜治白 \n痢），吐血衄血，诸疮肿毒，为荡热除湿之要剂。消暑散结通乳滑胎（时珍曰∶滑石利窍， \n不独小便也。上开腠理而发表，是除上、中之湿热。下利便溺而行水，是除中，下之湿热。 \n热去则三焦宁而表里和，湿去则阑门通而阴阳利矣。阑门分别清浊，乃小肠之下口。河间益 \n元散，通治上下表里诸病，盖是此意。益元散，一名天水散",g:"利水渗湿药"},
  "漆":{o:"漆",c:"泻，破血，消积，杀虫 \n辛温有毒。功专行血杀虫，削年深坚结之积滞（丹溪曰∶漆性急而飞补，用之中节，积 \n滞去后，补性内行，人不知也），破日久凝结之瘀血（能化瘀血为水），续筋骨绝伤（损伤必 \n有瘀血停滞）。治传尸劳瘵，瘕疝蛔虫。炒令烟尽入药，或烧存性，用半夏为使。畏川椒、 \n紫苏、鸡子、蟹（漆得蟹而成水）。",g:"活血化瘀药"},
  "漏芦":{o:"漏芦",c:"泻热，解毒 \n咸软坚，苦下泄，寒胜热。入胃、大肠，通肺、小肠。散热解毒，通经下乳，排脓止血 \n，生肌杀虫。 \n治遗精尿血，痈疽发背（古方以漏芦汤为称首），及预解时行痘疹毒（取其寒胜热，又 \n能入阳明故也）。 \n出闽中，茎如油麻，枯黑如漆者真。甘草拌蒸。连翘为使。",g:"清热药"},
  "灯心草":{o:"灯草",c:"轻，通，利水，清热 \n甘淡而寒。降心火（心能入心），清肺热，利小肠（心与小肠相表里，心火清则肺热小 \n肠亦清，而热从小便出矣），通气止血。 \n治五淋水肿，烧灰吹喉痹，涂乳止夜啼，擦癣最良（缚成把，擦摩极痒时，虫从草出， \n浮水可见，十余次则能断也）。",g:"清热药"},
  "炉甘石":{o:"炉甘石",c:"燥温，治目疾 \n甘温。阳明胃经药。受金、银之气，金胜木，燥胜湿，故止血消肿，收湿除烂，退赤去 \n翳，为目疾要药。产金银坑中，金银之苗也。状如羊脂，松似石脂，能点赤铜为黄（今之黄 \n铜，皆其所点也）。 红、童便淬七次，研粉，水飞用。",g:"其他"},
  "烟草":{o:"烟草",c:"\\x新增\\x \n宣，行气，辟寒 \n辛温有毒。 \n治风寒湿痹，滞气停痰，山岚瘴雾。其气入口，不循常度，顷刻而周一身，令人通体俱 \n快，醒能使醉，醉能使醒，饥能使饱，饱能使饥。 \n人以代酒代茗，终身不厌（故一名相思草）。然火气熏灼，耗血损年，人自不觉耳。闽 \n产者佳（烟筒中水，能解蛇毒）。",g:"理气药"},
  "熊胆":{o:"熊胆",c:"泻热 \n苦寒。凉心平肝，明目杀虫。治惊痫五痔（涂之取瘥）。通明者佳。性善辟尘。扑尘水 \n上，投胆少许，则豁然而开。",g:"平肝息风药"},
  "熟地黄":{o:"熟地黄",c:"平补肝肾，养血滋阴 \n甘而微温。入手足少阴、厥阴经。滋肾水，补真阴，填骨髓，生精血，聪耳明目（耳为 \n肾窍，目为肝窍。目得血而能视。耳得血而能聪），黑发乌髭。治劳伤风痹，胎产百病，为 \n补血之上剂（丹溪曰∶产前当清热养血为主，产后宜大补气血为主，虽有杂证，从未治之。 \n昂按∶丹溪产后大补气血一语，诚至当不易之论。后人不善用之，多有风寒未解，瘀血未尽 \n，妄施峻补，反致大害者，不可不察。王硕云∶男子多阴虚，宜熟地；女子多血热，宜生地 \n）。 \n以好酒拌砂仁末，浸蒸晒九次用（地黄性寒，得酒与火与日则温。性泥，得砂仁则和气 \n，且能引入丹田。六味丸用之为君，尺脉弱者加桂、附，所谓益火之原，以消阴翳也",g:"补虚药"},
  "牛肉":{o:"牛肉",c:"补脾土 \n甘温属土。安中补脾，益气止渴（倒仓法，用牡黄牛肉二十斤，洗净，煮为糜，滤去渣 \n，熬成琥珀色。前一晚不食，至日，空腹坐密室，取汁每饮一钟。少时又饮，积数十钟，身 \n体觉痛。如病在上则吐，在下则利，在中则吐而利，利后必渴，即饮已溺数碗，以涤余垢。 \n饥倦先与米饮，二日与淡粥，次与浓粥软饭，将养一月沉 悉安矣。须断房事半年，牛 \n肉五年。丹溪曰∶牛坤土，黄中色，肉、胃药，液、无形之物也！积聚既久，回薄肠胃曲折 \n之处，岂铢两丸散所能窥犯乎！肉液充满流行，无处不到，如洪水泛涨，一切凝滞，皆顺流 \n而去矣。此方传于西域异人，中年后行一二次，亦却疾养寿之一助也。王纶曰∶牛肉补中， \n非吐下药，",g:"其他"},
  "牛膝":{o:"牛膝",c:"补肝肾，泻恶血 \n苦酸而平。足厥阴、少阴经药（肝肾），能引诸药下行。酒蒸则甘酸而温，益肝肾，强 \n筋骨（肝主筋，肾主骨），治腰膝骨痛，足痿筋挛（下行故理足，补肝则筋舒，血行则痛止）， \n阴痿失溺（筋衰则阴痿，肾虚则失溺），久疟下痢，伤中少气（以土皆补肝肾之功）。 \n生用，则散恶血，破症结（血行则结散），治心腹诸痛，淋痛尿血（热蓄膀胱、便涩而 \n痛曰淋。气淋便涩余沥，劳淋房劳即发，冷淋寒战后溲，膏淋便出如膏，石淋精结成石，尿 \n血即血淋也。鲜色者，心与小肠实热；色瘀者，肾与膀胱虚冷。张子和曰∶石淋乃肝经移热 \n于胞中，日久熬煎成石，非肾与小肠病也。大法治淋宜通气、清心、平火、利湿。不宜用补， \n",g:"活血化瘀药"},
  "牛蒡子":{o:"牛蒡子",c:"\\x一名鼠粘子，一名恶实\\x \n泻热，解毒 \n辛平。润肺解热，散结除风，利咽膈，理痰嗽，消斑疹，利二便，行十二经。散诸肿疮 \n疡之毒，利腰膝凝滞之气（性冷而滑利，痘症虚寒泄泻者忌服）。 \n实如葡萄而褐色，酒拌蒸，待有霜，拭去用。根苦寒。竹刀刮净，绞汁，蜜和服，治中 \n风，汗出乃愈。捣和猪脂，贴疮肿及翻花疮（肉翻出如花状）。",g:"解表药"},
  "牛黄":{o:"牛黄",c:"泻热，利痰，凉惊 \n甘凉。牛有病，在心、肝、胆之间凝结成黄，故还以治心、肝、胆之病（《经疏》云∶ \n牛食百草，其精华凝结成黄，犹人之有内丹。故能散火、消痰、解毒，为世神物。或云牛病 \n乃生黄者，非也）。清心解热，利痰凉惊，通窍辟邪。治中风入脏，惊痫口噤（心热则火自 \n生焰，肝热则木自生风，风火相搏，胶痰上壅，遂致中风不语。东垣曰∶中脏宜之。若中 \n腑及血脉者用之，反能引风入骨，如油入面。按∶中风中脏者重，多滞九窍；中腑稍轻，多 \n着四肢。若外无六经形证，内无便溺阻隔，为中经络，为又轻。初宜顺气开痰，次宜养血活 \n血，不宜专用风药。大抵五脏皆有风，而犯肝者为多。肝属风木而主筋，肝病不能营筋，故 ",g:"补虚药"},
  "牡丹皮":{o:"牡丹皮",c:"泻伏火而补血 \n辛甘寒微。入手足少阴（心、肾）、厥阴（心包、肝）。泻血中伏火（色丹故入血分。时 \n珍曰∶伏火即阴火也，阴火即相火也。世人专以黄柏治相火，不知丹皮之功更胜，故仲景肾 \n气丸用之），和血、凉血而生血（血热则枯，凉则生），破积血（积瘀不去则新血不生），通 \n经脉。 \n为吐衄必用之药（血属阴本静，因相火所逼，故越出上窍）。治中风，五劳，惊痫螈 \n（筋脉伸缩抽掣为螈 。或手足抽掣，口眼 斜，卒然眩仆，吐涎身软，时发时止为痫。皆 \n阴虚血热，风火相搏，痰随火涌所致），除烦热，疗痈疮（凉血），下胞胎，退无汗之骨蒸（张 \n元素曰∶丹皮治无汗之骨蒸，地骨皮治有汗之骨蒸。神不足者手少阴，志不足者足",g:"清热药"},
  "牡蛎":{o:"牡蛎",c:"涩肠，补水，软坚 \n咸以软坚，化痰，消瘰 结核，老血瘕疝；涩以收脱，治遗精崩带，止嗽敛汗（或同麻 \n黄根、糯米为粉扑身，或加入煎剂）固大、小肠；微寒以清热补水，治虚劳烦热，温疟赤痢 \n，利湿止渴，为肝、肾血分之药（王好古曰∶以柴胡引之，去胁下硬；茶引之，消颈核；大 \n黄引之，消股间肿；以地黄为使，益精收涩，止大小便利；以贝母为使，消积结）。盐水煮 \n一伏时， 粉用。亦有生用者，贝母为使。恶麻黄、辛夷、吴茱萸。得甘草、牛膝、远志、 \n蛇床子良（海气化成，纯雄无雌，故名牡）。",g:"平肝息风药"},
  "牵牛":{o:"牵牛",c:"大泻气分湿热 \n辛热有毒，属火善走。入肺经，泻气分之湿热（肺主气，火能平金而泄肺），能达右肾 \n命门，走精隧，通下焦郁遏。及大肠风秘、气秘，利大小便，逐水消痰，杀虫堕胎。 \n治水肿喘满 癖气块。若湿、热在血分、胃弱气虚人禁用（东垣曰∶牵牛苦寒误矣，其 \n味辛辣，久嚼猛烈雄壮，所谓苦寒安在哉？乃泻气之药，比诸辛药泄气尤甚。若湿从下受， \n下焦主血，血中之湿，宜苦寒之味。而反用辛热之药，泄上焦之气，是血病泻气，使气血俱 \n损也。王好古曰∶以气药引，则入气；以大黄引，则入血。时珍曰∶一妇肠结，年几六十， \n服养血润燥药，则泥结，服硝黄药，则若罔知。如此三十余年。其人体肥膏梁而多郁，日吐 \n酸痰乃宽。",g:"补虚药"},
  "犀角":{o:"犀角",c:"泻心、胃大热 \n苦酸咸寒。凉心泻肝，清胃中大热，祛风利痰，辟邪解毒。治伤寒时疫，发黄发斑（伤 \n寒下早，热乘虚入胃则发斑；下迟，热留胃中亦发斑），吐血下血，蓄血谵狂，痘疮黑陷， \n消痈化脓，定惊明目。妊妇忌之（能消胎气。时珍曰∶五脏六腑，皆禀气于胃。风邪热毒， \n必先干之，饮食药物，必先入胃。角，犀之精华所聚，足阳明胃药也。故能入阳明，解一切 \n毒，疗一切血，及惊、狂、斑、痘之证。《抱朴子》云∶犀食百草之毒及棘，故能解毒。饮 \n食有毒，以角搅之，则生白沫）。乌而光润者胜，角尖尤胜（鹿取茸，犀取尖，其精气尽在 \n是也）。现成器物，多被蒸煮，不堪入药。入汤剂磨汁用，人丸散锉细。纸裹纳怀中，待热 \n",g:"清热药"},
  "犬肉":{o:"犬肉",c:"补虚寒 \n酸而咸温。暖脾益胃，脾胃暖则腰肾受荫矣。补虚寒，助阳事（两肾、阴茎尤胜）。黄 \n者补脾，黑者补肾。畏杏仁。忌蒜（道家以为地厌。黄犬血，酒服二碗，治肠痈）。",g:"其他"},
  "狗脊":{o:"狗脊",c:"平补肝肾 \n苦坚肾，甘益血（能强汗），温养气。治失溺不节（肾虚），脚弱、腰痛、寒湿。 \n周痹（经曰∶内不在脏腑，而外未发于皮，独居分肉之间，真气不能周，命曰周痹）。 \n除风虚，强机关，利俯仰（滋肾益肝，则骨健而筋强）。 \n有黄毛如狗形，故曰金毛狗脊。去毛，切，酒拌蒸。萆 为使。熬膏良。",g:"祛风湿药"},
  "独活":{o:"独活",c:"宣，搜风，去湿 \n辛苦微温。气缓善搜，入足少阴（肾）气分，以理伏风。 \n治本经伤风头痛，头晕目眩（宜与细辛同用），风热齿痛（文潞公《药准》用独活、地 \n黄等分为末，每服三钱），痉痫湿痹（项背强直，手足反张曰痉；湿流关节，痛而烦曰湿痹。 \n风胜湿，故二活兼能去湿），奔豚疝瘕（肾积曰奔豚，风寒湿客于肾家所致。瘕疝亦然）。有 \n风不动，无风反摇，又名独摇草（故治风）。 \n《本经》云∶独活一名羌活。古方惟用独活，后人云是一类二种，遂分用。以形虚大有 \n臼如鬼眼，节疏色黄者为独活；色紫节密，气猛烈者为羌活。并出蜀汉。又云自西羌来者名 \n羌活（故名胡王使者，今采诸家所分经络、主治各证，以便施用）。",g:"祛风湿药"},
  "猪肉":{o:"猪肉",c:"脏腑引经 \n水畜，咸寒。 \n心血，用作补心药之向导，盖取以心归心、以血导血之意（《延寿丹书》曰∶猪临杀， \n惊气入心，绝气入肝，皆不可多食）。 \n尾血，和龙脑（冰片），治痘疮倒 （能发之，时珍曰∶取其动而不息，亦有用心血者）。 \n肝，主藏血，补血药用之，入肝明目（雄者良。同夜明砂作丸，治雀目。雀目者，夜不 \n能睹，湿痰及肝火盛也）。 \n肺，补肺，治肺虚咳嗽（咳血者，蘸薏仁末食）。 \n肚，入胃健脾（仲景治消渴，有黄连猪肚丸。用雄猪肚一枚，入黄连末五两，栝蒌根、 \n白粱米各四两，知母三两，麦冬二两，缝定蒸熟，丸如梧子大，每服三十丸，米饮下。《直 \n指方》∶治小儿疳热，黄连五两，入猪肝蒸烂，饭丸，米",g:"补虚药"},
  "猪苓":{o:"猪苓",c:"通，行水 \n苦泄滞，淡利窍，甘助阳。入膀胱、肾经。升而能降，开腠发汗，利便行水，与茯苓同 \n而不补。 \n治伤寒、温疫大热，（《经疏曰∶大热利小便，亦分消之意），懊 消渴，肿胀淋浊，泻 \n痢疟（疟多由暑，暑必兼湿。经曰∶夏伤于暑，秋必 疟）。然耗津液，多服损肾昏目（肾 \n水不足则目昏。仲景五苓散，猪苓、茯苓、泽泻、白术、桂，为治水之总剂。昂按∶经曰∶ \n膀胱者，州都之官，津液藏焉，气化则能出矣。用肉桂辛热引入膀胱，所以化其气也。除桂 \n名四苓散。《资生经》曰∶五苓散能生津液，亦通大便。曾世荣治惊风，亦用五苓散。白茯 \n苓安心神，泽泻导小便，小肠利而心气平，木得桂而枯，能抑肝而风自止，可谓善用五苓",g:"利水渗湿药"},
  "獭肝":{o:"獭肝",c:"补肝肾，杀传尸 \n甘咸而温。益阴补虚，杀虫止嗽，治传尸鬼疰有神功（尸疰、鬼疰乃五疰之一，变动有 \n三十三种，乃至九十九种。其症使人寒热，沉沉默默，不知病之所苦，而无处不恶，死后传 \n入，乃至灭门。古方有獭肝丸。獭肝烘干，炙为末。水服二钱，日三次，以瘥为度）。诸肝 \n皆有叶数，惟獭肝一月一叶，其间又有退叶，须于獭身取下，不尔多伪（吴鹤皋曰∶獭阴物 \n，昼伏夜出，故治鬼疰。昂谓∶不然，缘其肝独异于他兽也）。",g:"驱虫药"},
  "玄参":{o:"元参",c:"补水，泻无根之火 \n苦咸微寒。色黑入肾。能壮水以制火，散无根浮游之火（肾水受寒，真阴失守，孤阳 \n无根，发为火病），益精明目，利咽喉，通二便。 \n治骨蒸传尸，伤寒阳毒发斑（亦有阴证发斑者），懊 （郁闷不舒），烦渴，温疟洒洒， \n喉痹咽痛（本肾药而治上焦火证，壮水以制火也。肾脉贯肝膈，入肺中。循喉咙，系舌本 \n。肾虚则相火上炎，此喉痹、咽肿、咳嗽、吐血之所由来也。潮热骨蒸，亦本于此。此与黄 \n能治下焦带浊崩淋同义），瘰疠结核（寒散火，咸软坚），痈疽鼠 （音漏）。脾虚泄泻者 \n忌用。蒸过焙用，勿犯铜器。恶黄 、山茱萸、姜、枣。反藜芦。",g:"清热药"},
  "玉竹":{o:"葳蕤",c:"平补而润，去风湿 \n甘平。补中益气，润心肺，悦颜色，除烦渴。 \n治风淫湿毒，目痛 烂（风湿），寒热 疟（ ，诗廉切，亦疟也），中风暴热，不能 \n动摇，头痛腰痛（凡头痛不止者属外感，宜发散。乍痛乍止者属内伤，宜补虚。又有偏头痛 \n者，左属风与血虚，右属痰热与气虚，腰痛亦有肾虚、气滞、痰积、血瘀、风寒、湿热之不 \n同。凡挟虚、挟风湿者，宜葳蕤），茎寒自汗，一切不足之证。用代参、 ，不寒不燥，大 \n有殊功（昂按∶葳蕤温润甘平，中和之品。若蜜制作丸，服之数斤，自有殊功。与服何首乌、 \n地黄者，同一理也。若仅加数分于煎剂，以为可代参、 ，则失之远矣。大抵此药性缓，久 \n服方能见功。而所主者，多风湿、虚劳",g:"补虚药"},
  "王不留行":{o:"王不留行",c:"通，行血 \n甘苦而平。其性行而不住，能走血分、通血脉，乃阳明、冲、任之药（阳明多气多血）。 \n除风去痹，止血定痛，通经利便，下乳（俗云∶穿山甲、王不留行妇人服之乳长流）催 \n生。治金疮（止血）痈疮（散血），出竹、木刺。孕妇忌之。 \n花如铃铎，实如灯笼，子壳五棱。取苗子蒸，浆水浸用。",g:"活血化瘀药"},
  "王瓜":{o:"王瓜",c:"\\x即土瓜根\\x \n泻热，利水，行血 \n苦寒。泻热利水。治天行热疾，黄胆消渴（捣汁饮），便数带下，月闭瘀血。利大、小 \n肠，排脓消肿，下乳（通乳药多用之，单服亦可）堕胎。 \n根如栝蒌之小者，味如山药，根、子通用（《经疏》曰∶主治略似栝蒌。伤寒发斑，用 \n王瓜捣汁，和伏龙肝末服，甚效）。",g:"利水渗湿药"},
  "珍珠":{o:"真珠",c:"泻热，定惊 \n甘咸性寒。感月而胎（语云∶上巳有风梨有蠹，中秋无月蚌无胎），水精所孕。水能制 \n火，入心、肝二经。镇心安魂（肝藏魂。昂按∶虽云泻热，亦借其宝气也。大抵宝物多能镇 \n心安魂，如金箔、琥珀、真珠之类。龙齿安魂，亦假其神气也），坠痰拔毒，收口生肌。治 \n惊热痘疗，下死胎胞衣（珠末一两，苦酒服），涂面好颜色，点目去翳膜，绵裹塞耳治聋。 \n取新洁未经钻缀者，乳浸三日，研粉极细用（不细伤人脏腑。陆佃曰∶蛤蚌无阴阳牝牡，须 \n雀化成，故能生珠，专一于阴阳也）。",g:"其他"},
  "琥珀":{o:"琥珀",c:"通，行水，散瘀，安神 \n甘平。以脂入土而成实，故能通塞以宁心。安魂魄，疗癫邪（从镇坠药，则安心神）。 \n色赤入手少阴、足厥阴（心、肝）血分，故能消瘀血，破症瘕，生肌肉，合金疮（从辛温药、 \n则破血生肌）。其味甘淡上行，能使肺气下降而通膀胱（经曰∶饮食入胃，游溢精气。上输 \n于脾，脾气散精，上归于肺，通调水道，下输膀胱。凡渗药皆上行而后下降），故能治五淋， \n利小便，燥脾土（从淡渗药，则利窍行水。然石药终燥，若血少而小便不利者，仅致燥急之 \n苦），又能明目磨翳。 \n松脂入土，年日久结成，或云枫脂结成。以摩热拾芥者真（市人多煮鸡子及青鱼枕伪之 \n。摩呵亦能拾芥，宜辨）。用柏子仁末，入瓦锅同煮半日，",g:"活血化瘀药"},
  "瓜蒌":{o:"栝楼仁",c:"\\x俗作瓜蒌\\x \n泻火，润肺，滑肠，止血，治热痰 \n甘补肺（本草苦），寒润下。能清上焦之火，使痰气下降，为治嗽要药（肺受火逼，失 \n下降之令，故生痰作嗽）。又能荡涤胸中郁热垢腻，生津止渴（丹溪曰∶消渴神药），清咽利 \n肠（通大便。《是斋方》∶焙研酒调或米饮下，治小便不通），通乳消肿。 \n治结胸胸痹（仲景小陷胸汤用之。又云∶少阳证口渴者，小柴胡汤，以此易半夏），酒 \n黄热痢，二便不通。炒香酒服，止一切血（寒降火），泻者忌用。 \n实圆长如熟柿子，扁多脂，去油用。枸杞为使，畏牛膝、干漆。恶干姜。反乌头。",g:"化痰止咳平喘药"},
  "瓦楞子":{o:"瓦楞子",c:"\\x即蚶壳\\x \n泻，消症，散痰 \n甘咸。消血块，散痰积（ 红、醋淬三次，为末，醋膏丸，治一切气血症瘕）。",g:"化痰止咳平喘药"},
  "甘松香":{o:"甘松香",c:"宣，理气醒脾 \n甘温芳香。理诸气，开脾郁。 \n治腹卒然满痛，风疳齿 ，香港脚膝浮。煎汤淋洗。 \n出凉州及黔蜀。叶如茅，用根（根极繁密）。",g:"理气药"},
  "甘澜水":{o:"甘澜水",c:"补 \n用流水以瓢扬万遍，亦曰劳水。水性咸而重，劳之则甘而轻。仲景用煎伤寒劳伤等药， \n取其不助肾气而益脾胃也。",g:"其他"},
  "甘草":{o:"甘草",c:"有补有泻，能表能里，可升可降 \n味甘。生用气平，补脾胃不足而泻心火（火急甚者，必以此缓之）。炙用气温，补三焦 \n元气而散表寒。入和剂则补益，入汗剂则解肌（解退肌表之热），入凉剂则泻邪热（白虎汤、 \n泻心汤之类），入峻剂则缓正气（姜、附加之，恐其僭上；硝、黄加之，恐其峻下，皆缓之 \n之意），入润剂则养阴血（炙甘草汤之类）。能协和诸药，使之不争。生肌止痛（土主肌肉， \n甘能缓痛），通行十二经，解百药毒（凡解毒药，并须冷冻饮料，热则不效。小儿初生，拭去口 \n中恶血，绵渍汁令咂之，能解胎毒），故有国老之称。中满证忌之（甘令人满。亦有生用为 \n泻者，以其能引诸药至于满所。经云∶以甘补之，以甘泻之是已。故",g:"补虚药"},
  "甘蔗":{o:"甘蔗",c:"补脾，润燥 \n甘寒。和中助脾，除热润燥，止渴（治消渴）消痰，解酒毒，利二便（《外台方》∶嚼咽 \n或捣汁，治发热口干便涩）。治呕哕反胃（《梅师方》∶蔗汁、姜汁和服），大便燥结（蔗汁熬 \n之，名石蜜，即白霜糖。唐大历间，有邹和尚始传造法，性味甘温，补脾缓肝，润肺和中， \n消痰治嗽，多食助热损齿生虫。紫沙糖功用略同）。",g:"其他"},
  "甘遂":{o:"甘遂",c:"大通，泻经隧水湿 \n苦寒有毒。能泻肾经及隧道水湿，直达水气所结之处，以攻决为用，为下水之圣药（仲 \n景大陷肠汤用之）。 \n主十二种水，大腹肿满（名水蛊。喻嘉言曰∶肾为水谷之海，五脏六腑之源。脾不能散 \n胃之水精于肺，而病于中；肺不能通胃之水道于膀胱，而病于上。肾不能司胃之关，时其输 \n泄，而病于下，以致积水浸淫，无所底止。肾者，胃之关也。前阴利水，后阴利谷。王好古 \n曰∶水者，脾肺肾三经所主。有五脏六腑十二经之部分，上头面，中四肢，下腰脚，外皮肤 \n，中肌肉，内筋骨。脉有尺寸之殊，浮沉之别，不可轻泻药，当知病在何经何脏，方可用之。 \n按∶水肿有痰裹食和瘀血、致清不升浊不降而成者，有湿热相生、隧",g:"泻下药"},
  "甜瓜蒂":{o:"甜瓜蒂",c:"宣，涌，吐。与淡豆豉、赤小豆，并为吐药 \n苦寒。阳明（胃）吐药，能吐风热痰涎，上隔宿食（吐去上焦之邪，经所谓其高者因而 \n越之。在上者涌之，木郁达之是也。越以瓜蒂、淡豉之苦，涌以赤小豆之酸，吐去上焦有形 \n之物，则木得舒畅，天地交而万物通矣。当吐而胃弱者，代以参芦。朱丹溪曰∶吐中就有发 \n散之义。张子和曰∶诸汗法，古方多有之，惟以吐发汗，世罕知之。故予尝曰∶吐法兼汗以 \n此夫。昂按∶汗、吐、下、和，乃治疗之四法。仲景瓜蒂散、栀豉汤，并是吐药。子和治病， \n用吐尤多。丹溪治许白云大吐二十余日，治小便不通，亦用吐法，甚至用四物、四君以引吐 \n，成法具在。今人惟知汗、下、和，而吐法绝置不用。遇邪在上",g:"解表药"},
  "生地黄":{o:"生地黄",c:"大泻火 \n甘苦大寒，入心肾。泻丙火（小肠为丙火，心与小肠相表里，导赤散与木通同用），清 \n燥金（胃、大肠火），消瘀通经，平诸血逆。治吐衄崩中（唾血者，血随唾出；咯血者，随 \n痰咯出，或带血丝，出肾经及肺经。自两胁逆上吐出者，属肝经。衄血者，血溢于脑，从鼻 \n而出；咳血者，咳出痰内有血，并属肺经。吐出呕出成盆成碗者，属胃经。经漏不止曰崩， \n血热则妄行，宜以此凉之。虚人忌用，用于干地黄可也），伤寒阳强，痘症大热（痘症用之 \n甚多，本草未载）。多服损胃。 \n生掘鲜者，捣汁饮之，或用酒制，则不伤胃。生则寒，干则凉，热则温（故分为三条， \n以便施用）。",g:"清热药"},
  "生姜":{o:"生姜",c:"宣，散寒发表，止呕开痰 \n辛温。行阳分而祛寒发表，宣肺气而解郁调中，畅胃口而开痰下食。治伤寒头痛，伤风 \n鼻塞（辛能入肺，通气散寒），咳逆呕哕（有声有物为呕，有声无物为哕，有物无声为吐。 \n其证或因寒、因热、因食、因痰，气逆上冲而然。生姜能散逆气，呕家圣药。东垣曰∶辛热 \n生姜之类治呕吐，但治上焦气壅表实之病，若胃虚谷气不行、胸闭塞而呕者，惟宜益胃、推 \n扬谷气而已，勿作表实用辛药泻之。丹溪曰∶阴分咳嗽者，多属阴虚，宜用贝母，勿用生姜， \n以其辛散也。昂按∶人特知陈皮、生姜能止呕，不知亦有发呕之时。以其性上升，如胃热者 \n非所宜也。藿香亦然），胸壅痰膈，寒痛湿泻。消水气，行血痹（产后血上冲心及",g:"解表药"},
  "田螺":{o:"田螺",c:"泻热 \n味甘大寒。利湿清热，止渴（消渴）醒酒，利大、小便（能引热下行。熊彦诚病前后不 \n通，腹胀如鼓，众医莫措。遇一异人曰∶此易耳，奉施一药。即脱靴入水，探得一大螺，曰∶ \n事济矣。以盐和壳捣碎，帛系脐下一寸三分，曾未安席，砉然暴下。归访异人，无所见矣。 \n董守约以香港脚攻注，或教捶数螺系两股，便觉冷气趋下至足，即而亦安）。治香港脚黄胆，噤 \n口毒痢（用螺少加麝，捣饼烘热，贴脐下，引热下行，自然思食），目热赤痛（入盐花，取 \n汁点之），搽痔疮狐臭。",g:"清热药"},
  "白前":{o:"白前",c:"泻肺，降气，下痰 \n辛甘微寒。长于降气下痰止嗽，治肺气壅实，胸膈逆满。虚者禁用。 \n似牛膝、粗长坚直易断者，白前也；短小柔软能弯者，白薇也（近道多有，形色颇同， \n以此别之）。去头须，甘草水浸一伏时（即一昼夜），焙用。忌羊肉。",g:"化痰止咳平喘药"},
  "白及":{o:"白芨",c:"涩，补肺，逐瘀生新 \n味苦而辛，性涩而收。得秋金之令，入肺止吐血，（《摘玄》云∶试血法，吐水内浮者 \n肺血也，沉者肝血也，半浮沉者心血也。各随所见，以羊肺、肝、心蘸白芨末，日日服之佳 \n），肺损者能复生之（以有形生有形也。人之五脏，惟肺叶损坏者，可以复生。台州狱吏悯 \n一重囚，囚感之曰∶吾七犯死罪，遭刑拷，肺皆损伤。得一方，用白芨末米饮日服，其效如 \n神。后囚凌迟，剖开胸，见肺开窍穴数十，皆白芨填补，色犹不变也）。 \n治跌打折骨（酒服二钱），汤火灼伤（油调末敷），恶疮痈肿，败疽死肌。去腐逐瘀生新， \n除面上 （ 音千，去声，面黑气。 音炮，面疮也），涂手足皴裂，令人肌滑。 \n紫石英为使。畏杏仁",g:"止血药"},
  "白头翁":{o:"白头翁",c:"泻热，凉血 \n苦坚肾，寒凉血。入阳明（胃，大肠）血分。 \n治热毒血痢（仲景治热痢，有白头翁汤合黄连、黄柏、秦皮。东垣曰∶骨欲坚，急食苦 \n以坚之。痢则下焦虚，故以纯苦之剂坚之），温疟寒热，齿痛骨痛（肾主齿骨，龈属阳明）， \n鼻衄秃疮，瘰 疝瘕，血痔偏坠（捣敷患处）。明目消疣。 \n有风反静，无风则摇，近根外有白茸。得酒良。",g:"清热药"},
  "白扁豆":{o:"白扁豆",c:"补脾，除湿，消暑 \n甘温腥香。色白微黄，脾之谷也。调脾暖胃，通利三焦，降浊升清，消暑除湿（能消脾 \n胃之暑），止渴止泻，专治中宫之病（土强湿去，正气自旺）。解酒毒，河豚毒（《备急方》∶ \n新汲水调末服，能解砒毒）。多食壅气，子粗圆、色白者入药，连皮炒，研用，亦有浸去皮 \n及生用者。",g:"补虚药"},
  "白术":{o:"白术",c:"补脾燥湿 \n苦燥湿（经曰∶脾苦湿，急食苦以燥之），甘补脾，温和中。在血补血，在气补气（同 \n血药则补血，同气药则补气），无汗能发，有汗能止（湿从汗出，湿去汗止。止汗同 、芍 \n之类，发汗加辛散之味）。燥湿则能利小便，生津液（既燥湿而又生津何也？汪机曰∶脾恶 \n湿，湿胜则气不得施化，津何由生？用白术以除其湿，则气得周流，而津液生矣），止泄泻 \n（凡水泻，湿也。腹痛肠鸣而泻，火也。水火相激则肠鸣。痛甚而泻，泻而痛减者食也。完 \n谷不化气虚也。在伤寒下利，则为邪热不杀谷也。久泻名脾泄，肾虚而命火衰，不能生土也 \n。有积痰壅滞，肺气不能下降，大肠虚而作泻者宜豁痰。有伤风泄泻者宜散风。如脾虚湿泻 \n者宜",g:"补虚药"},
  "白果":{o:"白果",c:"\\x一名银杏\\x \n涩，敛肺，去痰 \n甘苦而温。性涩而收。熟食温肺益气（色白属金，故入肺），定痰哮，敛喘嗽，缩小便， \n止带浊。生食降痰解酒，消毒杀虫（花夜开，人不得见，性阴，有小毒，故能消毒杀虫）。 \n多食则收涩太过，令人壅气胪胀，小儿发惊动疳（食千枚者死）。 \n浆，泽手面，浣油腻（时珍曰∶去痰浊之功，可以类推）。",g:"化痰止咳平喘药"},
  "白石英":{o:"白石英",c:"重，润肺 \n甘辛微温。肺、大肠经气分之药。润以去燥，利小便，实大肠。治肺痿吐脓，咳逆上气 \n。但系石类，祗可暂用（《十剂》曰∶湿可去枯，白石英、紫石英之属是也。湿，即润也。 \n按∶润药颇多，石药终燥，而徐之才取二石英为润剂，存其意可取）。白如水晶者良。",g:"其他"},
  "白矾":{o:"白矾",c:"涩，燥湿，坠痰 \n酸咸而寒，性涩而收。燥湿追涎，化痰坠浊，解毒生津，除风杀虫，止血定痛，通大、 \n小便，蚀恶肉，生好肉，除痼热在骨髓（髓为热所劫则空，故骨痿而齿浮）。治惊痫黄胆， \n血痛喉痹，齿痛风眼，鼻中息肉，崩带脱肛，阴蚀阴挺（阴肉挺出，肝经之火），疔肿痈疽， \n瘰疥癣，虎、犬、蛇、虫咬伤（时珍曰∶能吐风，热痰涎，取其酸苦涌泄也；治诸血痛、 \n阴挺、脱肛、疮疡，取其酸涩而收也；治风眼、痰饮、泄痢、崩滞，取其收而燥湿也；治喉 \n痹、痈蛊、蛇伤，取其解毒也）。多服损心、肺，伤骨（寇宗 曰∶劫水故也。书纸上，水 \n不能濡，故知其性劫水也。李迅曰∶凡发背，当服蜡矾丸以护膜，防毒瓦斯内攻。矾一两，黄",g:"清热药"},
  "白芍":{o:"白芍药",c:"补血，泻肝，涩，敛阴 \n苦酸微寒，入肝脾血分，为手、足太阴（肺脾）行经药。泻肝火（酸敛汗，肝以敛为泻， \n以散为补），安脾肺，固腠理（肺主皮毛，脾主肌肉。肝木不克土，则脾安。土旺能生金， \n则肺安。脾和肺安，则腠理固矣），和血脉，收阴气，敛逆气（酸主收敛），散恶血，利小便 \n（敛阴生津，小便自利，非通行之谓也），缓中止痛（东垣曰∶经曰损其肝者，缓其中，即 \n调血也）益气除烦，敛汗安胎，补劳退热。 \n治泻痢后重（能除胃中湿热），脾虚腹痛（泻痢俱太阴病，不可缺此，寒泻冷痛忌用。 \n虞天民曰∶白芍不惟治血虚，大能行气。古方治腹痛，用白芍四钱，甘草二钱，名芍药甘草 \n汤。盖腹痛因营气不从，逆于肉里，白",g:"补虚药"},
  "白芥子":{o:"白芥子",c:"宣，利气，豁痰 \n辛温入肺。通行经络，温中开胃，发汗散寒，利气豁痰，消肿止痛（痰行则肿消，气行 \n则痛止。为末醋调敷，消痈肿）。治咳嗽反胃，痹木香港脚，筋骨诸病（痰阻气滞）。久嗽肺虚 \n人禁用（丹溪曰∶痰在胁下及皮里膜外，非此不能达行。古方控涎丹用之，正此义。韩 三 \n子养亲汤，白芥子主痰，下气宽中；紫苏子主气，定喘止嗽；莱菔子主食，开痞降气。各微 \n炒研，看病所主为君。治老人痰嗽、喘满、懒食）北产者良。煎汤不可过熟，熟则力减。 \n芥菜子豁痰利气，主治略同。",g:"化痰止咳平喘药"},
  "白芷":{o:"白芷",c:"宣，发表，祛风，散湿 \n辛散风，温除湿，芳香通窍而表汗。行手足阳明（大肠、胃），入手太阴（肺，色白味 \n辛，故入肺），而为阳明主药（阳明之脉营于面，故治头面诸疾）。治阳明头目昏痛（杨吉老 \n方，白芷汤泡四、五遍，蜜丸弹子大，名都梁丸。每服一丸，荆芥点醋茶嚼下。杨吉老，名 \n介，治王定国病时在都梁，因以名丸），眉棱骨痛（风热与痰，同酒浸黄芩为末，茶下）牙 \n痛（上龈属足阳明，下龈属手阳明，二经风热）鼻渊（肺主鼻，风热乘肺，上烁于脑，故鼻 \n多浊涕而渊。经曰∶脑渗为涕，宜同细辛、辛夷治之），目痒泪出，面 （干去声，面黑气） \n瘢疵（可作面脂），皮肤燥痒，三经风热之病。及血崩血闭，肠风痔 ，痈疽疮疡",g:"解表药"},
  "白茅根":{o:"白茅根",c:"泻火，补中，止血，止哕 \n甘寒。入手少阴（心），足太阴、阳明（脾胃）。补中益气，除伏热，消瘀血，利小便， \n解酒毒。 \n治吐、衄诸血（心肝火旺，逼血上行，则吐血；肺火盛，则衄血。茅根甘和血，寒凉血 \n，引火下降，故治之。扑损瘀血，捣汁服。名茅花汤。亦治鼻衄产淋），血闭寒热（血瘀则 \n闭，闭则寒热作矣），淋沥崩中（血热则崩），伤寒哕逆（即呃逆。《说文》曰∶哕，气牾也。 \n东垣作干呕之甚者，未是），肺热喘急，内热烦渴，黄胆水肿（清火行水。时珍曰∶良药也， \n世人以微而忽之，惟事苦寒之剂，伤冲和之气，乌足知此哉）。 \n茅针，溃痈疖（酒煮服。一针溃一孔，二针溃二孔），口疮之神药。角蒿。",g:"止血药"},
  "白蔹":{o:"白蔹",c:"泻火，散结 \n苦能泄，辛能散，甘能缓，寒能除热。杀火毒，散结气，生肌止痛。 \n治痈疽疮肿，面上 疮，金疮扑损（箭镞不出者，同丹皮或半夏为末，酒服），敛疮方 \n多用之（故名，每与白芨相须），搽冻耳（同黄柏末油调）。 \n蔓赤，枝有五叶，根如卵而长，三五枝同窠，皮乌肉白。一种赤蔹，功用皆用（郑奠一 \n曰∶能治温疟血痢，肠风痔 ，赤白带下）。",g:"清热药"},
  "白薇":{o:"白薇",c:"泻血热 \n苦咸而寒，阴阳、冲、任之药。利阴气，下水气。 \n主中风身热支满，忽忽不知人（阴虚火旺，则内热主风。火气焚灼，故身热支满。痰随 \n火涌，故不知人），血厥（汗出过多血少，阳气独上，气塞不行而厥，妇人尤多。此证宜白 \n薇汤，白薇、当归各一两，参五钱，甘草钱半，每服五钱）热淋，温疟洒洒，寒热酸痛（寒 \n热作，则营气不能内营，故酸痛），妇人伤中淋露（血热。千金白薇散治胎前产后遗尿不知 \n时，白薇、芍药等分，酒调服。丹溪曰∶此即河间所谓热甚廷孔郁结，神无所依，不能收禁 \n之意也。廷孔，女人溺孔也），产虚烦呕（仲景安中益气竹皮丸用之。《经疏》曰∶古方调经 \n种子，往往用之。盖不孕缘于血热血少，而其",g:"清热药"},
  "白藓皮":{o:"白藓皮",c:"通，祛风湿 \n气寒善行，味苦性燥（行水故燥）。入脾、胃除湿热，兼入膀胱、小肠。行水道，通关 \n节，利九窍。 \n为诸黄、风痹之要药（一味白藓皮汤，治产后风。时珍曰∶世医止施之疮科，浅矣）。 \n兼 \n治风疮疥癣，女子阴中肿痛（湿热乘虚客肾与膀胱所致）。 \n根黄白而心实。取皮用。恶桑螵蛸、桔梗、茯苓、萆 。",g:"祛风湿药"},
  "白蜡":{o:"白蜡",c:"外用生肌 \n甘温属金。生肌止血（郑赞寰曰∶汪御章年十六，常患尿血，屡医不效。予以白蜡加入 \n冲血滋肾药中，遂愈），定痛补虚，续筋接骨，外科要药。",g:"其他"},
  "白豆蔻":{o:"白豆蔻",c:"宣，行气，暖胃 \n辛热。流行三焦，温暖脾胃（三焦利，脾胃运，则诸证自平矣）而为肺家本药（肺主气）。 \n散滞气，消酒积，除寒燥湿，化食宽膨。 \n治脾虚疟疾，感寒腹痛，吐逆反胃（肺胃火盛及气虚者禁用），白睛翳膜（白睛属肺， \n能散肺滞），太阳经目 红筋（太阳脉起目 ）。 \n番舶者良，研细用。",g:"化湿药"},
  "白附子":{o:"白附子",c:"燥，祛风湿，治面疾 \n辛甘有毒，大热纯阳。阳明经药，能引药势上行，治面上百病（阳明之脉萦于面，白附 \n能去头面游风。作面脂，消斑疵）。补肝虚，祛风痰，治心痛血痹，诸风冷气，中风失音， \n阴下湿痒。 \n根如草乌之小者，长寸许，皱纹有节，炮用（陶宏景曰∶此药久绝，无复真者，今惟凉 \n州生）。",g:"化痰止咳平喘药"},
  "白马溺":{o:"白马溺",c:"泻，杀虫，消症 \n辛寒。杀虫，破症积，治反胃，（祖台之志怪云∶昔有人与奴皆患心腹痛病，奴死，剖 \n之得一鳖，尚活。以诸药投口中，不死。有人乘白马观之，马溺坠鳖而鳖缩，遂以灌之，即 \n化成水。主乃服马溺而愈）。",g:"驱虫药"},
  "百合":{o:"百合",c:"润肺止嗽 \n甘平。润肺宁心，清热止嗽，益气调中，止涕泪（涕泪，肺肝热也。经曰∶肺为涕，肝 \n为泪，心为汗，脾为涎，肾为唾），利二便。治浮肿胪胀，痞满寒热，疮肿乳痈，伤寒百合 \n病（行住坐卧不安，如有鬼神状。苏颂曰∶病名百合，而用百合治之，不识其义。李士材曰 \n∶亦清心安神之效耳。朱二允曰∶久嗽之人，肺气必虚，虚则宜敛。百合之甘敛，胜于五味 \n之酸收）。花白者入药。",g:"补虚药"},
  "百沸汤":{o:"百沸汤",c:"宣，助阳气 \n助阳气，行经络（汪颖曰∶汤须百沸者佳。寇宗 曰∶患风冷气痹，人以汤淋脚至膝， \n浓复取汗，然别有药，特假阳气而行耳。四时暴泻痢，四肢、脐、腹冷，坐深汤中，浸至腹 \n上，生阳之药，无速于此。张从正曰∶凡伤风寒、酒食，初起无病，便饮太和汤。或酸荠水 \n揉肚探吐，汗出即已。昂按∶感冒风寒，而以热汤澡浴，亦发散之一法。故《内经》亦有可 \n汤熨、可浴及摩之、浴之之文。《备急方》治心腹卒胀痛，欲死，煮热汤以渍手足，冷即易 \n之）。",g:"其他"},
  "百草霜":{o:"百草霜",c:"轻，止血，消积 \n辛温。止血（鼻衄者，水调涂之。红见黑则止，水克火也）消积。治诸血病，伤寒阳毒、 \n发斑，疸膈疟痢，咽喉、口舌、白秃、诸疮（时珍曰∶皆兼取火化从治之法）。灶突上烟煤。",g:"其他"},
  "百部":{o:"百部",c:"润肺，杀虫 \n甘苦微温。能润肺，治肺热咳嗽（苦能泻热）。有小毒，杀蛔、蛲、蝇、虱，一切树木 \n蛀虫（触烟即死）。 \n治骨蒸传尸，疳积疥癣（皆有虫。时珍曰∶百部亦天冬之类，故皆治肺而杀虫，但天冬 \n寒，热嗽宜之；百部温，寒嗽宜之）。 \n根多成百故名。取肥实者，竹刀劈去心皮，酒浸焙用。",g:"化痰止咳平喘药"},
  "皂矾":{o:"皂矾",c:"\\x一名绿矾\\x \n涩，燥湿，化痰 \n酸涌涩收。燥湿化痰、解毒杀虫之功与石矾同，而力差缓。主治略同白矾，利小便，消 \n食积（同健脾消食药为丸），散喉痹（醋调咽汁。时珍曰∶胀满、黄肿、疟痢、疳疾方往往 \n用之。其源则自仲景用矾石硝石治女劳黄胆方中变化而来）。深青莹净者良。 赤用（ 赤 \n名绛矾，能入血分，伐肝木，燥脾湿。张三丰治肿满，有伐木丸。苍术二斤，米泔浸，黄酒， \n面曲四两炒，绛矾一斤，醋拌晒干，入瓶。火 为末，醋糊丸，酒下。或去皂矾乃铜之精液， \n用醋制以平肝，胜于针铁。不必忌盐，后亦不发。多服令人泻）。",g:"补虚药"},
  "皂角":{o:"皂角",c:"通关窍，搜风 \n辛咸性燥，气浮而散。入肺、大肠经。金胜木，燥胜风，故兼入肝。搜风泄热，吹之导 \n之，则通上、下关窍，而涌吐痰涎，搐鼻立作喷嚏。 \n治中风口噤，胸痹喉痹（凡中风不省人事，口噤不能进药。急提头发，手掐人中，用皂 \n角末或半夏末吹入鼻中，有嚏者生，无嚏者肺气已绝，死。或用稀涎散吐之，皂角末一两， \n白矾五钱，每用一钱，温水调灌。或加藜芦、少麝，鹅翎探喉，令微吐稀涎，再用药治。年 \n老、气虚人忌用）。服之则除湿去垢（最去油腻，刮人肠胃），消痰破坚（取中段，汤泡服， \n治老人风秘），杀虫下胎。治风湿风癞，痰喘肿满，坚症囊结（厥阴肝脉络阴器。寒客肝经， \n则为囊结）。涂之则散肿消毒，煎膏贴",g:"驱虫药"},
  "皮":{o:"皮",c:"泻，凉血 \n苦平。治肠风泻血，五痔（烧末，油调敷，水服亦佳）阴肿。脂滴耳中治聋。胆点痘后 \n风眼。似鼠而圆大，褐色，攒毛，外刺如栗房。 黑存性用。",g:"清热药"},
  "益智仁":{o:"益智子",c:"燥脾肾，补心肾 \n辛热。本脾药，兼入心、肾。主君相二火，补心气、命门、三焦之不足（心为脾母，补 \n火故能生土），能涩精固气（《本草》未载）。又能开发郁结，使气宣通（味辛能散），温中进 \n食，摄涎唾（胃冷则涎涌），缩小便（肾与膀胱相表里，益智辛温固肾。盐水炒，同乌药等 \n分，酒煮山药糊丸，盐汤下，名缩泉丸）。 \n治呕吐泄泻，客寒犯胃，冷气腹痛，崩带泄精（涩精固气。因热而崩浊者禁用）。 \n出岭南，形如枣核，用仁。",g:"补虚药"},
  "益母草":{o:"益母草",c:"\\x一名茺蔚\\x \n通行瘀血，生新血 \n辛微苦寒。入手、足厥阴（心包、肝）。消水行血，去瘀生新，调经解毒（瘀血去则经 \n调）。 \n治血风血晕，血痛血淋，胎痛产难，崩中带下（带脉横于腰间，病生于此，故名为带。 \n赤属血，白属气。气虚者，补中益气而兼升降。血虚者，养血滋阴而兼调气）。为经产良药 \n，消疔肿乳痈（亦取其散瘀解毒），通大小便。然辛散之药，瞳子散大者忌服。 \n益母子主治略同，调经益精，明目（血滞病目者则宜之）活血，顺气逐风（气行则血行， \n血活则风散），行中有补。治心烦头痛（血虚血热之候），胎产带崩，令人有子（有补阴之功。 \n时珍曰∶益母根茎花叶实，皆可同用。若治疮肿胎产，消水行血，则宜",g:"活血化瘀药"},
  "瞿麦":{o:"瞿麦",c:"通，利水，破血 \n苦寒。降心火，利小肠，逐膀胱邪热，为治淋要药（故八正散用之。五淋大抵皆属湿热 \n，热淋宜八正及山栀、滑石之类；血淋宜小蓟、牛膝；膏肾虚淋宜补肾，不可独泻；老人气 \n虚者，宜参、术兼木通、山栀；亦有痰滞中焦作淋者，宜行痰兼通利药，最忌发汗，汗之必 \n便血）。破血利窍，决痈消肿，明目去翳，通经堕胎。性利善下，虚者慎用（寇宗 曰∶心 \n经虽有热，而小肠虚者服之，则心热未清，而小肠别作病矣）。 \n花大如钱，红白斑斓，色甚斌媚，俗呼洛阳花。用蕊、壳。丹皮为使。恶螵蛸（产后淋 \n当去血，瞿麦、蒲黄皆为要药）。",g:"利水渗湿药"},
  "知母":{o:"知母",c:"泻火补水，润燥滑肠 \n辛苦寒滑。上清肺金而泻火（泻胃热、膀胱邪热、肾命相火），下润肾燥而滋阴，入二 \n经气分（黄柏入二经血分，故二药必相须而行）。消痰定嗽，止渴安胎（莫非清火之用）。 \n治伤寒烦热，蓐劳（产劳）骨蒸（退有汗之骨蒸），燥渴虚烦，久疟下痢（治嗽者，清 \n肺火也。治渴者，清胃热也。退骨蒸者，泻肾火也），利二便，消浮肿（小便利则肿消。东 \n垣曰∶热在上焦气分，结秘而渴，乃肺中伏热，不能生水，膀胱绝其化源。宜用渗湿之药， \n泻火清金，滋水之化源。热在下焦血分，便闭而不渴，乃真水不足，膀胱干涸，无阴则阳无 \n以化。宜用黄柏、知母大苦寒之药，滋肾与膀胱之阴。而阳自化，小便自通。丹溪曰∶小便 ",g:"清热药"},
  "石":{o:"石",c:"重，燥，祛寒积 \n辛热，有大毒。治坚癖痼冷，寒湿风痹（苏恭曰∶攻寒冷之病最良。《别录》曰∶不炼 \n服，杀人。此石生于山无雪，入水不冰。时珍曰∶性气与砒石相近。《博物志》言∶鹳伏卵 \n时，取此石暖足。谬也）。有疮、白数种，火烧但解散，不能脱其坚。置水不冻者真。恶羊 \n血。",g:"其他"},
  "石决明":{o:"石决明",c:"泻风热，明目 \n咸平。除肺、肝风热，青盲内障，水飞点目外障。亦治骨蒸劳热。通五淋（能清肺、肝 \n故也，古方多用治疡疽），解酒酸（为末，投热酒中，即解）。如蚌而扁，唯一片无对，七孔 \n、九孔者良。盐水煮一伏时，或面裹煨熟，研粉极细，水飞用。恶旋复花。",g:"平肝息风药"},
  "石南叶":{o:"石南叶",c:"宣，去风，补肾 \n辛散风、苦坚肾。补内伤阴衰，利筋骨皮毛，为治肾虚、脚弱、风痹要药。妇人不可久 \n服，令思男（时珍曰∶今人绝不知用，盖为《药性论》有令人阴痿之说也。不知此药能令肾 \n强，人或借此纵欲，以致痿弱，归咎于药，良可慨也。昂按∶石南补阴祛风则有之，然味辛 \n不热，不助相火，亦未闻淫邪方中用石南者，《别录》思男之说，殆不可信）。 \n关中者佳。炙用。",g:"祛风湿药"},
  "石斛":{o:"石斛",c:"平补肝肾 \n甘淡入脾，而除虚热，咸平入肾，而涩元气。益精，强阴，暖水脏，平胃气，补虚劳， \n壮筋骨。 \n疗风痹脚弱，发热自汗，梦遗滑精，囊涩余沥（雷 曰∶石斛镇髓。昂按∶石斛石生 \n之草，体瘦无汁，味淡难出。置之煎剂，猝难见功，必须熬膏，用之为良）。 \n光泽如金钗，股短而中实，生石上者良，名金钗石斛。长而虚者名水斛，不堪用。去 \n头、根，酒浸用。恶巴豆。畏僵蚕。细锉水浸，熬膏更良。",g:"补虚药"},
  "石榴皮":{o:"石榴皮",c:"涩肠，外用染须 \n酸涩而温。能涩肠，止泻痢下血（ 末服），崩带脱肛（泻痢至于脱肛者，以石榴皮、 \n陈壁土加明矾少许，浓煎熏洗，再用五倍子炒研、敷托而止之）。浸水，汁黑如墨，乌须方 \n绿云油中用之。勿犯铁器（《客座新闻》云∶一人患腹胀，夏成诊曰∶饮食如常，非水肿蛊 \n胀，乃湿热生虫之象也。以石榴、椿树东引根皮、槟榔各五钱，空心服，腹大痛，泻虫长丈 \n余，遂愈）。",g:"收涩药"},
  "石灰":{o:"石灰",c:"重，燥湿，止血，生肌 \n辛温性烈。能坚物散血，定痛生肌，止金疮血（腊月用黄牛胆汁和，纳胆中，阴干用）， \n杀疮虫（有人脚肚生一疮，久遂成漏，百药不效，自度必死。一村人见之曰∶此鳝漏也。以 \n锻石温泡、熏洗、觉痒即是也。洗不数次，遂愈）蚀恶肉，无瘢疵（和药点痣）解酒酸（酒 \n家多用之，然有灰之酒伤人），内用止泻痢、崩带，收阴挺（阴肉挺出，亦名阴菌，或产后 \n玉门不闭。熬黄水泡，澄清暖洗）、脱肛，消积聚、结核。风化者良。 \n圹灰，火毒已出，主顽疮、脓水淋漓，敛口尤妙。",g:"化湿药"},
  "石硫黄":{o:"石硫黄",c:"燥，补阳，杀虫 \n味酸有毒。大热纯阳（硫黄阳精极热，与大黄极寒，并号将军），补命门真火不足。性 \n虽热而疏利大肠，与燥涩者不同（热药多秘，惟硫黄暖而能通；寒药多泄，惟黄连肥汤而止 \n泻），若阳气暴绝，阳毒伤寒，久患寒泻，脾胃虚寒，命欲垂尽者用之，亦救危妙药也。治 \n寒痹冷癖，足寒无力，老人虚秘（《局方》用半硫丸），妇人阴蚀，小儿慢惊。暖精壮阳，杀 \n虫疗疮，辟鬼魅，化五金，能干汞（王好古曰∶太白丹、来复丹皆用硫黄佐以硝石∶至阳佐 \n以至阳，与仲景白通汤佐以人尿、猪胆汁意同。所以治内伤生冷，外冒暑湿、霍乱诸病。能 \n除扦格之寒，兼有伏阳，不得不尔。如无伏阳，只是阴虚，更不必以阴药佐之。《夷坚志》",g:"驱虫药"},
  "石膏":{o:"石膏",c:"体重，泻火气，轻，解肌 \n甘辛而淡，体重而降。足阳明经（胃）大寒之药。色白入肺，兼入三焦（诸经气分之药）。 \n寒能清热降火，辛能发汗解肌，甘能缓脾益气，生津止渴。治伤寒郁结无汗，阳明头痛， \n发热恶寒，日晡潮热。肌肉壮热（经云∶阳盛生外热），小便赤浊，大渴引饮，中暑自 \n汗（能发汗，又能止自汗），舌焦（胎浓无津）牙痛（阳明经热，为末擦牙固齿）。又胃 \n主肌肉，肺主皮毛，为发斑、发疹之要品（色赤如锦纹者为斑，隐隐见红点者为疹，斑 \n重而疹轻。率由胃热，然亦有阴阳二证，阳证宜用石膏。又有内伤阴证见斑疹者，微红 \n而稀少，此胃气极虚，逼其无根之火游行于外，当补益气血，使中有主，则气不外游， \n血不外",g:"清热药"},
  "石菖蒲":{o:"石菖蒲",c:"宣，通窍，补心 \n辛苦而温，芳香而散。补肝益心，开心孔，利九窍，明耳目，发音声。去湿逐风，除 \n痰消积，开胃宽中。 \n疗噤口毒痢（杨土瀛曰∶噤口虽属脾虚，亦热闭胸膈所致。用木香 \n失之温，山药失之闭，唯参苓白术散加菖蒲，米饮下，胸次一开，自然思食。菖蒲黍米酸酒， \n治一切风），风痹惊痫，崩带胎漏，消肿止痛，解毒杀虫（李士材曰∶《仙经》称为水草之精 \n英，神仙之灵药，用泔浸饭上蒸之，借谷气而臻于中和，真有殊常之效。又曰∶芳香利窍， \n心脾良药，能佐地黄、天冬之属，资其宣导，若多用、独用，亦耗气血而为殃。李士材，着 \n《药性解》、《本草通玄》）。 \n根瘦节密，一寸九节者良。去皮，微炒用。秦艽为使。",g:"开窍药"},
  "石蟹":{o:"石蟹",c:"重，泻，明目 \n咸寒。治青盲目翳，天行热疾，解一切金石药毒。醋磨，敷痈肿。出南海。身全是蟹， \n而质石也。细研，水飞用。",g:"其他"},
  "石韦":{o:"石韦",c:"通淋，补劳 \n甘苦微寒。清肺金以滋化源（凡行水之药，必皆能先清肺火），通膀胱而利水道。益精 \n气，补五劳（利湿清热之功。高阳生对宣帝治劳伤，用石韦计）。治淋崩发背（炒末，冷调， \n酒服）。 \n生石阴，柔韧如皮，背有黄毛。去毛，微炙用。杏仁、滑石、射干为使，得菖蒲良。生 \n古瓦上者名瓦韦，治淋。",g:"利水渗湿药"},
  "石首鱼":{o:"石首鱼",c:"补，调胃 \n甘平。开胃消食，治暴痢腹胀（《菽园杂记》曰∶痢疾最忌油腻、生冷，惟白鲞相宜。 \n以其无脂不腻，而能消宿食、理肠胃也）。即干白鱼鲞，首中有石，故名（石治石淋。昂按∶ \n今人多以石首鱼鳔合破故纸等药为丸，名鱼鳔丸，云暖精种子。而《本草》全未之及，何也 \n）。",g:"消食药"},
  "砂":{o:"砂",c:"泻，消肉积 \n咸苦辛热，有毒。消食破瘀。治噎膈症瘕，去目翳 肉，暖子宫，助阳道（性大热，能 \n烂五金。《本草》称其能化人心为血，亦甚言不可多服耳。凡煮硬肉，投少许即易烂，故治 \n噎膈、症瘕、肉积有殊功。《鸡峰方》云∶人之脏腑，多因触冒成病，而脾胃最易受触。饮 \n食过多，则停滞难化。冷热不调，则呕吐泻痢，而膏梁者为尤甚。口腹不节，须用消化药。 \n或言饮食既伤于前，难以毒药反攻其后，不使 砂、巴豆等，只用曲、柏之类。不知古今立 \n方用药，各有主对。曲、柏只能消化米谷，如伤肉食，则非 砂、阿魏不能治也；如伤鱼、 \n蟹，须用橘叶、紫苏、生姜；伤菜果，须用丁香、桂心；伤水饮，须用牵牛、芫花，必审所 \n伤",g:"消食药"},
  "砂仁":{o:"砂仁",c:"\\x即缩砂 \\x \n宣，行气，调中 \n辛温香窜。补肺益肾，和胃醒脾，快气调中，通行结滞。 \n治腹痛痞胀（痞滞，有伤寒下早里虚邪入而痞者；有食壅痰塞而痞者；有脾虚气弱而痞 \n者。须分虚实治之，不宜专用利气药，恐变为鼓胀。鼓胀，内胀而外有形；痞胀，惟觉痞闷 \n而已，皆太阴为病也），噎膈呕吐，上气咳嗽，赤白泻利（湿热积滞，客于大肠，砂仁亦入 \n大小肠经），霍乱转筋，奔豚崩带。祛痰逐冷，消食醒酒，止痛安胎（气行则痛止，气顺则 \n胎安），散咽喉口齿浮热，化铜铁骨鲠（王好古曰∶得檀香、豆蔻入肺，得人参、益智入脾， \n得黄柏、茯苓入肾，得赤石脂入大、小肠。《医通》曰∶辛能润肾燥，引诸药归宿丹田，地 \n黄用之",g:"化湿药"},
  "砒石":{o:"砒石",c:"大燥，劫痰 \n辛苦而咸。大热大毒，砒霜尤烈。专能燥痰，可作吐药。疗风痰在胸膈，截疟除哮。外 \n用蚀败肉，杀虫枯痔。出信州，故名信石，衡州次之。锡之苗也（故锡壶亦云有毒）。生者 \n名砒黄，炼者名砒霜。畏绿豆、冷水、羊血。",g:"驱虫药"},
  "硼砂":{o:"硼砂",c:"润，生津，去痰热 \n甘微咸凉。色白质轻，故除上焦胸膈之痰热，生津止嗽。治喉痹、口齿诸病（初觉喉中 \n肿痛，含化咽津，则不成痹）。能金而去垢腻，故治噎膈积块，结核 肉，目翳骨哽（碱 \n能软坚，含之咽汁）。出西番者，白如明矾，出南番者，黄如桃胶。能制汞、哑铜（硼砂、 \n砂，并可作金银焊）。",g:"其他"},
  "碱":{o:"碱",c:"\\x一作碱\\x \n泻，磨积，去垢 \n辛苦涩温。消食磨积，去垢除痰。治反胃噎膈，点痣、 、疣、赘（与矿灰等分，用小 \n麦杆灰，煎干为末。挑破痣，三点即瘥）。发面，浣衣用之。取蓼蒿之属，浸晒烧灰，以原 \n水淋汁，每百斤入粉面二三斤，则凝定如石。",g:"消食药"},
  "磁石":{o:"磁石",c:"重，补肾 \n辛咸。色黑属水，能引肺金之气入肾。补肾益精，除烦祛热，通耳明目（耳为肾窍，肾 \n水足，则目明）。治羸弱周痹，骨节酸痛（肾主骨），惊痫（重镇怯）肿核（咸软坚），误吞 \n针铁（末服），止金疮血（《十剂》曰∶重可去怯，磁石、铁粉之属是也。《经疏》云∶石药 \n皆有毒，独磁石冲和，无悍猛之气。又能补肾益精，然体重渍酒优于丸散。时珍曰∶一士病 \n目渐生翳，珍以羌活胜湿汤加减，而以磁朱丸佐之，两月而愈。盖磁石入肾，镇养真阴，使 \n神水不外移；朱砂入心，镇养心血，使邪火不上侵；佐以神曲，消化滞气，温养脾胃生发之 \n气，乃道家黄婆媒合婴 之理。方见孙真人《千金方》，但云明目，而未发出用药微义也。 \n",g:"安神药"},
  "礞石":{o:"礞石",c:"重，泻痰 \n甘威有毒，体重沉坠。色青入肝，制以硝石，能平肝下气，为治惊利痰之圣药（吐痰在 \n水上，以石末掺之，痰即随下。王隐君有礞石滚痰丸，能治百病。礞石、焰硝各二两， 研 \n，水飞净一两，大黄酒蒸八两，黄芩酒洗八两，沉香五钱，为末，水丸，量虚实服。时珍曰 \n∶风木太过，来制脾土，气不运化，积滞生痰，壅寒上、中二焦，变生诸证。礞石重坠，硝 \n性疏快，使痰积通利，诸证自除）。气弱脾虚者禁用。坚细青黑，中有白星点。硝石、礞石 \n等分，打碎拌匀，入坩锅 至硝尽、石色如金为度。如无金星者不入药。研末水飞，去硝毒 \n用。",g:"平肝息风药"},
  "神曲":{o:"神曲",c:"宣，行气，化痰，消食 \n辛散气，甘调中，温开胃。化水谷，消积滞（《医余》云∶有伤粽子成积，用曲末少加 \n木香，盐汤下，数日口中闻酒香，积遂散）。治痰逆症结，泻痢胀满。回乳（炒研，酒服二 \n钱，日二）下胎（产后血晕，末服亦良），亦治目病（《启微集》云∶生用，能发其生气；熟 \n用，能敛其暴气）。造曲法，以五月五日，六月六日，用白面百斤，赤豆末、杏仁泥、青蒿、 \n苍耳、红蓼汁各三升，以配青龙、白虎、朱雀、玄武、 蛇、勾陈六神，通和作饼， 生黄 \n衣，晒收。陈者良。炒用。",g:"消食药"},
  "禹余粮":{o:"禹余粮",c:"重，涩固下 \n甘平性涩。手、足阳明（大肠、胃）血分重剂。治咳逆下痢，血闭（症瘕）血崩，能固 \n下（李先知云∶下焦有病患难会，须用余粮、赤石脂），又能催生。石中黄粉，生于池泽。 \n无砂者良。牡丹为使。",g:"其他"},
  "秋石":{o:"秋石",c:"补肾水，润三焦 \n咸温。滋肾水，润三焦，养丹田，安五脏，退骨蒸，软坚块。治虚劳咳嗽，白浊遗精， \n为滋阴降火之圣药。若煎炼失道，多服误服，反生燥喝之患（咸能走血，且经 炼，中寓暖 \n气，使虚阳妄作，则真水愈亏。）《蒙筌》曰∶每月取童便，每缸用石膏七钱，桑条搅澄， \n倾去清液，如此二三次，乃入秋露水搅澄（故名秋石）如此数次，滓秽净，咸味减，以重纸 \n铺灰上晒干，刮去在下重浊，取轻清者为秋石。世医不取秋时，杂收人溺，以皂荚水澄晒为 \n阴炼，火 为阳炼，尽失于道，安能应病？况经火炼，性却变温耶（秋石再研入罐，铁盏盖 \n定，盐泥固济升打，升起盏上者名秋冰。味淡而香，乃秋石之精英也。《保寿堂方》∶用童男",g:"补虚药"},
  "秦皮":{o:"秦皮",c:"涩而补，明目 \n苦寒，色青，性涩。补肝胆而益肾。以能平木（能除肝热）故治目疾（洗目赤，退翳膜） \n惊痫。以其收涩而寒，故治崩带下痢（仲景白头翁汤用之）。以其涩而补下焦，故能益精有 \n子（时珍曰∶天道贵啬，惟收涩故能补。今人只知治目一节，几于废弃，良为可婉）。出西 \n土。皮有白点、渍水碧色、书纸不脱者真。大戟为使。恶吴茱萸。",g:"其他"},
  "秦艽":{o:"秦艽",c:"宣，去寒湿 \n苦燥湿，辛散风。去肠胃之热，益肝胆之气，养血荣筋（风药中润剂，散药中补剂）。 \n治风寒湿痹（经曰∶风寒湿三气杂至，合而为痹。风胜为行痹，寒胜为痛痹，湿胜为着 \n痹。痹在于骨则体重，在脉则血涩，在筋则拘挛，在肉则不仁，在皮则寒），通身挛急，（血 \n不荣筋），虚劳骨蒸（时珍曰∶手足阳阴经药，兼入肝胆。阳明有湿，则手足酸痛寒热，有 \n热则日晡潮热骨蒸。《圣惠方》治急劳烦热，秦艽、柴胡各一两，甘草五钱，为末，每服三 \n钱。治小儿骨蒸潮热食减瘦弱，秦艽、炙甘草各一两，每服一二钱，钱乙加薄荷五钱），疸 \n黄酒毒，肠风泻血，口噤牙痛（齿下龈属手阳明大肠经。张洁古曰∶秦艽能去下牙痛，及本 \n经风",g:"祛风湿药"},
  "稷":{o:"稷",c:"补、和中 \n甘平。益气和中，宣脾利胃（陶宏景曰∶稷米，人亦不识。书记多云黍与稷相似，又注 \n∶黍米云 米。与黍米相似，而粒殊大，食之不宜，人发旧病。《诗》云∶黍稷稻粱，禾麻 \n菽麦，此八谷也。俗犹不能辨证，况芝英乎？按∶黍、稷辨者颇多，皆无确义。李时珍曰∶ \n稷、黍一类二种。粘者为黍，不粘者为稷。昂谓∶诗人既云八谷，何必取一类者强分二种？ \n是仍为七谷矣。盖 、稷同音，故世妄谓 为稷，不知 乃黍类似粟，而粒大疏散，乃北方 \n下谷，南土全无，北人亦不之重，安能度越粳、糯而高踞八谷之上乎？陶氏所说，因是 黍 \n，所以疑也。若稷当属高硕如芦，世之所谓芦稷者，实既香美，性复中和，干又高硕，所以 \n能为",g:"解表药"},
  "空青":{o:"空青",c:"重，明目 \n甘酸而寒。益肝明目，通窍利水。产铜坑中。大块、中空有水者良。",g:"利水渗湿药"},
  "穿山甲":{o:"穿山甲",c:"\\x一名鲛鲤\\x \n宣，通经络 \n咸寒善窜（喜穿山），专能行散，通经络，达病所（某处病，用某处之甲，更良），入厥 \n阴、阳明（肝、胃）。治风湿冷痹。通经下乳，消肿溃痈，止痛排脓，和伤发痘（元气虚者 \n慎用）。风、疟、疮科为要药（以其穴山寓水，故能出入阴阳，贯穿经络，达于营分，以破 \n邪结，故用为使），以其食蚁，又治蚁 （漏也，音闾，亦音漏。有妇人项下忽肿一块，渐 \n延至颈，偶刺破，出水一碗，疮久不合。有道人曰∶此蚁漏也，缘饭中偶食蚁得之。用穿山 \n甲烧，存性为末，敷之立愈。刘伯温《多能鄙事》云∶油笼渗漏，刮甲里肉 投入，自至漏 \n处补住。《永州记》云∶不可于堤岸杀之。恐血入土，则岸堤渗漏。观此",g:"其他"},
  "童便":{o:"童便",c:"\\x一名还元水。饮自己溺，名轮回酒\\x \n平，泻火，补阴，散瘀血 \n咸寒（时珍曰温）。能引肺火下行从膀胱出，乃其旧路，降火滋阴甚速。润肺散瘀（咸 \n走血），治肺痿失音，吐衄损伤（凡跌打损伤、血闷欲死者，擘开口以热尿灌之，下咽即醒。 \n一切金疮受杖，并宜用之，不伤脏腑。若用他药，恐无瘀者，反致误人矣），胞胎不下（皆 \n散瘀之功）。凡产后血晕，败血入肺，阴虚久嗽，火蒸如燎者，惟此可以治之（晋褚澄《劳 \n极论》曰∶降火甚速，降血甚神。饮溲溺百无一死，服寒凉药百无一生）取十二岁以下童子 \n（少知识，无相火），不食荤、腥、酸、咸者佳。去头尾，取中间一节清沏如水者，用当热 \n饮。热则真气尚存，其行自速，冷",g:"补虚药"},
  "竹沥":{o:"竹沥",c:"泻火，滑痰，润燥 \n甘寒而滑。消风降火，润燥行痰，养血益阴（竹之有沥，犹人之有血也。故能补阴清火） \n。利窍明目。 \n治中风口噤，痰迷大热，风痉癫狂，烦闷（《产乳》方∶妊娠苦烦名子烦，竹沥不限多 \n少细服。梅师加茯苓煎）消渴，血虚自汗。然寒胃滑肠、有寒湿者勿服（《经疏》曰∶中风 \n要药。凡中风未有不因阴虚火旺、痰热壅结所致，如果外来风邪，安得复用此寒滑之药治之 \n哉！丹溪曰∶痰在经络、四肢、皮里、膜外者，非此不能达行。又曰∶味甘性缓，能除阴虚 \n之有大热者。寒而能补，胎后不碍虚，胎前不损子。世人因本草大寒二字，弃而不用，然人 \n食笋，至老未有因寒而病者。沥，即笋之液也，又假火而成，何寒如此之甚",g:"补虚药"},
  "竹茹":{o:"竹茹",c:"泻上焦烦热，凉血 \n甘而微寒。开胃土之郁，清肺金之燥，凉血除热。治上焦烦热（皮入肺，主上焦。温胆 \n汤用之），温气寒热，噎膈呕逆（胃热），吐血衄血（清肺凉胃，齿血不止，浸醋含之），肺 \n痿惊痫（散肝火），崩中胎动（凉胎气）。",g:"化痰止咳平喘药"},
  "粟":{o:"粟",c:"补肾 \n甘咸微寒。养肾益气。治胃热消渴，止霍乱，利二便（《千金方》粟米粉水丸，梧子大 \n，煮七枚，纳醋中，细吞之，治反胃吐食）。即粱米。有青、黄、赤、白、黑诸色，陈者良 \n。",g:"其他"},
  "粪清":{o:"粪清",c:"\\x一名金汁\\x \n泻火热 \n主治同人中黄。用棕皮棉纸，上铺黄土，淋粪滤汁，入新瓮，碗复埋土中一年，清若泉 \n水，全无秽气用。年久者弥佳（野间残粪下土，筛敷痈疽，如冰着背）。",g:"清热药"},
  "粳米":{o:"粳米",c:"\\x粳，硬也\\x \n补脾清肺 \n甘凉。得天地中和之气，和胃补中，色白入肺。除烦清热，煮汁止渴（仲景白虎汤、桃 \n花汤、竹叶石膏汤，并用之以清热、补不足。张文潜《粥记》∶粥能畅胃气，生津液，每晨 \n空腹食之，所补不细。昂按∶今人终日食粥，不知其妙。迨病中食之，觉与脏腑相宜，迥非 \n他物之所能及也）。粳，乃稻之总名，有早、中、晚三收。晚者得金气多，性凉，尤能清热 \n（北粳凉，南粳温，白粳凉，红粳温，新米食之动气）。 \n陈廪米冲淡可以养胃，煮汁煎药，亦取其调肠胃、利小便、去湿热，除烦渴之功（《集 \n成》云∶陈米饭扎作团，火 存性，麻油，腻粉调，敷一切恶疮、百药不效者）。",g:"清热药"},
  "糯米":{o:"糯米",c:"\\x糯，懦也。《本草》名稻米。按∶《诗》，黍、稷、稻、粱、禾、麻、菽、麦，名八\\x \n\\x此稻与禾所以有异乎。\\x \n补温脾肺 \n甘温。补脾、肺虚寒，坚大便，缩小便，收自汗（同龙骨、牡蛎为粉，能扑汗），发痘 \n疮（解毒化脓）。然性粘滞，病患及小儿忌之（糯米酿酒则热，熬饧尤甚。饧即饴糖，润肺 \n和脾，化痰止嗽。仲景建中汤用之，取其甘以补脾缓中。多食发湿热、动痰火、损齿）。",g:"清热药"},
  "紫檀":{o:"紫檀",c:"重，和血 \n咸寒。血分之药。和荣气，消肿毒，敷金疮，止血定痛。",g:"其他"},
  "紫河车":{o:"紫河车",c:"\\x即胞衣，一名混沌皮\\x \n大补气血 \n甘咸性温。本人之血气所生，故能大补气血，治一切虚劳损极（虚损∶一损肺，皮槁毛 \n落；二损心，血脉衰少；三损脾，肌肉消脱；四损肝，筋缓不收；五损肾，骨痿不起。六极 \n，曰气极、血极、筋极、肌极、骨极、精极），恍惚失志癫痫。以初胎及无病妇人者良。有 \n胎毒者害人（以银器插入，焙煮，不黑则无毒）。长流水洗极净，酒蒸焙干研末。或煮烂捣 \n碎入药（如新瓦炙者，反损其精汁），亦可调和煮食（李时珍曰∶崔行功《小儿方》云∶胞 \n衣宜藏天德月德吉方，深埋紧筑。若为猪、狗食，令儿癫狂；蝼蚁食，令儿疮癣；鸟雀食， \n令儿恶死；弃火中，令儿疮烂；近社庙、井、灶、街巷，皆有所忌",g:"补虚药"},
  "紫石英":{o:"紫石英",c:"重，镇心，润，补肝 \n甘平。性温而补，重以去怯，湿以去枯。入心、肝血分，故心神不安，肝血不足，女子 \n血海虚寒不孕者宜之（冲为血海，任主胞胎。《经疏》云∶女子系胞于肾及心包络，虚则风 \n寒乘之，故不孕。紫石英辛温，走二经，散风寒，镇下焦，为暖子宫之要药）。色深紫莹彻 \n，五棱。火 、醋淬七次，研末水飞用。二英俱畏附子。恶黄连（石英五色，各入五脏）。",g:"其他"},
  "紫花地丁":{o:"紫花地丁",c:"泻热，解毒 \n辛苦而寒。 \n治痈疽发背，疔肿瘰 ，无名肿毒。 \n叶如柳而细，夏开紫花结角，生平地者起茎，生沟壑者起蔓。",g:"清热药"},
  "紫苏":{o:"紫苏",c:"宣，发表，散寒 \n味辛入气分，色紫入血分。香温散寒，通心利肺，开胃益脾（气香入胃），发汗解肌， \n和血下气，宽中消痰，祛风定喘，止痛安胎，利大、小肠，解鱼、蟹毒。多服泄人真气（时 \n珍曰∶同陈皮、砂仁，行气安胎；同霍香、乌药，温中止痛；同香附、麻黄，发热解肌；同 \n芎、当归，和血散血；同桔梗、枳壳，利膈宽肠；同卜子、杏仁，消痰定喘；同木瓜、浓 \n朴，散温解暑治霍乱香港脚）。 \n气香者良。宜橘皮。忌鲤鱼。 \n苏子与叶同功。润心肺，尤能下气定喘，止嗽消痰，利膈宽肠，温中开郁（有苏子降气 \n汤）。 \n苏梗下气稍缓，虚者宜之（叶发汗散寒、梗顺气安胎，子降气开郁、消痰定喘。表弱气 \n虚者忌用叶，肠滑气虚",g:"解表药"},
  "紫草":{o:"紫草",c:"泻血热，滑肠 \n甘咸气寒。入厥阴（心包、肝）血分。凉血活血，利九窍，通二便（咸寒性滑）。 \n治心腹邪气（即热也），水肿五痘， 癣恶疮（血热所致）及痘疮血热毒盛、二便闭涩 \n者（血热则毒闭，得紫草凉之，则血行而毒出。大便利者忌之。《活幼心书》云∶紫草性寒， \n小儿脾实者可用，脾虚者反能作泻。古方惟用茸，取其初得阳气，以类触类，用发痘疮。今 \n人不达此理，一概用之误矣）。泻者忌用。 \n去头须，酒洗。",g:"清热药"},
  "紫菀":{o:"紫菀",c:"润肺，泻火 \n辛温润肺，苦温下气。补虚调中，消痰止渴。 \n治寒热结气，咳逆上气，咳吐脓血（专治血痰，为血劳圣药），肺经虚热，小儿惊痫（亦 \n虚而有热）。能开喉痹，取恶涎，然辛散性滑，不宜多用独用（《本草汇》云∶苦能达下，辛 \n可益金，故吐血保肺，收为上剂。虽入至高善于达下，使气化及于州都，小便自利，人所不 \n知。李士材曰∶辛而不燥，润而不寒，补而不滞，诚金玉君子，非多用独用，不能速效。州 \n都，膀胱也）。 \n根作节、紫色润软者良（人多以车前、旋复根伪之，误服误人）。去头须蜜水浸，焙用。 \n款冬为使。恶天雄、瞿麦、 本、远志。畏茵陈。白者名菀（时珍曰∶紫入血分，白入气分） \n。",g:"化痰止咳平喘药"},
  "紫葳":{o:"凌霄花",c:"\\x一名紫葳\\x \n泻血热 \n甘酸而寒。入厥阴（心包、肝）血分。能去血中伏火，破血去瘀。 \n生产乳余疾，崩带症瘕，肠结（不大便）血闭，淋 风痒，血热生风之证。女科多用， \n孕妇忌之（《本经》云∶养胎。《经疏》云∶破血之药，非所宜也。肺痈有用之为君药者。凌 \n霄花为末，和密陀僧唾调，敷酒 甚验）。 \n藤生，花开五瓣，黄赤有点，不可近鼻，嗅之伤脑。",g:"活血化瘀药"},
  "红曲":{o:"红曲",c:"宣，破血，燥，消食 \n甘温色赤。入营而破血，燥胃消食，活血和血。治赤白下痢，跌打损伤，产后恶露不尽 \n（李时珍曰∶人之水谷入胃，中焦湿热熏蒸，游溢精气，化为营血，此造化自然之妙也。红 \n曲以白米饭杂曲面母，湿热蒸 ，即变为真红，此人窥造化之巧者也。故治脾胃营血，得同 \n气相求之理）。红入米心、陈久者良（昂按∶红曲温燥，能腐生物使熟。故鱼肉 用之，不 \n特取其色也）。",g:"消食药"},
  "红花":{o:"红花",c:"\\x古名红兰花\\x \n通，行血，润燥 \n辛苦甘温。入肺经而破瘀血、活血（瘀行则血活。有热结于中、暴吐紫黑血者，吐出为 \n好。吐未尽，加桃仁、红花行之。大抵鲜血宜止，瘀血宜行），润燥，消肿止痛（凡血热血 \n瘀，则作肿作痛）。 \n治经闭便难，血运口噤，胎死腹中（非活血行血不能下），痘疮血热（本草不言治痘）， \n喉痹不通。又能入心经，生新血（须兼补益药为佐使）。俗用染红，并作胭脂（胭脂活血解 \n毒。痘疔挑破，以油胭脂敷之良）。少用养血，多则行血，过用能使血行不止而毙（血生于 \n心包，藏于肝，属于冲、任。红花汁与相类，故治血病。有产妇血闷而死，名医陆氏以红花 \n敷十斤煮汤，寝妇于上而熏之，汤冷再加，半",g:"活血化瘀药"},
  "细辛":{o:"细辛",c:"宣散风湿，补肝润肾 \n辛温散风邪，故诸风痹痛、咳嗽上气、头痛脊强者宜之（专治少阴头痛，独活为使）。 \n辛散浮热，故口疮喉痹（少阴火）、鼻渊齿蛊者（虫蚀脓烂）宜之。辛益肝胆，故胆虚惊痫， \n风眼泪下者宜之。水停心下则肾燥，细辛之辛，能行水气以润之（肾燥者，心亦燥，火屈于 \n水故燥也。经曰∶肾苦燥，急食辛以润之）。虽手少阴（心）引经，乃足少阴（肾）本药， \n能通精气，利九窍，故耳聋鼻 （音瓮，鼻塞不闻香臭也。风寒入脑，故气不宣通。寒宜表， \n热宜清，有息肉者，为末吹鼻）、倒睫便涩者宜之。散结温经，破痰下乳，行血发汗（能发 \n少阴之汗。仲景治少阴证反发热，麻黄附子细辛汤，乃治邪在里之表剂）。然味浓性",g:"解表药"},
  "续断":{o:"续断",c:"补肝肾，理筋骨 \n苦温补肾、辛温补肝。能宣通血脉而理筋骨。主伤中，补不足（《经疏》曰∶味甘故然） \n暖子宫，缩小便，破瘀血。 \n治腰痛胎漏（怀妊沥血），崩带遗精，肠风血痢（《是斋方》∶平胃散一两，川续断二钱 \n半，每服二钱，米饮下，治时痢亦验），痈痔肿毒。又主金疮折跌（以功命名），止痛生肌。 \n女科外科，需为上剂。川产良。状如鸡脚，皮黄皱节节断者真。去向里硬筋，酒浸用。地黄 \n为使。",g:"补虚药"},
  "续随子":{o:"续随子",c:"\\x一名千金子\\x \n泻，行水，破血，解毒 \n辛温有毒，行水破血。 \n治症瘕痰饮，冷气胀满，蛊毒鬼疰。利大、小肠，下恶滞物，涂疥癣疮（玉枢丹用之， \n治百病多效。《经疏》曰∶乃以毒治毒之功）。 \n去壳，取色白者，压去油用（时珍曰∶续随子、大戟、泽漆、甘遂，茎叶相似，主疗亦 \n相似，长于利水，用之得法，皆要药也）。",g:"清热药"},
  "绿豆":{o:"绿豆",c:"泻热解毒 \n甘寒。行十二经，清热解毒（一切草木、金石、砒霜毒皆治之），利小便，止消渴，治 \n泻痢，连皮用（其凉在皮）。 \n粉，扑痘疮溃烂良（一市民诵观音经甚诚，出行折一足，哀叫菩萨，梦僧授一方，绿豆 \n粉新铫炒紫色，井水调，浓敷纸贴，杉木扎定，其效如神）。",g:"清热药"},
  "羊肉":{o:"羊肉",c:"补虚劳 \n甘热属火。补虚劳，益气血，壮阳道，开胃健力，通气发疮（仲景治虚羸蓐劳，有当归 \n羊血汤。《十剂》曰∶补可去弱，人参、羊肉之属是也。东垣曰∶人参补气，羊肉补形。凡 \n味同羊肉者，皆补血虚，阳生则阴长也）。 \n羊肝，苦寒（苏颂曰温）色青。补肝而明目（肝以泻为补。羊肝丸，治目疾加黄连）。 \n胆，苦寒。点风泪眼，赤障白翳（腊月入蜜胆中，纸套笼住，悬檐下，待霜出，扫取点 \n眼。又入蜜胆中蒸之，候干，研为膏，每含少许，或点之。名二百味草花膏，以羊食百草， \n蜂采百花也。时珍曰∶肝窍开于目，胆汁减则目暗。目者，肝之外候，胆之精华也，故诸胆 \n皆治目病）。 \n胫骨，入肾而补骨。烧灰擦牙良（时珍曰∶羊",g:"补虚药"},
  "羊血":{o:"羊血",c:"解金银、丹石、砒硫一切诸毒。 \n乳，甘温。补肺肾虚，润胃脘、大肠之燥。治反胃消渴，口疮舌肿（含漱），蜘蛛咬伤 \n（有浑身生丝者，饮之瘥）。 \n肉、肝，青 羊良；胆，青羯羊良；乳，白 羊良。骨 用。反半夏、菖蒲。忌铜器（ \n牡羊曰 、曰羝，去势曰羯。子曰羔，羔五月曰 ）。",g:"其他"},
  "羌活":{o:"羌活",c:"宣，搜风，发表，胜湿 \n辛苦性湿，气雄而散，味薄上升。入足太阳（膀胱）以理游风，兼入足少阴、厥阴（肾、 \n肝）气分。泻肝气，搜肝风，小无不入，大无不通。 \n治风湿相搏，本经头痛（同川芎，治太阳、少阴头痛。凡头痛多用风药者，以巅顶之上 \n，唯风药可到也），督脉为病，脊强而厥（督脉并太阳经），刚痉柔痉（脊强而厥，即痉证也。 \n伤寒无汗为刚痉；伤风有汗为柔痉。亦有血虚发痉者。大约风证宜二活，血虚忌用），中风 \n不语（按∶古人治中风，多主外感，率用续命、愈风等汤以发表，用三化汤、麻仁丸以攻里 \n。至河间出，如云中风非外来之风，良由心火暴甚，肾水虚衰。东垣则以为本气自病。丹溪 \n以为湿生痰、痰生热、热生",g:"解表药"},
  "羚羊角":{o:"羚羊角",c:"泻心、肝火 \n苦咸微寒。羊属火，而羚羊属木，入足厥阴（肝）、手太阴、少阴（肺、心）经。目为 \n肝窍，此能清肝，故明目去障。肝主风，其合在筋，此能祛风舒筋，故治惊痫搐搦，骨痛筋 \n挛；肝藏魂，心主神明，此能泻心、肝邪热，故治狂越僻谬，梦魇惊骇；肝主血，此能散血， \n故治瘀滞恶血，血痢肿毒；相火寄于肝胆，在志为怒，（经曰∶大怒则形气绝，而血菀于上）， \n此能下气降火，故治伤寒伏热，烦懑气逆，食噎不通；羚之性灵，而精在角，故又辟邪而解 \n诸毒（昂按∶痘科多用以清肝火，而《本草》不言治痘）。似羊而大，角有节、最坚劲、能 \n碎金刚石与貘骨（貘，音麦，能食铁）。夜宿防患，以角挂树而栖（角有挂纹者真。一边有",g:"祛风湿药"},
  "肉桂":{o:"肉桂",c:"大燥，补肾命火 \n辛甘大热，气浓纯阳。入肝、肾血分（平肝、补肾），补命门相火之不足（两肾中间， \n先天祖气，乃真火也。人非此火，不能有生，无此真阳之火，则无以蒸糟粕而化精微，脾胃 \n衰败，气尽而亡矣），益阳消阴。治痼冷沉寒，能发汗疏通血脉，宣导百药（辛则善散，热 \n则通行）。去营卫风寒，表虚自汗（阳虚），腹中冷痛，咳逆结气（咳逆亦由气不归元，桂能 \n引火，归宿丹田）。 \n木得桂而枯（削桂钉木根，其木即死），又能抑肝风而扶脾土（肝木盛则克土，辛散肝 \n风，甘益脾土），从治目赤肿痛（以热攻热，名曰从治），及脾虚恶食（命火不足），湿盛泄 \n泻（土为木克，不能防水。古行水方中，亦多用桂，如五苓散、滋肾",g:"温里药"},
  "肉苁蓉":{o:"肉苁蓉",c:"补肾命，滑肠 \n甘酸咸温。入肾经血分。补命门相火，滋润五脏。益髓强筋。 \n治五劳七伤，绝阳不兴，绝阴不产，腰膝冷痛，崩带遗精，峻补精血（时珍曰∶补而不 \n峻，故有苁蓉之号）。骤用恐妨心，滑大便。 \n长大如臂，重至斤许。有松子鳞甲者良。酒浸一宿，刷去浮甲，劈破，除内筋膜。酒蒸 \n半日。又酥炙用。忌铁（苏恭曰∶今日所用，多草苁蓉功力稍劣）。",g:"补虚药"},
  "肉豆蔻":{o:"肉豆蔻",c:"\\x一名肉果\\x \n燥脾，涩肠 \n辛温气香。理脾暖胃，下气调中，逐冷祛痰，消食解酒。 \n治积冷心腹胀痛（挟痰、挟食者并宜之），中恶吐沫，小儿吐逆，乳食不下。又能涩大 \n肠，止虚泻冷痢（初起忌用）。 \n出岭南。似草蔻，外有皱纹，内有斑纹。糯米粉裹，煨熟用。忌铁。",g:"收涩药"},
  "肥皂荚":{o:"肥皂荚",c:"泻热毒 \n辛温。除风湿，去垢腻（故澡身，盥面用之），疗无名肿毒有奇功（不拘奇疡恶毒，用 \n生肥皂去子、弦及筋捣烂，酽醋和敷立愈，不愈再敷奇验。此方方书未载，若贫人，僻地 \n仓卒无药者，用之甚便，故特着之。《集成》曰∶生肥皂火 存性，生油，腻粉调敷诸恶疮 \n）。",g:"其他"},
  "胆矾":{o:"胆矾",c:"\\x一名石胆\\x \n宣，吐风痰，涩，敛咳逆 \n酸涩辛寒。入少阳胆经。性敛而能上行，涌吐风、热痰诞，发散风木相火。治喉痹（醋 \n调咽，吐痰诞立效）咳逆，痉痫崩淋。能杀虫，治牙虫、疮毒、阴蚀。产铜坑中，乃铜之精 \n液（故能入肝、胆治风木）。磨铁作铜色者真，形似空青鸭嘴色为上（市人多以醋揉青矾伪 \n之）。畏桂、芫花、辛夷、白薇。",g:"驱虫药"},
  "胡卢巴":{o:"胡卢巴",c:"燥，补肾命，除寒湿 \n苦温纯阳。入右肾命门。暖丹田，壮元阳。 \n治肾脏虚冷，阳气不能归元（同附子、硫黄），瘕疝冷气（同茴香、巴戟、川乌、川楝、 \n吴茱萸），寒湿香港脚。 \n出岭南番舶者良，云是番莱菔子。酒浸曝，或蒸，或炒。",g:"其他"},
  "胡桃":{o:"胡桃",c:"补命门，肉润，皮涩 \n味甘气热。皮涩（皮敛肺定喘，固肾涩精。今药中罕用，昂谓若用之，当胜金樱、莲须 \n也）肉润，皮汁青黑，属水入肾。通命门，利三焦，温肺润肠，补气养血。佐补骨脂，一木 \n一火，大补下焦（胡桃属木，破故纸属火，有木火相生之妙。古云∶黄柏无知母，破故纸无 \n胡桃，犹水母之无虾也。时珍曰∶三焦者，无气之别使；命门者，三焦之本原。命门指所居 \n之府而言，为藏精、系胞之物；三焦指所治之部而名，为出纳、腐熟之司。一为体，一为用 \n也。其体非脂非肉，白膜裹之，在脊骨第七节两肾中央，系着于脊，下通二肾，上通心、肺 \n贯脑。为生命之源，相火之生，精气之府，人物皆有之。生人生物，皆由此出。《内经》",g:"补虚药"},
  "胡桐泪":{o:"胡桐泪",c:"泻热，杀虫 \n苦能杀虫，咸能入胃软坚，大寒能除热。治咽喉热痛（磨扫取涎），齿 风疳，瘰 结 \n核（苏颂曰∶古方稀用，今口齿家，多用为要药）。出凉肃。乃胡桐脂，入土得斥卤之气结 \n成，如小石片，木泪状如膏油。",g:"驱虫药"},
  "胡椒":{o:"胡椒",c:"燥，快膈，消痰 \n辛热纯阳。暖胃快膈，下气消痰。治寒痰食积，肠滑冷痢，阴毒腹痛，胃寒吐水，牙齿 \n浮热作痛（合荜茇散之）。杀一切鱼、肉、鳖、蕈（音寻，上声）毒。食料宜之，嗜之者众。 \n多食损肺，走气动火，发疮、痔、脏毒，齿痛目昏。 \n毕澄茄一类二种，主治略同。",g:"其他"},
  "胡荽":{o:"胡荽",c:"宣，发痘疹，辟恶气 \n辛温香窜。内通心脾，外达四肢。辟一切不正之气，痧疹、痘疮不出。煎酒喷之（心脾 \n之气，得芳香而营运，含喷遍身，勿 头面。痘疹家悬挂，辟邪恶，胡荽久食，令人多忘， \n病患不宜食胡荽、黄花菜）。",g:"其他"},
  "胡麻":{o:"胡麻",c:"\\x即芝麻，一名巨胜子，种出大宛，故曰胡麻\\x \n补肝肾，润五脏，清肠 \n甘平。补肺气、益肝肾，润五脏，填精髓，坚筋骨，明耳目，耐饥渴（可以辟谷，但滑 \n肠，与白术并用为胜），乌髭发，利大小肠，逐风湿气（刘河间曰∶麻木谷而治风。又云∶ \n治风先治血，血活则风散，胡麻入肝益血，故风药中不可阙也。郑奠一用鳖虱胡麻，佐苦参、 \n蒺藜，治大疯疥癞，屡有愈者），凉血解毒。生嚼敷小儿头疮。 \n麻油滑胎疗疮，熬膏多用之（凉血解毒，止痛生肌）。 \n皮肉俱黑者良（入肾） 栗色者名鳖虱胡麻更佳，九蒸九晒，可以服食（陶宏景曰∶八 \n谷之中，惟此为良。昂按∶若云自大宛来，则非八谷之麻，明矣。又按∶月令仲秋之月，天 \n",g:"清热药"},
  "胡黄连":{o:"胡黄连",c:"泻热，疗惊疳 \n苦寒。去心热，益肝胆，浓肠胃。 \n治骨蒸劳热，五心（心窝、左右手心、足心）烦热，三消（渴而多饮为上消，肺热也。 \n心移热于肺，传为膈消是也。多食善饥为中消，胃热也，痹成为消中是也。渴而小便数有膏 \n为下消，肾热而水亏也）五痔（牝痔、牡痔、脉痔、肠痔、血痔、湿热下流伤血分，无所施 \n泄，则逼肛门而为痔肿），温疟泻痢，女人胎蒸，消果子积，为小儿惊疳良药（朱二允曰∶ \n解吃烟毒，合茶服之甚效）。性味功用同黄连，故名。 \n出波斯国，今秦陇、南海亦有之。心黑外黄，折之尘出如烟者真。畏、恶同黄连。",g:"清热药"},
  "腊雪水":{o:"腊雪水",c:"泻热 \n甘寒。治时行瘟疫，宜煎伤寒、火 （音谒，伤暑）之药，抹痱良。",g:"其他"},
  "自然铜":{o:"自然铜",c:"重，续筋骨 \n辛平。主折伤，续筋骨，散瘀止痛（折伤必有死血瘀滞经络，然须审虚实，佐以养血、 \n补气、温经之药。铜非 不可用，火毒、金毒相煽，复挟香药，热毒内攻，虽有接骨之功， \n必多燥散之祸，用者慎之）。产铜坑中。火 、醋淬七次，细研，甘草水飞用（昔有饲折翅 \n雁者，雁飞去，故治折伤）。",g:"补虚药"},
  "艾叶":{o:"艾叶",c:"宣，理气血，燥，逐寒湿 \n苦辛。生温，熟热。纯阳之性，能回垂绝之元阳。通十二经，走三阴（太、少、厥）， \n理气血，逐寒湿，暖子宫，止诸血，温中开郁，调经安胎（胎动腰痛下血，胶艾汤良，阿胶、 \n艾叶煎服，亦治虚痢）。 \n治吐衄崩带（治带要药），腹痛冷痢，霍乱转筋（皆理气血、逐寒湿之效），杀蛇治癣（醋 \n煎，外科有用干艾作汤，投白矾二三钱，洗疮，然后敷药者。盖人血气冷，必假艾力以佐阳 \n，而艾性又能杀虫也）。以之灸（音九）火，能透诸经而治百病。血热为病者禁用（灸火则 \n气下行，入药则热上冲，不可过剂。丹田气弱，脐腹冷者，以熟艾装袋，兜脐腹甚妙。寒湿 \n香港脚，亦宜以此夹入袜内）。 \n陈者良，揉捣如",g:"止血药"},
  "芒硝":{o:"朴硝、芒硝",c:"\\x朴硝，即皮硝\\x \n大泻，润燥，软坚 \n辛能润燥，咸能软坚，苦能下泄，大寒能除热。朴硝酷涩性急，芒硝经炼稍缓。能荡涤 \n三焦、肠、胃实热，推陈致新（按∶致新则泻亦有补，与大黄同。盖邪气不除，则正气不能 \n复也）。治阳强之病，伤寒（经曰∶人之伤于寒也必病热，盖寒郁而为热也）疫痢，积聚结 \n癖，留血停痰，黄胆淋闭，瘰 疮肿，目赤障翳。通经堕胎（丰城尉家有猫，子死腹中，啼 \n叫欲绝，医以硝灌之，死子即下。后有一牛，亦用此法得活。本用治人，治畜亦验《经疏》 \n曰∶硝者消也，五金八石，皆能消之，况脏腑之积聚乎？其直往无前之性，所谓无坚不破， \n无热不荡者也。病非热邪深固、闭结不通，不可轻投，恐误伐下",g:"泻下药"},
  "芙蓉花":{o:"芙蓉花",c:"泻，凉血，解毒 \n辛平、性滑涎粘。清肺凉血，散热止痛，消肿排脓。治一切痈疽肿毒有殊功（用芙蓉花 \n，或叶、或皮、或根，生捣或干研末，蜜调涂四围，中间留头，干则频换。初起者即觉清凉 \n，痛止肿消。已成者即脓出，已溃者则易敛。疡科秘其名为清凉膏、清露散、铁箍散，皆此 \n物也。或加赤小豆末，或苍耳烧存性为末，加入亦妙）。",g:"清热药"},
  "芜夷":{o:"芜夷",c:"宣，散风湿，泻，消积，杀虫 \n辛散满，苦杀虫，温燥湿化食（诸虫皆因湿而生，气食皆因寒而滞）。祛五脏、皮肤、 \n肢节风湿，心腹积冷，症痛鳖瘕（《直指方》云∶嗜酒人，血入于酒为酒鳖；多气人，血入 \n于气为气鳖；虚劳人，败血杂痰为血鳖。如虫之行，上侵人咽，下蚀人肛，或附胁背，或隐 \n胸腹。惟用芜夷炒，兼暖胃、理气、益血之药，乃可杀之），痔 疮癣，小儿惊疳冷痢（得 \n诃子、豆蔻良），胃中有虫，食即作痛（和面炒黄为末，米饮下）。形类榆荚。陈久、气膻者 \n良。",g:"化湿药"},
  "芡实":{o:"芡实",c:"\\x一名鸡头子\\x \n补脾，涩精 \n甘涩。固肾益精，补脾去湿。治泄泻带浊，小便不禁，梦遗滑精（同金樱膏为丸，名水 \n陆二仙丹），腰漆瘀痛（吴子野曰∶人之食芡，必枚啮而细嚼之，使华液流通，转相灌溉， \n其功胜于乳石也。《经验后方》∶煮熟研膏，合粳米煮粥食，益精气）。蒸熟捣粉用，涩精药 \n或连壳用（李惟熙曰∶菱寒而芡暖，菱花背日，芡花向日）。",g:"收涩药"},
  "芦根":{o:"芦根",c:"泻热，止呕 \n甘益胃，寒降火。 \n治呕哕反胃（胃热火升，则呕逆，食不下。《金匮》方∶芦根煎服），消渴客热，伤寒内 \n热，止小便数（肺为水之上源，脾气散精，上归于肺，始能通调水道，下输膀胱。肾为水脏， \n而主二便，三经有热。则小便数，甚至不能少忍，火性急速故也。芦中空，故入心肺，清上 \n焦热，热解则肺之气化行，而小便复其常道矣）。能解鱼、蟹、河豚毒。 \n取迸水肥浓者，去须、节用。",g:"清热药"},
  "芦荟":{o:"芦荟",c:"泻热，杀虫 \n大苦大寒。功专清热杀虫，凉肝明目，镇心除烦。治小儿惊痫五疳，敷 齿湿癣（甘草 \n末和敷），吹鼻杀脑疳，除鼻痒。小儿脾胃虚寒作泻者勿服。出波斯国。木脂也，味苦、色 \n绿者真。",g:"清热药"},
  "芫花":{o:"芫花",c:"大通，行水 \n苦寒有毒。去水饮痰癖。 \n疗五水在五脏、皮肤，胀满喘急，痛引胸胁，咳嗽瘴疟（五水者，风水、皮水、正水、 \n石水、黄汗也。水积胸中，坚满如石，名石水。汗如柏汁，名黄汗，久不愈必致痈脓。时珍 \n曰∶仲景治伤寒太阳证，表未解，心下有水而咳，干呕发热，或喘或利者，小青龙汤主之。 \n表已解，有时头痛，汗出恶寒，心下有水，干呕，痛引两胁，或喘或嗽者，十枣汤主之。盖 \n青龙散表邪，使水从汗出，《内经》所谓开鬼门也；十枣逐里邪，使水从两便出，《内经》 \n所谓洁净府、去陈 法也。十枣汤∶芫花、甘遂、大戟等分，枣十枚）。 \n叶似柳，二月开花紫碧色，叶生花落。陈久者良。醋煮过，水浸曝用。根疗疥，可毒鱼",g:"泻下药"},
  "芭蕉根":{o:"芭蕉根",c:"泻热 \n味甘大寒。治天行热狂，烦闷消渴，产后血胀（并捣汁服），涂痈肿结热（为末，油调 \n敷。霜后者佳）。",g:"其他"},
  "花椒":{o:"川椒",c:"宣，散寒湿，燥，补火 \n辛热纯阳。入肺，发汗散寒，治风寒咳嗽。入脾，暖胃燥湿，消食除胀，治心腹冷痛、 \n吐泻 痢、痰饮水肿（《千金方》有人冷气入阴囊肿满，生椒择净，帛裹着丸囊，浓半寸， \n须臾热气大通，日再易，取消瘥。梅师用桂末涂亦良）；入右肾命门，补火，治肾气上逆（能 \n下行导火归元。每日吞三十粒，大能温补下焦），阳衰溲数、阴汗泄精（下焦虚寒）。坚齿明 \n目，破血通经，除症安蛔（虫见椒则伏。仲景蛔厥乌梅丸用之。凡虫嚼腹痛者，面白唇红， \n时发时止）。杀鬼疰、虫、鱼毒（最杀劳虫。危氏神授丸。川椒炒出汗，为末，米饮下三钱。 \n有人病传尸劳，遇异人传此方，服至二斤，吐出虫如蛇而安）。肺、胃素热者忌",g:"温里药"},
  "花蕊石":{o:"花蕊石",c:"涩，止血 \n酸涩气平。专入肝经血分。能化瘀血为水，止金疮出血（刮末敷之即合，仍不作脓。《 \n局方》治损伤诸血，胎产恶血、血晕，有花蕊石散），下死胎胞衣（恶血化则胞胎无阻）。出 \n陕华代地。体坚色黄。 研，水飞用。",g:"其他"},
  "芸苔":{o:"芸薹",c:"宣，散血，消肿 \n辛温。散血消肿，捣贴乳痈丹毒（孙思邈曰∶捣贴丹毒，随手即消，其效如神），动疾 \n发疮。即油菜（道家五荤之一）。 \n子，与叶同功，治产难。",g:"其他"},
  "苍术":{o:"苍术",c:"补脾燥湿，宣，升阳散郁 \n甘温辛烈。燥胃强脾，发汗除湿，能升发胃中阳气（东垣曰∶雄壮上行，能除湿，下 \n安太阴，使邪气不传入脾），止吐泻，逐痰水（许叔微云∶苍术能治水饮之 囊，盖燥脾以 \n去湿，崇土以填科。日用苍术一斤，大枣五十枚，去皮捣，麻油半两，水二盏研，滤汁和丸， \n名神术丸。丹溪曰∶实脾土，燥脾湿，洵是治痰之本），消肿满，辟恶气（辟一切岚瘴、邪 \n恶、鬼气。暑湿月，焚之佳。《夷坚志》曰∶有士人游西湖，遇一女子，明艳动人，重币求 \n之不得。又五年重寻旧游，怅然空返，忽遇女子，士欣然并行，过旅馆，留半岁，将议偕逝。 \n女曰∶向自君去，忆念之苦，感疾而亡，今非人也，但君浸阴气深，当暴泻，宜服",g:"化湿药"},
  "苍耳子":{o:"苍耳子",c:"\\x一名 耳，即诗卷耳\\x \n轻，发汗，散风湿 \n甘苦性温。善发汗散风湿，上通脑顶，下行足膝，外达皮肤。 \n治头痛目暗，齿痛鼻渊，肢挛痹痛，瘰 疮疥（采根叶熬，名万应膏），遍身瘙痒（作 \n浴汤佳）。 \n去刺，酒拌蒸。忌猪肉（《圣惠方》云∶叶捣汁，治产后痢）。",g:"解表药"},
  "苎根":{o:"苎根",c:"泻热，散瘀 \n甘寒而滑。补阴破瘀，解热润燥。 \n治天行热疾，大渴大狂，胎动下血，诸淋血淋，捣贴赤游丹毒，痈疽发背，金疮折伤（ \n止血易痂），鸡鱼骨哽（捣如龙眼。鸡骨，鸡汤下，鱼骨，鱼汤下）。汁能化血为水。 \n苎皮与产妇作枕，止血运；安腹上，止产后腹痛（散瘀之功）沤苎汁，疗消渴。",g:"其他"},
  "苏合香":{o:"苏合香",c:"宣，通窍，辟恶 \n甘温走窜。通窍开郁，辟一切不正之气，杀精鬼。出诸番。合众香之汁煎成。以筋挑起 \n，悬丝不断者真。",g:"开窍药"},
  "苏木":{o:"苏木",c:"泻，行血，解表 \n甘咸辛凉。入三阴血分。行血去瘀，发散表里风气（宜与防风同用）。治产后血晕（《肘 \n后方》∶煮汁服。《海藏方》∶加乳香，酒服），胀满欲死，血痛血瘕，经闭气壅，痈肿朴伤， \n排脓止痛。多破血，少和血。出苏方国，交、爱亦有。忌铁。",g:"解表药"},
  "苦参":{o:"苦参",c:"泻火，燥湿，补阴 \n苦燥湿，寒胜热。沉阴主肾。补阴益精，养肝胆，安五脏（湿热去则血气和平，而五脏 \n自安）利九窍，生津止渴，明目止泪（泪为肝热）。 \n治温病血痢（纯下清血者，风伤肝也，宜散风凉血；下如豆汁者，湿伤脾也，宜清热渗 \n湿），肠风溺赤，黄胆酒毒。热生风，湿生虫，又能祛风、逐水、杀虫，治大肠疥癞。然大 \n苦大寒，肝、肾虚而无热者勿服（张从正曰∶凡药皆毒也，虽苦参、甘草，不可不谓之毒， \n久服必偏胜为患。经曰∶五味入胃，各归其所喜攻，久而增气，物化之常也。气增而久，夭 \n之由也。王冰注曰∶气增不已，则脏有偏胜，偏胜则脏有偏绝，故令人暴夭。《笔谈》曰∶ \n久用苦参擦牙，遂病腰痛，由其气伤肾",g:"清热药"},
  "苦杏仁":{o:"杏仁",c:"泻肺，解肌，润燥，下气 \n辛苦甘温而利。泻肺解肌（能发汗），除风散寒，降气行痰，润燥消积（索面、豆粉， \n近之则烂），通大肠气秘。治时行头痛，上焦风燥，咳逆上气（杏仁炒研，蜜和为丸，含咽）， \n烦热喘促。有小毒，能杀虫治疮，制狗毒（可毒狗，消狗肉积）、 毒。肺虚而咳者禁用（东 \n垣曰∶杏仁下喘治气，桃仁疗狂治血，俱治大便秘。当分气血，昼便难属阳气，夜便难属阴 \n血。妇人便秘，不可过泄。脉浮属气，用杏仁、陈皮；脉沉属血，用桃仁、陈皮。肺与大肠 \n相表里，贲门上主往来，魄门下主收闭，为气之通道，故并用陈皮佐之。贲门胃之上口，魄 \n门，即肛门。杏仁、紫菀，并能解肺郁，利小便）。去皮、尖，炒研，发散连",g:"化痰止咳平喘药"},
  "苦楝子":{o:"苦楝子",c:"\\x一名金铃子\\x \n泻湿热，治疝，杀虫 \n苦寒有小毒。能入肝舒筋，能导小肠、膀胱之热，因引心包相火下行，通利小便。 \n为疝气要药。亦治伤寒热狂、热厥，腹痛心痛。杀三虫，疗疡疥（《夷坚志》∶消渴症 \n有虫、耗其津液者，取根、皮浓煎，加少麝服，下其虫而渴自止）。脾胃虚寒忌之。 \n川产良。酒蒸（寒因热用）。去皮取肉、去核用。用核则槌碎，浆水煮一伏时去肉用。 \n茴香为使。",g:"驱虫药"},
  "茄根":{o:"茄根",c:"泻，散血，消肿 \n散血消肿。煮汁渍冻疮（史国公药酒，用白茄根为君。茄根以马尿浸三日，晒炒为末， \n点牙即落）。 \n茄子甘寒，散血宽肠，动风发病。",g:"其他"},
  "茜草":{o:"茜草",c:"通，行血 \n色赤入营，气温行滞，味酸走肝，而咸走血（《本经》苦寒），入厥阴（心包、肝）血分。 \n能行血止血（能行故能止。消瘀通经，又能止吐崩尿血），消瘀通经（酒煎一两，通经甚效）。 \n治风痹黄胆（疸有五∶黄胆、谷疸、酒疸、黄汗疸、女劳疸。此盖蓄血发黄，不专于温 \n热者也。女劳疸必属肾虚，亦不可以湿热例治。当用四物、知、柏壮其水，参、术培其气， \n随证而加利湿清热药），崩运扑损，痔 疮疖。血少者忌用。根可染绛，忌铁。",g:"止血药"},
  "茯神":{o:"茯神",c:"补心 \n主治略同茯苓，但茯苓入脾，肾之用多，茯神入心之用多。开心益智，安魂养神。疗风 \n眩心虚，健忘多恚。 \n即茯苓抱根生者（昂按∶以其抱心，故能补心也）。去皮及中木用。 \n茯神心木，名黄松节。疗诸筋挛缩，偏风 斜，心掣健忘（心木一两，乳香一钱，石器 \n炒研，名松节散。每服二钱，木瓜汤下，治一切筋挛疼痛。乳香能伸筋，木瓜能舒筋也）。",g:"安神药"},
  "茯苓":{o:"茯苓",c:"补心脾，通，行水 \n甘温益脾助阳，淡渗利窍除湿。色白入肺泻热，而下通膀胱（能通心气于肾，使热从小 \n便出，然必其上行入肺，能清化源，而后能下降利水也），宁心益气，调营理卫，定魄安魂 \n（营主血，卫主气，肺藏魄，肝藏魂）。 \n治忧恚惊悸（心肝不足），心下结痛，寒热烦满，口焦舌干（口为脾窍，舌为心苗。火 \n下降则热除），咳逆（肺火）呕哕（胃火），膈中痰水（脾虚），水肿淋沥，泄泻（渗湿）遗 \n精（益心肾。若虚寒遗溺、泄精者，又当用温热之剂峻补其下。忌用茯苓淡渗之药）。小便 \n结者能通，多者能止（湿除则便自止），生津止渴（湿热去则津生），退热安胎。 \n松根灵气结成，以大块、坚白者良。去皮，乳拌蒸，多拌",g:"利水渗湿药"},
  "茴香":{o:"茴香",c:"\\x古作怀香\\x \n燥，补肾命门，治寒疝 \n大茴辛热。入肾膀胱。暖丹田，补命门，开胃下食，调中止呕。 \n疗小肠冷气， 疝阴肿（疝有七种，气、血、寒、水、筋、狐、 也。肝经病，不属肾 \n经，以厥阴肝脉络阴器也。多因寒湿所致，亦有挟虚者，当加参、术于温散药中），干湿脚 \n气。多食损目发疮。 \n小茴辛平，理气开胃，亦治寒疝。食料宜之。 \n大如麦粒，轻而有细棱者名大茴，出宁夏，他处小者名小茴。自番舶来，实八瓣者，名 \n八角茴香。炒黄用，得酒良。得盐则入肾，发肾邪，故治阴疝（受病于肝，见证于肾。大、 \n小茴各一两，为末，猪脬一个，连尿入药，酒煮烂，为丸服）。",g:"理气药"},
  "茵芋":{o:"茵芋",c:"宣，去风湿 \n辛苦微温，有小毒。 \n治风湿拘挛痹痛（时珍曰∶古方治风痫，有茵芋丸；治风痹，有茵芋酒；治产后风，有 \n茵芋膏。风湿诸证多用之。茵芋、石南、莽草，皆治风妙品，近世罕知。莽草辛温有毒，治 \n头风痈肿乳痈疝瘕。苏颂曰∶古方风湿诸酒多用之，今人取叶煎汤热含，治牙虫喉痹甚效。 \n甄权曰∶不入汤）。 \n茎赤，叶如石榴而短浓，茎炙用。",g:"其他"},
  "茵陈":{o:"茵陈",c:"通，利湿热，治诸黄 \n苦燥湿，寒胜热。入足太阳（膀胱）经。发汗利水，以泄太阴、阳明（脾、胃）之湿热。 \n为治黄胆之君药（脾胃有湿热则发黄，黄者，脾之色也。热甚者，身如桔色，汗如柏汁 \n。亦有寒湿发黄、身熏黄而色暗。大抵治以茵陈为主，阳黄加大黄、栀子，阴黄加附子、干 \n姜，各随寒热治之）。又治伤寒时疾，狂热瘴疟，头痛头旋，女人瘕疝（皆湿热为病）。",g:"利水渗湿药"},
  "茶":{o:"茶",c:"泻热，清神，消食 \n苦甘微寒。下气消食，去痰热，除烦渴，清头目（得春初生发之气，故多整肃上膈之功 \n。《汤液》云∶茶苦寒下行，如何是清头目？《蒙鉴》曰∶热下降，则上自清矣），醒昏睡（ \n清神），解酒食、油腻、烧炙之毒，利大、小便。多饮消脂（最能去油）、寒胃（故浓茶能 \n引吐。《千金》疗卒头痛如破，非中冷、中风。由痰、厥气上冲所致，名厥头痛，单煮茶恣 \n饮取吐，直吐出胆汁乃已，渴而即瘥）。酒后饮茶，引入膀胱、肾经，患瘕疝水肿，空心亦 \n忌之（与姜等分浓煎，名姜茶饮，治赤白痢。茶助阴，姜助阳，使寒热平调。并能消暑、解 \n酒、食毒）。陈、细者良，粗者损人。",g:"消食药"},
  "茹":{o:"茹",c:"泻，破血 \n辛寒，有小毒。蚀恶肉，排脓血，杀疥虫，除热痹，破症瘕（《内经》同乌贼骨。治妇 \n人血枯）。 \n根如莱菔，皮黄肉白，叶长微阔，折之有汁，结实如豆，一颗三粒。甘草为使。",g:"活血化瘀药"},
  "荆沥":{o:"荆沥",c:"宣通经络，滑痰泻热 \n甘平。除风热，化痰涎，开经络，行血气。治中风失音，惊痫痰迷，眩晕烦闷，消渴热 \n痢，为去风化痰妙药。气虚、食少者忌之（《延年秘录》云∶热多用竹沥，寒多用荆沥。丹 \n溪曰∶虚痰用竹沥，实痰用荆沥，并宜姜汁助送，则不凝滞）。 \n牡荆俗名黄荆，截取尺余，架砖上，中间火炙，两头承取汁用。",g:"化痰止咳平喘药"},
  "荆芥":{o:"荆芥",c:"\\x一名假苏\\x \n轻，宣，发表，祛风，理血 \n辛苦而温，芳香而散。入肝经气分，兼行血分。其性升浮能发汗（又云∶止冷汗、虚汗） \n，散风湿，清头目，利咽喉。治伤寒头痛，中风口噤，身强项直，口面 斜，目中黑花。 \n其气温散，能助脾消食（气香入脾），通利血脉。治吐衄肠风，崩中血痢，产风血运（产 \n后去血过多，腹内空虚，则自生风。故常有崩运之患，不待外风袭之也。荆芥最能散血中之 \n风，华佗愈风散，荆芥三钱，微焙为末，豆淋酒调服，或童便服，诸家云甚效），瘰 疮肿 \n。清热散瘀，破结解毒（结散热清，则血凉而毒解，为风病、血病、疮家圣药）。荆芥功本 \n治风，又兼治血者，以其入风木之脏，即是藏血之地也。李士",g:"解表药"},
  "草":{o:"草",c:"宣，去风湿 \n苦辛。生寒，熟温。 \n治肝肾风气，四肢麻痹，筋骨冷痛，腰膝无力，风湿疮疡。若痹痛由脾肾两虚、阴血不 \n足，不由风湿而得者，忌服（风药能燥血）。 \n江东人呼猪为 ，其草似猪咏臭，故名（唐·成讷有进 表。宋·张咏进 表云∶ \n其草金棱银线，素茎紫 ，对节而生，颇同苍耳。臣吃百服，眼目清明，即至千服，须发乌 \n黑，筋力轻健，效验多端）。以五月五日、六月六日、七月七日、九月九日采者尤佳。去粗 \n茎，留枝叶花实，酒拌蒸晒九次，蜜丸，甚益元气（ 辛苦气寒，故必蒸晒九次加以酒蜜 \n，则苦寒之阴浊尽去，而清香之美味见矣。数不至九，阴浊未尽，则不能透骨搜风而却病也 \n）。捣汁熬膏，以甘草、生地煎膏",g:"其他"},
  "草乌头":{o:"草乌头",c:"大燥，开顽痰 \n辛苦大热。搜风胜湿，开顽痰。治顽疮，以毒攻毒，颇胜川乌。然至毒，无所酿制，不 \n可轻投。 \n野生，状类川乌，亦名乌喙。姜汁炒，或豆腐煮用。熬膏，名射罔，敷箭射兽，见面立 \n死。",g:"其他"},
  "草豆蔻":{o:"草豆蔻",c:"\\x一名草果\\x \n燥湿祛痰，除痰截疟 \n辛热香散。暖胃健脾，破气开郁，燥湿祛寒，除痰化食。 \n治瘴疠寒疟（佐常山能截疟。或与知母同用，取其一阴一阳，治寒热瘴疟。盖草果治太 \n阴独胜之寒，知母治阳明独胜之火），寒客胃痛（散滞气，利膈痰，因滞因寒者多效），霍乱 \n泻痢，噎膈反胃，痞满吐酸，痰饮积聚。解口臭气、酒毒、鱼肉毒（故食料用之）。过剂助 \n脾热，耗气损目。 \n闽产名草蔻，如龙眼而微长，皮黄白、薄而棱峭，仁如砂仁，而辛香气和。滇广所产名 \n草果，如诃子，皮黑、浓而棱密，子粗而辛臭，虽是一物，微有不同。面裹，煨熟，取仁用 \n。忌铁。",g:"补虚药"},
  "荔枝核":{o:"荔枝核",c:"宣散寒湿 \n甘涩而温。入肝肾。散滞气，辟寒邪。治胃脘痛，妇人血气痛（ 存性五钱，香附一两 \n，为末，每服二钱，盐汤或米饮下，名蠲痛散。单服、醋汤下，亦效）。其实双结，核似睾 \n丸（睾音皋，肾子也）故治 疝卵肿，有述类象形之义（ 存性，酒调服，加茴香、青皮， \n各炒为末，酒服亦良）。壳发痘疮，烧存性用。荔枝连壳 研，止呃逆（生荔枝多食则醉， \n以壳浸水解之。此即食物不消，还以本物解之之义）。",g:"理气药"},
  "荛花":{o:"荛花",c:"大通，行水 \n辛散结、苦泄热，行水捷药，主治略同芫花。",g:"其他"},
  "荜茇":{o:"荜茇",c:"\\x茇、一作拨\\x \n燥，除胃冷，散浮热 \n辛热除胃冷，温中下气，消食祛痰。 \n治水泻气痢（牛乳点服），虚冷肠鸣（亦入大肠经），冷痰恶心，呕吐酸水， 癖阴疝。 \n辛散阳明之浮热，治头痛（偏头痛者，口含温水，随左右以末吹一字入鼻效）、牙痛（寒痛 \n宜干姜、荜茇、细辛，热痛宜石膏、牙硝，风痛宜皂角、僵蚕、蜂房、二乌，虫痛宜锻石、 \n雄黄），鼻渊。多服泄真气，动脾肺之火，损目。 \n出南番，岭南亦有。类椹子而长，青色，去挺用头。醋浸。刮净皮粟，免伤人肺。",g:"化痰止咳平喘药"},
  "荞麦":{o:"荞麦",c:"泻，利肠，下气 \n甘寒。降气，宽肠胃沉积（孟诜曰∶能炼五脏垢秽。昂按∶亦解酒积），泄痢带浊，敷 \n痘疮溃烂，汤火灼伤。脾胃虚寒人勿服。",g:"理气药"},
  "荠":{o:"荠",c:"补，和中，解毒 \n寒利肺，甘解毒（能解百药及蛇虫毒，在诸药中，毒皆自解）。和中止嗽，治消渴强中 \n（渴症下消，茎长兴盛，不交精出，名强中。消渴之后，发为痈疽），痈肿疔毒。 \n似人参而体虚无心，似桔梗而味甘不苦（奸贾多用以乱人参。时珍曰∶荠 即甜桔梗）。",g:"清热药"},
  "荷叶":{o:"荷叶",c:"轻宣，升阳，散瘀 \n苦平。其色青，其形仰，其中空，其象震（震仰盂），感少阳甲胆之气。烧饭合药，裨 \n助脾，胃而升发阳气（洁古枳术丸，用荷叶烧饭为丸），痘疮倒 者，用此发之（僵蚕等分 \n为末，胡荽汤下。闻人规曰∶胜于人牙、龙脑）。能散瘀血，留好血。治吐、衄、崩、淋， \n损伤产瘀（熬香末服），一切血证，洗肾囊风（东垣曰∶雷头风症，头面疙瘩肿痛，憎寒恶 \n热，状如伤寒，病在三阳，不可过用寒药重剂，诛罚无过，处清震汤治之。荷叶一枚，升麻、 \n苍术各五钱，煎服。郑奠一曰∶荷叶研末，酒服三钱，治遗精极验）。",g:"其他"},
  "荸荠":{o:"荸荠",c:"\\x一名凫茈，一名乌芋，一名地栗\\x \n补中，泻热，消食 \n甘微寒滑。益气安中，开胃消食（饭后宜食之），除胸中实热。治五种噎膈（五膈，忧 \n膈、恚膈、气膈、热膈、寒膈。噎亦五种，气噎、食噎、劳噎、忧噎、思噎），消渴黄胆， \n血证蛊毒（末服辟蛊），能毁铜（汪机曰∶食铜钱，食之则钱化。可见为消坚削积之物，故 \n能开五膈，消宿食，治误吞铜也）。",g:"消食药"},
  "莪术":{o:"蓬莪术",c:"泻，破血，行气，消积 \n辛苦气温。入肝经血分。破气中之血（能通肝经聚血），消瘀通经，开胃化食，解毒止 \n痛。 \n治心腹诸痛，冷气吐酸，奔豚 癖（酒、醋磨服。 ，音贤，小腹积。 癖多见于男子 \n，症瘕多见于妇人。莪术香烈，行气通窍，同三棱用，治积聚诸气良。按∶五积，心积曰伏 \n梁，起脐上至心下；肝积曰肥气，在左胁；肺积曰息贲，在右胁；脾积曰痞气，在胃脘右侧 \n；肾积曰奔豚，在小腹上至心下。治之不宜专用下药，恐损真气，宜于破血行气药中，加补 \n脾胃药。气旺方能磨积，正旺则邪自消也。经曰∶大积大聚，其可犯也，哀其大半而止，过 \n者死。东垣五积方，用三棱、莪术，皆兼人参赞助成功。按治积诸药，神曲、麦芽",g:"活血化瘀药"},
  "莱菔":{o:"莱菔",c:"\\x俗作萝卜\\x \n宣，行气，化痰，消食 \n辛甘属土。生食升气，熟食降气。宽中化痰，散瘀消食（丹溪曰∶气升则食自降）。治 \n吐血衄血，咳嗽吞酸，利二便，解酒毒，制面毒、豆腐积（昔有人病，梦红裳女子引入宫殿， \n小姑歌云∶五灵楼阁晓玲珑，天府由来是此中，惆怅闷怀言不尽，一丸莱菔火吾宫。一道士 \n云∶此犯大麦毒也。女子心神，小姑脾神。《医经》∶莱菔制面毒，遂以药并莱菔治之，果 \n愈。腐浆见莱菔则难收）。生捣治噤口痢，止消渴，涂跌打汤火伤。多食渗血，故白人髭发 \n（服何首乌、地黄者忌之，生姜能制其毒。夏月食其菜数斤，秋不患痢，冬月以菜叶摊屋瓦 \n上，任霜雪打压，至春收之，煎汤饮，治痢得效。有人避难入",g:"化痰止咳平喘药"},
  "莲子":{o:"莲子",c:"补脾，涩肠，固精 \n甘温而涩，脾之果也。脾者黄宫，故能交水火而媾心肾，安靖上下君、相火邪（古方治 \n心肾不交、劳伤白浊，有莲子清心饮，补心肾有瑞莲丸）。益十二经脉血气，涩精气，浓肠 \n胃，除寒热。治脾泄久痢，白浊梦遗，女人崩带及诸血病。大便燥者勿服。去心、皮，蒸熟 \n焙干用。得茯苓、山药、白术、枸杞良。 \n黑而沉水者为石莲，清心除烦，开胃进食，专治噤口痢、淋浊诸证（石莲入水则沉，入 \n卤则浮。煎盐人以之试卤，莲浮至顶，卤乃可煎。落田野中者，百年不坏，人得食之，发黑 \n不老。肆中石莲，产广中树上，其味大苦，不宜入药）。 \n莲心为末，米饮下，疗产后血竭。",g:"收涩药"},
  "莲蕊须":{o:"莲蕊须",c:"涩精 \n甘温而涩。精心通肾，益血固精，乌须黑发，止梦泄遗精，吐崩诸血。略与莲子同功。",g:"收涩药"},
  "菊花":{o:"甘菊花",c:"祛风温，补肺肾，明目 \n味兼甘苦，性禀平和，备受四气（冬苗、春叶、夏蕊、秋花），饱经霜露，得金、水之 \n精居多。能益金、水二脏（肺肾），以制火而平木（心肝）。木平则风息，火降则热除。故能 \n养目血，去翳膜（与枸杞相对蜜丸久服，永无目疾）。治头目眩晕（风热），散湿痹游风。 \n以单瓣味甘者入药（花小味苦者，名苦薏，非真菊也。《牧署闲谈》云∶真菊延龄，野 \n菊泻人）。术、枸杞、地骨皮为使。黄者入阴分，白者入阳分。紫者入血分。可药可饵，可 \n酿可枕，《仙经》重之。",g:"解表药"},
  "菟丝子":{o:"菟丝子",c:"平补三阴 \n甘辛和平。凝正阳之气，入足三阴（脾、肝、肾）。强阴益精，温而不燥，不助相火。 \n治五劳七伤，精寒淋沥，口苦燥渴（脾虚肾燥而生内热，菟丝益阴清热）。祛风明目，补卫 \n气，助筋脉，益气力，肥健人（补肝肾之效。《老学庵笔记》∶予族弟，少服菟丝子凡数年， \n饮食倍常，血气充盛。忽因浴见背肿，随视随长，乃大疽也。适值金银花开，饮至数斤，肿 \n遂消。菟丝过服，尚能作疽，以此知金石药，不可不戒。昂按∶此人或感他毒，未可尽归咎 \n于菟丝也）。 \n无根，蔓延草上，子黄如黍粒。得酒良。淘去泥沙，酒浸一宿，曝干捣末。山药为使。",g:"补虚药"},
  "菱":{o:"菱",c:"\\x俗名菱角，一名芰\\x \n泻，解暑，止渴 \n甘寒。安中消暑，止渴解酒。有两角、三角、四角、老嫩之殊（《武陵记》以三角、四 \n角者为芰，两角者为菱。菱花随月而转，犹葵花之向日）。",g:"其他"},
  "萆":{o:"萆",c:"通，祛风湿，补下焦 \n甘苦性平。入足阳明、厥阴（胃、肝）。祛风去湿，以固下焦（阳明主肉，属湿。厥阴 \n主筋，属风），补肝虚（去风），坚筋骨（风湿去，则筋骨坚），益精明目。 \n治风寒湿痹，腰痛久冷，关节老血，膀胱宿水，阴痿失溺，茎痛遗浊，痔 恶疮（诸病 \n皆阳明湿热流入下焦，萆 能除浊厘清，古方有萆 厘清饮。史国信云∶若欲兴阳，先滋筋 \n力。若欲便清，先分肝火。《万金护命方》云∶凡人小便频数、便时痛不可忍者，此疾必因 \n大肠秘热不通，水液只就小肠，大肠愈加干竭，甚则身热心躁，思水，即重证也。此疾本因 \n贪酒色，或过食辛热、荤腻之物，积有热毒，腐物、瘀血，乘虚流入小肠，故便时作痛也。 \n此便数而痛",g:"祛风湿药"},
  "萹蓄":{o:"蓄",c:"\\x一名扁竹\\x \n通淋 \n苦平。杀虫疥，利小便。治黄胆热淋，蛔咬腹痛，虫蚀下部（煮服）。 \n叶细如竹，弱茎蔓引，促节有粉，三月开红花。",g:"利水渗湿药"},
  "落花生":{o:"落花生",c:"补脾润肺 \n辛能润肺，香能舒脾。果中佳品，出闽广。藤生花，落地而结实，故名（按∶落花生《 \n本草》未收，本无当医药之用，然能益脾润肺，实佳果也。因世人谤之者多，附见于此，明 \n其有利无害也）。炒食。",g:"其他"},
  "葛根":{o:"葛根",c:"轻，宣，解肌，升阳，散火 \n辛甘性平，轻扬升发。入阴阳经，能鼓胃气上行，生津止渴（风药多燥，葛根独能止渴 \n者，以能升胃气、入肺而生津耳）。兼入脾经，开腠发汗，解肌退热（脾主肌肉）。为治脾胃 \n虚弱泄泻之圣药（经曰∶清气在下，则生飧泄。葛根能升阳明清气）。 \n疗伤寒中风，阳明头痛（张元素曰∶头痛如破，乃阳明中风，可用葛根葱白汤；若太阳 \n初病，未入阳明而头痛者，不可便服升葛汤发之，反引邪气入阳明也。仲景治太阳、阳明合 \n病，桂枝汤加葛根麻黄；又有葛根黄芩黄连解肌汤，是用以断太阳入阳明之路，非太阳药也 \n）。血痢温疟（丹溪曰∶治疟无汗要有汗，散邪为主，带补；有汗要无汗，扶正为主，带散。 \n若阳疟",g:"解表药"},
  "葱":{o:"葱",c:"轻，发表和里，宣，通阳活血 \n生辛散，熟甘温（陶宏景曰∶白冷青热，伤寒汤中不得用青），外实中空，肺之菜也。 \n肺主皮毛，其合阳明（大肠）。故发汗解肌，以通上下阳气（仲景白通汤、通脉四逆汤并加 \n之，以通脉回阳），益目睛（白睛属肺），利耳鸣，通二便（时珍曰∶葱管吹盐入玉茎中，治 \n小便不通，及转脬危急者极效）。治伤寒头痛，时疾热狂，阴毒腹痛（阴证厥逆，用葱白安 \n脐上熨之）。气通则血活（气为血帅），故治吐血衄血，便血痢血（《食医心镜》∶葱煮粥食， \n治赤白痢，薤粥亦良），折伤血出（火煨研封，止痛无瘢），乳痈风痹，通乳安胎（妇人妊娠 \n伤寒，葱白一物汤，发汗而安胎，加生姜亦佳。《删繁方》∶合香豉、",g:"解表药"},
  "葶苈":{o:"葶苈",c:"大泻气秘，通，行水 \n辛苦大寒。属火性急，大能下气，行膀胱水。肿中水气 急者，非此不能除。破积聚症 \n结，伏留热气，消肿除痰，止嗽定喘（水湿泛溢，为肿胀，为痰嗽，为喘满）通经利便。久 \n服令人虚（《十剂》曰∶泄可去闭，葶苈、大黄之属是也。大黄泄阴分血闭，葶苈泄阳分气 \n闭，气味俱浓，不减大黄。然有甜、苦二种，甜者性缓，苦者性急，泄肺而伤胃，宜大枣辅 \n之。仲景有葶苈大枣泻肺汤，治肺气喘急不得卧。昂按∶辅以大枣，补土所以制水）。 \n子如黍米，微长色黄。合糯米微炒，去米用。得酒良。榆皮为使。",g:"其他"},
  "蒲公英":{o:"蒲公英",c:"\\x一名黄花地丁\\x \n泻热，解毒 \n甘平。花黄，属土，入太阴、阳明（脾、胃）。化热毒，解食毒，消肿核。 \n专治乳痈（乳头属厥阴，乳房属阳明。同忍冬煎，入少酒服，捣敷亦良）疔毒，亦为通 \n淋妙品（诸家不言治淋，试之甚验）。擦牙、乌髭发（瑞竹堂有还少丹，方取其通肾。东垣 \n曰∶苦寒肾经君药），白汁涂恶刺（凡螳螂诸虫，盛夏孕育，游诸物上，必遗精汁，干久则 \n有毒。人手触之成疾，名狐尿刺。惨痛不眠，百疗难效，取汁浓涂即愈，千金方极言其功）。 \n叶如莴苣，花如单瓣菊花，四时有花，花罢飞絮，断之茎中有白汁（郑方升曰∶一茎两 \n花，高尺许者，掘下数尺，根大如拳，旁有人形拱抱。捣汁酒服，治噎膈如神）。",g:"清热药"},
  "蒲黄":{o:"蒲黄",c:"生滑行血，炒涩止血 \n甘平。厥阴（心包、肝）血分药。生用性滑，行血消瘀，通经脉，利小便，祛心、腹、 \n膀胱寒、热（同五灵脂，治心腹血气痛，名失笑散）。 \n疗扑打损伤，疮疖诸肿（一妇舌胀满口，以蒲黄频掺，比晓乃愈。宋度宗舌胀满口，御 \n医用蒲黄、干姜末等分，搽之愈。时珍曰∶观此则蒲黄之凉血、活血可知矣。盖舌为心苗， \n心包相火。乃其臣使，得干姜，是阴阳相济也）。 \n炒黑性涩，止一切血，崩带泄精。 \n香蒲，花中蕊屑，汤成入药。",g:"止血药"},
  "蓖麻子":{o:"蓖麻子",c:"泻，通窍，拔毒，出有形滞物 \n辛苦有毒。性善收，亦善走，能开通诸窍、经络。 \n治偏风不遂， 斜（捣饼。左贴右，右贴左，即止）口噤，鼻窒耳聋（捣烂绵裹，塞耳 \n塞鼻），喉痹舌胀（油作纸，燃烟熏）。能利水气，治水症浮肿（研服。当下青黄水，壮人只 \n可五粒）能出有形滞物。治针刺入肉（捣敷伤处，频看，刺出即去药，恐努出好肉），竹木 \n骨哽（蓖麻子一两，凝水石二两，研匀。以一捻置舌根，噙咽，自然不见），胞胎不下（蓖 \n麻一粒，巴豆一粒，麝香一分，贴脐中并足心，胎下即去之。若子肠挺出者，捣膏涂顶心， \n即收）。能追脓拔毒，敷瘰 恶疮，外用屡奏奇功（鹈鹕油，能引药气入内。蓖麻油，能拔 \n气出外，故诸膏多用之",g:"利水渗湿药"},
  "蓼实":{o:"蓼实",c:"宣，温中 \n辛温。温中明目，耐风寒，下水气（时珍曰∶古人种蓼为蔬，收子入药，今为酒曲用其 \n汁耳。以香蓼、青蓼、紫蓼为良）。 \n有香蓼、青蓼、紫蓼、赤蓼、木蓼、水蓼、马蓼。",g:"温里药"},
  "蔓荆子":{o:"蔓荆子",c:"轻宣，散上部风热 \n辛苦微寒、轻浮升散。入足太阳、阳明、厥阴（膀胱、胃、肝）经。搜风凉血，通利九 \n窍。 \n治湿痹拘挛，头痛脑鸣（太阳脉络于脑），目赤齿痛（齿虽属肾，为骨之余。而上龈属 \n足阳明，下龈属手阳明。阳明风热上攻，则动摇肿痛），头面风虚之证。明目固齿，长 \n发泽肌。 \n去膜，打碎用，亦有酒蒸、炒用者。恶石膏、乌头。",g:"解表药"},
  "蔓菁子":{o:"蔓菁子",c:"\\x即芜菁\\x \n泻热，利水，明目 \n苦辛。泻热解毒，利水明目（古方治目，用之最多）。治黄胆（捣服）腹胀（捣研滤汁 \n饮，或吐或利，腹中自宽，得汗愈），症瘕积聚，小儿血痢（蜜和汁服），一切疮疽（凡痈疽 \n捣敷皆良。醋调敷秃疮，盐捣敷乳痈。冬取根用），敷蜘蛛咬毒（陈藏器曰∶蔓菁园中无蜘 \n蛛。李时珍曰∶蔓菁子可升可降，能汗能吐能下，能利小便，明目解毒，其功甚伟，世罕知 \n用，何哉？）。根，捣敷阴囊肿大如斗；末服解酒毒；和芸苔（油菜也）根捣汁，鸡子清调， \n涂诸热毒（单盐捣，不用芸苔亦可）。",g:"清热药"},
  "蔷薇根":{o:"蔷薇根",c:"泻湿热 \n苦涩而冷。入胃、大肠经。除风热、湿热，生肌杀虫。 \n治泄痢消渴，牙痛口糜（煎汁含漱），遗尿好眠，痈疽疮癣。 \n花有黄、白、红、紫数色，以黄心、白色、粉红者入药。 \n子，名营实，酸温。主治略同（《千金》曰∶蔷薇根，角蒿，口疮之神药。角蒿所在多 \n有，开淡红紫花，角微弯，长二寸许，辛苦有小毒。治恶疮有虫，及口齿疮）。",g:"驱虫药"},
  "蕤仁":{o:"蕤仁",c:"\\x亦名白 \\x \n补，明目 \n甘温（《别录》微寒）。入心、肝、脾三经。消风散热，益水生光（三经皆血脏也。血得 \n其养，则目疾平。凡目病在表，当疏风清热。在里属肾虚、血少、神劳，宜补肾养血安神。 \n远视为肾水亏，近视为火不足）。 \n治目赤肿痛， 烂泪出，亦治心腹邪热，结气痰痞（今人惟用疗眼。陈藏器曰∶生治足 \n睡，熟治不眠）。丛生有刺，实如五味，圆扁有纹，紫赤可食。取仁浸，去皮、尖，研用。",g:"补虚药"},
  "蕲蛇":{o:"白花蛇",c:"宣，祛风湿 \n甘咸而温。蛇善行数蜕，如风之善行数变，花蛇又食石南（食石南藤花、叶。石南辛苦 \n，治风），故能内走脏腑，外彻皮肤，透骨搜风，截惊定搐。治风湿瘫痪，大风疥癞（《开宝 \n本草》云∶治中风口眼 斜，半身不遂。《经疏》云∶前症定缘阴虚、血少、内热而发，与 \n得之风湿者殊。料白花蛇非所宜也，宜辨。凡服蛇酒药，切忌见风）。出蕲州。龙头虎口， \n黑质白花，胁有二十四方胜纹，腹有念珠斑。尾有佛指甲，虽死而眼光不枯。他产则否。头 \n、尾有毒，各去三寸，亦有单用头尾者。酒浸三日，去尽皮、骨，大蛇一条只得净肉四两。",g:"祛风湿药"},
  "薄荷":{o:"薄荷",c:"轻，宣，散风热 \n辛能散，凉能清（本经温，盖体温而用凉也），升浮能发汗。搜肝气而抑肺盛，消散风 \n热，清利头目。 \n治头痛头风，中风失音，痰嗽口气，语涩舌胎（含漱），眼耳咽喉，口齿诸病（辛香通 \n窍，而散风热），皮肤瘾疹，瘰 疮疥，惊热（凡小儿治惊药，俱宜薄荷汤调），骨蒸。破血 \n止痢（能治血痢。血痢病在凝滞，辛能散，凉能清）。虚人不宜多服（能发汗疏表，夏月多 \n服，泄人元气）。 \n苏产气芳者良（薄荷，猫之酒也；犬，虎之酒也；蜈蚣，鸡之酒也；桑椹，鸠之酒也； \n莽草，鱼之酒也，食之皆醉。被猫伤者，薄荷汁涂之）。",g:"解表药"},
  "薏苡仁":{o:"薏苡仁",c:"补脾胃，通，行水 \n甘淡。微寒而属土，阳明（胃）药也。甘益胃，土胜水。淡渗湿。泻水所以益土，故健 \n脾。治水肿湿痹，香港脚疝气，泄痢热淋。益土所以生金，故补肺清热（色白入肺，微寒清热）， \n治肺痿肺痛，咳吐脓血（以猪肺沾苡仁米服）。扶土所以抑木，故治风热筋急拘挛（厥阴风 \n木主筋，然治筋骨之病，以阳明为末。阳明主润宗筋，宗筋主束骨而利机关者也。阳明虚则 \n宗筋纵驰，故经曰∶治痿独取阳明，又曰∶肺热叶焦，发为痿 。盖肺者相传之官，治节出 \n焉，阳明湿热上蒸于肺，则肺热叶焦，气无所主而失其治节，故痿 。薏苡理脾，而兼清热 \n补肺，筋寒则急，热则缩，湿则纵。然寒湿久留，亦变为热。又有热气熏蒸，水液不",g:"利水渗湿药"},
  "薤":{o:"薤",c:"\\x一名 子， 音叫\\x \n滑，利窍，助阳 \n辛苦滑温。调中助阳，散血生肌，泄下焦大肠气滞。治泄痢下重（王好古曰∶下重者， \n气滞也，四逆散加此以泄滞。按∶下重亦有气虚、血虚、火热、风燥之不同），胸痹刺痛（仲 \n景用栝蒌薤白白酒汤），肺气喘急。安胎利产，涂汤、火伤（和蜜捣用。《肘后方》∶中恶卒 \n死者，用薤汁灌鼻中，韭汁亦可）。叶似韭而中空，根如蒜。取白用。忌牛肉（其叶光滑， \n露亦难贮，故云薤露）。",g:"其他"},
  "藕":{o:"藕",c:"凉血散瘀 \n涩平。解热毒，消瘀血，止吐、衄、淋、痢一切血证（和生地汁、童便服良）。藕生甘 \n寒，凉血散瘀（宋大官作血 ，误落藕皮，血遂涣散不凝。一人病血淋，痛胀欲死，李时珍 \n以发灰二钱，藕汁调服，三日而愈。《梅师方》∶产后余血上冲，煮汁服），止渴除烦（《圣惠 \n方》∶藕汁，蜜和服，治时气烦渴），解酒毒、蟹毒（捣烂，热酒调服）。煮熟甘温，益胃补 \n心（多孔象心），止泻（能实大肠）止怒，久服令人欢（益心之效）。生捣，罨金疮伤折；熟 \n捣，涂坼裂冻疮（《肘后方》∶卒中毒箭者，藕汁饮，多多益善。孟诜曰∶产后忌生冷，独藕 \n不忌，为能散瘀血也）澄粉亦佳，安神益胃。",g:"清热药"},
  "藜芦":{o:"藜芦",c:"宣，引吐 \n辛寒至苦，有毒。 \n入口即吐，善通顶，令人嚏，风痫证多用之（张子和曰∶一妇病风痫，初一、二年一作 \n，后渐日作，甚至一日数作，求死而已。值岁大饥，采百草食，见野草若葱，采蒸饱食，觉 \n不安，吐胶涎数日，约一二斗，汗出如洗，甚昏困，后遂轻健如常人。以所食葱访人，乃憨 \n葱苗，即藜芦是矣。时珍曰∶和王妃年七十，中风不省，牙关紧闭。先考太医吏目月池翁诊 \n视，药不得入。不获已，打去一齿，浓煎藜芦汤灌之，少顷噫气，遂吐痰而苏。药不瞑眩， \n厥疾不瘳，诚然）。 \n取根去头。用黄连为使。反细辛、芍药、诸参。恶大黄。畏葱白（吐者、服葱汤即止）。",g:"其他"},
  "藿香":{o:"藿香",c:"宣，去恶气 \n辛甘微温。入手足太阴（肺、脾）。快气和中，开胃止呕（胃弱、胃热而呕者忌用），去 \n恶气，进饮食。 \n治霍乱吐泻，心腹绞痛，肺虚有寒，上焦壅热（能理脾、肺之气。古方有藿香正气散， \n正气通畅，则邪逆自除）。 \n出交广，方茎有节，叶微似茄汁。古惟用叶，今枝、茎亦用之，因叶多伪也。",g:"消食药"},
  "虎骨":{o:"虎骨",c:"宣，去风，健骨 \n味辛微热。虎属金而制木，故啸则风生。追风健骨，定痛辟邪。治风痹拘挛疼痛，惊悸 \n颠痫，犬咬骨哽（为末，水服，犬咬敷患处）。以头骨、胫骨良（虎虽死，犹立不仆，其气 \n力皆在前胫。时珍曰∶凡辟邪疰，治惊痫，瘟疟、头风，当用头骨。治手足风，当用胫骨。 \n治腰脊风，当用脊骨，各从其类也）。 \n虎肚，治反胃（取生者，存滓秽勿洗，新瓦固 存性，为末。入平胃散一两，每服三钱 \n，效。昂按∶虎肚丸宜于食膈，若寒膈、气膈、血膈、痰膈，恐难见功）。 \n虎睛为散，竹沥下，治小儿惊痫夜啼。",g:"其他"},
  "虾":{o:"虾",c:"补阳 \n甘温。托痘疮。下浮汁，吐风痰（中风症，以虾半斤，入姜、葱、酱料水煮，先吃虾， \n次吃汁，以鹅翎探引，吐出痰涎，随证用药），壮阳道。",g:"其他"},
  "蚺蛇胆":{o:"蚺蛇胆",c:"泻热、明目、护心 \n蚺（音髯）禀己土之气，胆属甲乙风木，气寒有小毒，其味苦而带甘。凉血明目，疗疳 \n杀虫，主厥阴、太阴（肝木、脾土）之病。 \n肉，极腴美，主治略同。 \n取胆粟许，置水上，旋行极速者真（胆上旬近头，中旬近心，下旬近尾。能护心止痛， \n受杖时噙之，杖多不死）。",g:"清热药"},
  "蛇床子":{o:"蛇床子",c:"补肾命，去风湿 \n辛苦而温。强阳益阴，补肾祛寒，祛风燥湿。 \n治痿囊湿，女子阴痛阴痒（湿生虫，同矾煎汤洗），子脏虚寒，产门不闭（炒热熨之）， \n肾命之病。及腰酸体痛，带下脱肛，喉痹齿痛，湿癣恶疮（杀虫止痒），风湿诸病。煎汤浴， \n止风痒（时珍曰∶肾命、三焦气分之药，不独补助男子，而且有益妇人，世人舍此而求补药 \n于远域，岂非贵耳贱目乎？）。 \n似小茴而细。微妙，杀毒则不辣（以地黄汁拌蒸三遍佳）。恶丹皮、贝母、巴豆。",g:"温里药"},
  "蛇蜕":{o:"蛇蜕",c:"轻，宣，去风毒 \n甘咸无毒（甄权∶有毒）。性灵而能辟恶，故治鬼魅蛊毒；性窜而善去风，故治惊痫风 \n疟，重舌（《圣惠方》∶烧末敷）喉风；性毒而能杀虫，故治疥癣恶疮，疔肿痔漏；属皮而性 \n善蜕，故治皮肤疮疡，产难目翳。用白色如银者，皂荚水洗净。或酒、或醋、或蜜浸，炙 \n黄用，或烧存性，或盐泥固 ，各随本方。",g:"驱虫药"},
  "蛤粉":{o:"蛤粉",c:"涩 \n蛤蜊壳 为粉。与牡蛎同功（海藏曰∶肾经血分药。宋徽宗宠妃病痰嗽，面肿不寐，李 \n防御治之，三日不效，当诛，李技穷忧泣，忽闻市人卖嗽药，一文一帖，吃了今夜得睡，色 \n淡碧，李市之。恐药猛悍，先自试，觉无害，共并三帖为一以进，妃服之，是夕寝安嗽止， \n面肿亦消。帝大悦，赐直万金。李不知其方，惧得罪。伺得市人，重价求之，乃蚌壳研粉， \n少加青黛也。以淡荠水，加麻油数滴，调服。《圣惠方》∶白蚬壳研粉，米饮调，治咳嗽不 \n止）。 \n肉，咸冷，止渴解酒（牡蛎、蛤蜊、海蛤、文蛤，并出海中，大抵海物咸寒，功用略同 \n。江湖蛤蚌，无咸水浸渍，但能清热利湿，不能软坚）。 \n文蛤。背有花纹，兼能除烦渴，利小便",g:"清热药"},
  "蛤蚧":{o:"蛤蚧",c:"补肺润肾，定喘止嗽 \n咸平。补肺润肾，益精助阳。治渴通淋，定喘止嗽，肺痿咯血，气虚、血竭者宜之（能 \n补肺、益水源。李时珍曰∶补肺止渴，功同人参。益气扶羸，功同羊肉。《经疏》曰∶咳嗽 \n由风寒外邪者不宜用）。出广南。首如蟾蜍，背绿色，斑点如绵纹。雄为蛤（鸣声亦然，因 \n声而名），皮粗口大，身小尾粗；雌为蚧，皮细口尖，身大尾小。雌雄相呼，屡日乃交，两 \n两相抱，捕者擘之，虽死不开。房术用之甚效，不论牝牡者，只可入杂药。口含少许，奔走 \n不喘者真。药力在尾（见人捕之，辄自啮断其尾，尾不全者不效）。凡使去头足（雷 曰∶ \n其毒在眼，用须去眼），洗去鳞内不净及肉、毛，酥炙，或蜜炙、或酒浸焙用。",g:"补虚药"},
  "蜂蜜":{o:"蜂蜜",c:"\\x亦名石蜜、岩蜜\\x \n补中，润燥，滑肠 \n草木精英，合露气以酿成。生性凉，能清热；熟性温，能补中。甘而和，故解毒。柔而 \n滑，故润燥。甘缓可以去急，故止心腹、肌肉、疮疡诸痛；甘缓可以和中，故能调营卫，通 \n三焦，除众病，和百药（故丸药多用之），而与甘草同功。止嗽治痢（解毒润肠，最治痢疾。 \n姜汁和服甚佳），明目悦颜。同薤白捣，涂汤火伤。煎炼成胶，通大便秘（乘热纳谷道中， \n名蜜煎导）。然能滑肠，泄泻与中满者忌用之。以白如膏者良（汪颖曰∶蜜以花为主。闽广 \n蜜热，川蜜温，西蜜凉。安宣州有黄连蜜，味小苦，点目热良。西京有梨花蜜，色白如脂）。 \n用银、石器，每蜜一斤入水四两，桑火慢熬，掠出浮沫，",g:"补虚药"},
  "蜈蚣":{o:"蜈蚣",c:"宣，去风 \n辛温有毒。入厥阴肝经。善走能散，治脐风撮口（炙末，猪乳调服），惊痫瘰 ，蛇症 \n（能制蛇）疮甲（趾甲内恶肉突出，俗名鸡眼睛，蜈蚣焙研敷之，以南星末醋调，敷四围）， \n杀虫（古方治嗽多生用之）堕胎。取赤足黑头者，火炙，去头、足、尾、甲，将荷叶火煨用， \n或酒炙。畏蜘蛛、蜒蚰（不敢过所行之路，触着即死）、鸡屎、桑皮、盐（中其毒者，以桑 \n汁、盐、蒜涂之。被咬者，捕蜘蛛置咬处，自吸其毒，蜘蛛死，放水中，吐而活之）。",g:"平肝息风药"},
  "蝉蜕":{o:"蝉蜕",c:"轻，散风热 \n蝉乃土木余气所化，饮风露而不食。其气清虚而味甘寒，故除风热；其体轻浮，故发痘 \n疹；其性善蜕，故退目翳，催生下胞；其蜕为壳，故治皮肤疮疡瘾疹（与薄荷等分，为末， \n酒调服）；其声清响，故治中风失音；又昼鸣夜息，故止小儿夜啼，蝉类甚多，惟大而色黑 \n者入药，洗去泥土、翅、足，浆水煮，晒干用（攻毒生用）。 \n蚱蝉，治小儿惊痫夜啼，杀疳去热，出胎下胞（时珍曰∶治皮肤疮疡风热，当用蝉蜕； \n治脏腑经络，当用蝉身。各从其类也）。",g:"解表药"},
  "蝎":{o:"蝎",c:"宣，去风 \n辛甘有毒。色青属木，故治诸风眩掉（皆属肝木），惊痫搐掣，口眼 斜（白附、僵蚕、 \n全蝎等分为末，名牵正散。酒服二钱，甚效），疟疾风疮，耳聋带疝，厥阴风木之病（东垣 \n曰∶凡疝气带下，皆属于风。蝎乃治风要药，俱宜加而用之。汪机曰∶破伤风，宜以全蝎、 \n防风为主）。类中风、慢脾惊属虚者忌用。全用去足，焙，或用尾，尾力尤紧。形紧小者良 \n（人被螫者，涂蜗牛即解）。",g:"其他"},
  "蟹":{o:"蟹",c:"泻，散血 \n咸寒。除热解结，散血通经，续筋骨（筋绝伤者，取蟹黄、足髓，熬纳疮中，筋即续生 \n。骨节脱离者，生捣，热酒调服，渣涂半日，骨内谷谷有声即好），涂漆疮（能败漆）。然寒 \n胃动风。 \n蟹爪堕胎（产难及子死腹中者，服蟹爪汤即出。其螯烧烟，能集鼠于庭。中蟹毒者，捣 \n藕节，热酒调服。腌蟹，中入蒜则不沙）。",g:"其他"},
  "蟾蜍":{o:"蟾蜍",c:"\\x即癞虾蟆\\x \n泻，疗疳，拔毒 \n蟾，土精而应月魄，辛凉微毒，入阳明胃。发汗退热，除湿杀虫，治疮疽发背（未成者 \n，用活蟾蜍系疮上。半日，蟾必昏愦，置水中救其命。再易一个，三易则毒散矣。势重者， \n剖蟾蜍合疮上，不久必臭不可闻，如此二三易，其肿自愈），小儿劳瘦疳疾。 \n蟾酥，辛温大毒。助阳气，治疔肿发背，小儿疳疾脑疳（即蟾蜍眉间白汁，能烂人肌肉 \n，惟疔疳或合他药服一二厘，取其以毒攻毒。脑疳乳和滴鼻中。外科多用之。蟾蜍肪涂玉， \n刻之如蜡。肪音方，脂也）。",g:"解表药"},
  "血竭":{o:"血竭",c:"补，和血，敛疮 \n甘咸。色赤入血分。补心包、肝血不足，专除血痛，散瘀生新，为和血之圣药。治内伤 \n血聚，金疮折跌，疮口不合，止痛生肌。性急，不可多使，引脓（血竭单入血分、乳香、没 \n药兼入气分，皆木脂也）。出南番。色赤，以染透指甲者为真（假者是海母血，味大咸，有 \n腥气）。单碾用（同众药捣，则作尘飞）。",g:"其他"},
  "补骨脂":{o:"破故纸",c:"\\x一名补骨脂\\x \n燥，补命火 \n辛苦大温。入心包、命门。补相火以通君火，暖丹田，壮元阳，缩小便（亦治遗尿）。 \n治五劳七伤（五脏之劳，七情之伤），腰膝冷痛，肾冷精流，肾虚泄泻（肾虚则命门火 \n衰，不能熏蒸脾胃，脾胃虚寒，迟于运化，致饮食减少，腹胀肠鸣，呕涎泄泻，如鼎釜之下 \n无火，物终不熟，故补命门相火即所以补脾。破故纸四两，五味三两，肉蔻二两，吴茱一两， \n姜煮枣丸，名四神丸，治五更泄泻），妇人血气（妇人之血脱气陷，亦犹男子之肾冷精流） \n堕胎。 \n出南番者色赤，岭南者色绿。酒浸蒸用，亦有童便乳浸、盐水炒者。得胡桃、胡麻良。 \n恶甘草（唐郑相国方∶破故纸十两，酒浸蒸为末，胡桃肉二十两，去",g:"补虚药"},
  "西瓜":{o:"西瓜",c:"泻暑 \n甘寒。解暑除烦，利便醒酒，名天生白虎汤（西瓜、甜瓜，皆属生冷，多食伤脾助湿。 \n《卫生歌》云∶瓜、桃生冷宜少食，免致成疟痢。瓜性寒，曝之尤寒。《稽食赋》云∶ \n瓜、曝则寒，油煎则冷，物性之异也）。",g:"其他"},
  "覆盆子":{o:"复盆子",c:"平补肝肾 \n甘酸微温。益肾脏而固精，补肝虚而明目，起阳痿，缩小便（寇氏曰∶服之当复其溺器 \n，故名），泽肌肤，乌髭发（榨汁涂发不白），女子多孕。 \n同蜜为膏，治肺气虚寒（李士材曰∶强肾无燥热之偏，固精无凝涩之害，金玉之品也）。 \n状如复盆，故名。去蒂，淘净捣饼，用时酒拌蒸。叶绞汁，滴目中，出目弦虫，除肤赤 \n，收湿止泪。",g:"收涩药"},
  "诃子":{o:"诃子",c:"涩肠，敛肺，泻气 \n苦以泄气消痰，酸以敛肺降火（东垣曰∶肺苦气上逆，急食苦以泄之，以酸补之。诃子 \n苦重泄气，酸轻不能补肺，故嗽药中不用），涩以收脱止泻，温以开胃调中。 \n治冷气腹胀，膈气呕逆，痰嗽喘急（肺挟痰水，或被火伤，故宜苦酸以敛之），泻痢脱 \n肛，肠风崩带（皆取其酸涩），开音止渴（肺敛则音开，火降则渴止。古方有诃子清音汤）。 \n然苦多酸少，虽涩肠而泄气，气虚及嗽痢初起者，忌服（同乌梅、倍子，则收敛；同陈皮、 \n浓朴，则下气。得人参，治肺虚寒嗽；得陈皮、砂仁，治冷气腹胀。佐白术、莲子，治虚寒 \n久泻；佐樗皮，治肠癖便血。同蛇床、五味、山茱、续断、杜仲，治虚寒带下）。 \n从番舶来，番名诃黎",g:"收涩药"},
  "谷精草":{o:"谷精草",c:"轻，明目 \n辛温轻浮。上行阳明（胃），兼入厥阴（肝）。明目退翳之功在菊花之上。亦治喉痹齿痛， \n阳明风热。 \n收谷后，荒田中生。叶似嫩秧，花如白星（小儿雀盲者，羯羊肝一具，不洗，竹刀割开 \n，入谷精煮熟食之。或作丸，茶下）。",g:"其他"},
  "谷芽":{o:"谷芽",c:"健脾消食 \n甘温。开胃快脾，下气和中，消食化积。炒用。",g:"补虚药"},
  "象皮":{o:"象皮",c:"外用，敛金疮 \n象肉壅肿，以刀刺之，半日即合。治金疮不合者，用其皮灰，亦可以熬膏入散。 \n象胆亦能辟尘，与熊胆同功。",g:"其他"},
  "贝母":{o:"贝母",c:"宣，散结，泻热，润肺，清火 \n微寒，苦泻心火，辛散肺郁（入肺经气分，心火降则肺气宁。《诗》曰∶言采其虻。虻 \n即贝母也。取其解郁）。润心肺，清虚痰。 \n治虚劳烦热，咳嗽上气，吐血咯血，肺痿肺痈，喉痹（君相之火）目眩（火热上攻）， \n淋沥（小肠邪热，心与小肠相表里，肺为气化之源）瘿瘤（化痰），乳闭产难。功专散结除 \n热，敷恶疮（唐时有人膊上生疮如人面，能饮酒食物，亦无他苦。遍投诸药悉受之，至贝母。 \n疮乃颦眉，灌之数日，成痂而愈），敛疮口（火降邪散，疮口自敛，非贝母性收敛也。俗以 \n半夏燥毒，代以贝母，不知贝母寒润，主肺家燥痰，半夏温燥，主脾家湿痰，设或误用，贻 \n误非浅。故凡风、寒、湿、食诸痰",g:"化痰止咳平喘药"},
  "贯众":{o:"贯众",c:"泻热，解毒 \n味苦微寒，有毒，而能解邪热之毒。 \n治崩中带下，产后血气胀痛，破症瘕，发斑痘（王海藏快斑散用之），化骨哽（能软坚）， \n杀三虫。 \n根似狗脊而大。汁能制三黄，化五金，伏钟乳、结砂、制汞，解毒软坚（以此浸水缸中 \n，日饮其水，能辟时疾）。",g:"清热药"},
  "赤小豆":{o:"赤小豆",c:"通，行水，散血。十剂作燥 \n甘酸（思邈∶咸冷）。色赤，心之谷也。性下行，通小肠，利小便（心与小肠相表里）， \n行水散血，消肿排脓，清热解毒。治泻痢香港脚（昔有患香港脚者，用袋盛赤小豆，朝夕践踏之， \n遂愈。同鲤鱼煮汁食，能消水肿，煮粥亦佳），敷一切疮疽（鸡子白调末箍之，性极粘，干 \n则难揭，入苎根末则不粘。宋仁宗患 腮，道士赞能，取赤小豆四十九粒咒之，杂他药敷之 \n而愈。中贵任承亮亲见，后任自患恶疮，付永投以药立愈。问之∶赤小豆也。承亮始悟道士 \n之咒伪也。后过豫章，见医治胁疽甚捷，任曰∶莫非赤小豆耶？医惊拜曰∶用此活三十余口， \n愿勿复宣），止渴解酒，通乳下胎。然渗津液，久服令人枯瘦（《十剂",g:"利水渗湿药"},
  "赤柽柳":{o:"赤柽柳",c:"\\x一名西河柳\\x \n宣，解毒 \n能使疹毒外出。末服四钱，治痧疹不出，喘嗽闷乱。沙糖调服，治疹后痢。",g:"清热药"},
  "赤石脂":{o:"赤石脂",c:"重，涩，固大小肠 \n甘而温，故益气生肌而调中。酸而涩，故收湿（《独行方》∶ 末，治小儿脐中汁出、 \n赤肿）止血而固下（《经疏》云∶大、小肠下后虚脱，非涩剂无以固之。其他涩药轻浮，不 \n能达下，惟赤石脂体重而涩，直入下焦阴分，故为久痢、泄癖要药。仲景桃花汤用之，加干 \n姜、粳米）。疗肠癖泄痢，崩带遗精，痈痔溃疡，收口长肉，催生下胞（《经疏》云∶能去恶 \n血，恶血化，则胞胎无阻。东垣云∶胞胎不出，涩剂可以下之。又云∶固肠、胃有收敛之能， \n下胎衣无推荡之峻）。细腻粘舌者良。赤入血分，白入气分（五色石脂入五脏）。研粉，水飞 \n用。恶芫花。畏大黄。",g:"收涩药"},
  "车前子":{o:"车前草",c:"通，行水，泻热，凉血 \n甘寒。凉血去热，止吐衄，消瘕瘀，明目通淋（凡利水之剂，多损于目。惟此能解肝与 \n小肠之热，湿热退而目清矣。雷 曰∶使叶，勿使茎、蕊）。 \n子，甘寒。清肺、肝风热，渗膀胱湿热，利小便而不走气，与茯苓同功，强阴益精，令 \n人有子（肾有二窍，车前子能利水窍而固精窍。精盛则有子，五子衍宗丸用之，枸杞、菟丝 \n各八两，五味、复盆各四两，车前二两，蜜丸。惯遗泄者，车前易莲子。时珍曰∶人服食， \n须佐他药，如六味丸之用泽泻可也，若单用则过泻）。治湿痹五淋，暑湿泻痢（欧阳文忠患 \n暴下，国医不能愈。夫人云∶市有药，三文一贴甚效。公不肯服，夫人杂他药进之，一服而 \n愈。问其方，乃车前子为",g:"利水渗湿药"},
  "轻粉":{o:"轻粉",c:"燥，劫痰涎，外用杀虫 \n辛冷（时珍曰∶燥有毒）。杀虫治疮，劫痰消积（能消涎积。十枣汤加大黄、牵牛、轻 \n粉，名三化神 散），善入经络，螈 药多用之。不可过服常用（时珍曰∶水银阴毒，用火 \n丹砂而出。再加盐、矾，炼为轻粉。轻扬燥烈，走而不守，今人用治杨梅毒疮。虽能劫风 \n痰湿热从牙龈出，邪郁暂解，然毒瓦斯窜入经络，筋骨血液耗亡，筋失所养，变为筋挛骨痛。 \n痈肿疳漏，遂成废痼，贻害无穷。上下齿龈，属手足阳明肠胃经。毒瓦斯循经上行，至齿龈薄 \n嫩之处而出）。土茯苓、黄连、黑铅、铁浆、陈酱能制其毒。",g:"驱虫药"},
  "辛夷":{o:"辛夷",c:"\\x即木笔花\\x \n宣散上焦风热 \n辛温轻浮。入肺、胃气分，能助胃中清阳上行，通于头脑。温中解肌，通九窍，利关节 \n。 \n主治鼻渊鼻塞（肺主鼻。胆移热于脑，则鼻多浊涕而渊，风寒客于脑则鼻塞。经曰∶脑 \n渗为涕。王冰曰∶胆液不澄，则为浊涕，如泉不已，故曰鼻渊），及头痛面 （音旱，黑斑。 \n可作面脂），目眩齿痛，九窍风热之病。然性走窜，气虚火盛者忌服（时珍曰∶肺 \n开窍于鼻，阳明胃脉环鼻上行。脑为元神之府，鼻为命门之窍。人之中气不足，清阳不升， \n则头为之倾，九窍为之不利。吾乡金正希先生尝语余曰∶人之记性，皆在脑中。小儿善忘者 \n，脑未满也；老人健忘者，脑渐空也。凡人外见一物，必有一形影留于脑中。",g:"解表药"},
  "远志":{o:"远志",c:"补心肾 \n苦泄热，温壮气，辛散郁。主手少阴（心），能通肾气上达于心。强志益智，补精壮阳， \n聪耳明目，利九窍，长肌肉，助筋骨。 \n治迷惑善忘，惊悸梦泄（能交心肾。时珍曰∶远志入足少阴肾经，非心经药也。强志 \n益精，故治健忘。盖精与志，皆藏于肾，肾精不足，则志气衰，不能上通于心，故健忘梦泄 \n也），肾积奔豚，一切痈疽（酒煎服。《经疏》曰∶痈疽皆属七情忧郁恼怒而得，远志辛能散 \n郁。昂按∶辛能散郁者多矣，何独远志？《三因》云∶盖亦补肾之力耳。缪希雍着《本草经 \n疏》）。 \n去心，甘草水浸一宿用。畏真珠、藜芦，得茯苓、龙骨良。",g:"安神药"},
  "连翘":{o:"连翘",c:"轻，宣，散结，泻火 \n微寒升浮。形似心（实以莲房有瓣），苦入心，故入手少阴，厥阴（心、心包）气分而 \n泻火，兼除手、足少阳（三焦、胆），手阳明经（大肠）气分湿热。散诸经血凝、气聚（营 \n气壅遏，卫气郁滞，遂成疮肿），利水通经，杀虫止痛，消肿排脓（皆结者散之。凡肿而痛 \n者为实邪，肿而不痛为虚邪，肿而赤者为结热，肿而不赤为留气停痰），为十二经疮家圣药 \n（经曰∶诸疮痛痒皆属心火）。",g:"清热药"},
  "逆流回澜水":{o:"逆流回澜水",c:"宣 \n性逆而倒上，中风、卒厥宣痰饮之药宜之。",g:"其他"},
  "通草":{o:"通草",c:"\\x古名通脱木\\x \n轻、通、利水、退热 \n色白气寒，体轻味淡。气寒则降，故入肺经，引热下行而利小便；味淡则升，故入胃经 \n，通气上达而下乳汁。治五淋水肿，目昏耳聋，鼻塞失音（淡通窍，寒降火，利肺气），退 \n热催生。",g:"利水渗湿药"},
  "郁李仁":{o:"郁李仁",c:"润燥，泻气，破血 \n辛苦而甘。入脾经气分。性降下气行水，破血润燥。 \n治水肿癃急，大肠气滞，关格不通。用酒能入胆，治悸、目张不眠（一妇因大恐而病， \n愈后目张不瞑。钱乙曰∶目系内连肝胆，恐则气结，胆横不下。郁李润能散结，随酒入胆， \n结去胆下，而目瞑矣）。然治标之剂，多服渗人津液。 \n去皮、尖，蜜浸研。",g:"泻下药"},
  "郁金":{o:"郁金",c:"宣，行气解郁，泻，泄血破瘀 \n辛苦气寒。纯阳之品，其性轻扬上行，入心及包络，兼入肺经。凉心热，散肝郁，下气 \n破血（行滞气，亦不损正气。破瘀血，亦能生新血）。 \n治吐衄尿血，妇人经脉逆行（经不下行，上为吐衄诸症。用郁金末，加韭汁、姜汁、童 \n便服，其血自清。痰中带血者，加竹沥），血气诸痛，产后败血攻心，癫狂失心（癫多喜笑， \n尚知畏惧，证属不足；狂多忿怒，人莫能制，证属有余。此病多因惊忧、瘀血塞于心窍所致 \n。郁金七两，白矾三两，米糊丸服，名白金丸。郁金入心散恶血，明矾化顽痰故也），痘毒 \n入心（郁金一两，甘草二钱半，煮干焙研末，冰片五分，每用一钱，加猪血五、七滴，新汲 \n水下。治斑痘始有白泡",g:"活血化瘀药"},
  "酒":{o:"酒",c:"宣，行药势 \n辛者能散，苦者能降，甘者居中而缓，浓者热而毒，淡者利小便。用为响导，可以通行 \n一身之表，引药至极高之分。热饮伤肺，温饮和中。少饮则和血行气，壮神御寒，遣兴消愁 \n，辟邪逐秽，暖水藏，行药势。过饮则伤神耗血（亦能乱血，故饮之身面俱赤），损胃灼精， \n动火生痰，发怒助欲（酒是色媒人），致生湿热诸病（过饮则相火昌炎，肺金受灼，致生痰 \n嗽。脾因火而困怠，胃因火而呕吐，心因火而昏狂，肝因火而善怒，胆因火而忘惧，肾因火 \n而精枯，以致吐血、消渴、劳伤、蛊膈、痈疽、失明，为害无穷。汪颖曰∶人知戒早饮，而 \n不知夜饮更甚。醉饱就床，热壅三焦，伤心损目，夜气收敛，酒以发之，乱其清明，劳其脾 \n",g:"理气药"},
  "酸枣仁":{o:"酸枣仁",c:"补而润，敛汗，宁心 \n甘酸而润（凡仁皆润）。专补肝胆。炒熟酸温而香，亦能醒脾（故归脾汤用之）。助阴气， \n坚筋骨，除烦止渴（敛阴生津），敛汗（《经疏》曰∶凡服固表药，而汗不止者，用枣仁炒研 \n，同生地、白芍、五味，麦冬、竹叶、龙眼肉煎服多效。汗为心液故也）宁心（心君易动， \n皆由胆怯所致。经曰∶凡十一官皆取决于胆也）。 \n疗胆虚不眠（温胆汤中或用之。肝虚则胆也虚，肝不藏魂，故不寐。血不归脾，卧亦不 \n安。《金匮》治虚劳烦不眠，用酸枣仁汤。枣仁二升，甘草一两炙，知母、茯苓、芎 各二 \n两，深师加生姜二两，此补肝之剂。经曰∶卧则血归于肝。苏颂曰∶一方加桂一两，二方枣 \n仁并生用，治不得眠，岂得以煮",g:"安神药"},
  "醋":{o:"醋",c:"\\x一名苦酒\\x \n散瘀，敛气，消痈肿 \n酸温。散瘀解毒，下气消食（食敛缩则消矣），开胃气（令人嗜食，《本草》未载），散 \n水气。治心腹血气痛（磨木香服），产后血晕（以火淬醋，使闻其气），症结痰癖，疸黄痈肿 \n（外科敷药多用之，取其敛壅热、散瘀解毒。昂按∶贝母性散而敛疮口，盖能散，所以能敛。 \n醋性酸收而散痈肿，盖消则内散，溃则外散，收处即是散处，两者一义也）口舌生疮（含漱）， \n损伤积血（面和，涂能散之），谷、鱼、肉、菜、蕈、诸虫毒。多食伤筋（收缩太过。酒、 \n醋无所不入，故制药多用之）。米造、陈久者良（寇宗 曰∶食酸则齿软者，齿属肾，酸属 \n肝，木气强水气弱故也）。",g:"清热药"},
  "金":{o:"金",c:"重，镇心肝，定郁悸 \n辛平有毒（生金屑，服之杀人。昂按∶金性至刚重坠，与血肉之体不相宜，故服之致死 \n，非其性有毒也。人被金银灼者，并不溃烂，无毒可知矣。精金粹玉，世之宝器，岂有毒瓦斯 \n哉？）。金制木，重镇怯，故镇心肝，安魂魄（虽云重坠，亦借其宝气也。古方有红雪、紫 \n雪，皆并金银煮汁，亦假其气耳）。治惊痫风热，肝胆之病（肝经风热，则为惊痫失志，魂 \n魄飞扬。肝属木而畏金，与心为子母之脏，故其病同源一治）。丸散用箔为衣，煎剂加入药 \n煮。畏铅、水银（遇铅则碎，五金皆畏水银）。",g:"其他"},
  "金樱子":{o:"金樱子",c:"涩精，固肠 \n酸涩。入脾、肺、肾三经。固精秘气。 \n治梦泄遗精（和芡实为丸，名水陆丹），泄痢便数（丹溪曰∶经络隧道，以通畅为平和， \n而昧者以涩性为快，熬膏食之，自作不靖，咎将谁执李时珍曰∶无故而食，以恣欲则不可。 \n若精气不固者，服之何害）。 \n似榴而小，黄赤有刺。取半黄，（熟则纯甘）去刺核用。熬膏亦良（《笔谈》云∶熬膏则 \n甘，全失涩味）。",g:"收涩药"},
  "金银花":{o:"金银花",c:"泻热，解毒 \n甘寒入肺。散热解毒（清热即是解毒），补虚（凡物甘者皆补）疗风，养血止渴（丹溪 \n曰∶痈疽安后发渴，黄 六一汤吞忍冬丸切当。忍冬养血，黄 补气，渴何由作）。 \n治痈疽疥癣，杨梅恶疮，肠 血痢，五种尸疰。 \n经冬不凋，名忍冬（又名左缠藤）。花叶同功，花香尤佳，酿酒代茶。熬膏并妙（忍冬 \n酒，治痈疽发背一切恶毒，初起便服奇效。干者亦可，惟不及生者力速。忍冬五两，甘草二 \n两，水二碗、煎至一碗，再入酒一碗略煎，分三服，一日一夜吃尽。重者日二剂，服至大、 \n小肠通利，则药力到。忍冬丸，照前分两，酒煮晒干，同甘草为末，以所煮余酒打糊为丸。 \n陈藏器曰∶热毒血痢，浓煎服之。为末，糖调常服，能稀",g:"清热药"},
  "钟乳":{o:"钟乳",c:"补阳 \n甘温。阳明（胃）气分药。木石之精。强阴益阳，通百节，利九窍，补虚劳，下乳汁。 \n服之令人阳气暴充，饮食倍进，形体壮盛。然其性 悍，须命门真火衰者可偶用之。若借以 \n恣欲，多服、久服，不免淋浊痈疽之患。出洞穴中，石液凝成，下垂如冰柱。通中轻薄、如 \n鹅翎管、碎之如爪甲光明者真。炼合各如本方，蛇床为使。恶牡丹、紫石英。忌参、术、羊 \n肉、葱、蒜、胡荽。",g:"其他"},
  "钩藤":{o:"钓藤钩",c:"宣，除风热，定惊 \n甘微苦寒。除心热，平肝风。 \n治大人头旋目眩，小儿惊啼螈 （音炽纵。筋急而缩为螈，筋缓而弛为 ，伸缩不已为 \n螈，俗谓之搐搦是也），客忤胎风，发斑疹。主肝风相火之病，风静火息，则诸证自除（相 \n火散行于胆、三焦、心包）。 \n有刺，类钓钩。藤细多钩者良（纯用钩，其功加倍）。久煎则无力。",g:"平肝息风药"},
  "铁":{o:"铁",c:"重，坠痰，镇惊 \n辛平重坠。镇心平肝，定惊疗狂，消痈解毒。诸药多忌之（李时珍曰∶补肾药尤忌之）。 \n畏磁石、皂荚（皂荚木作薪，则斧裂）。 \n时，砧上打落者名铁落（《素问》用治怒狂），如尘飞起者名铁精，器物生衣者名铁锈 \n，盐、醋浸出者名铁华（李时珍曰∶大抵借金气以平木、坠下解毒，无他义也）。 \n针砂消水肿黄胆，散瘿瘤，乌髭发（乌须方多用之）。",g:"清热药"},
  "铅":{o:"铅",c:"重，坠痰，解毒 \n甘寒属肾。禀壬癸之气，水中之金，金丹之母，八石之祖（丹灶家必用之）。安神解毒， \n坠痰杀虫，乌须（制为梳，以梳须）明目。 \n铅丹（即黄丹，用黑铅加硝、黄、盐、矾炼成）咸寒沉重，味兼盐、矾。内用坠痰去怯， \n消积杀虫，治惊疳疟痢。外用解热拔毒，去瘀长肉，熬膏必用之药（用水漂去盐硝砂石，微 \n火炒紫色，摊地上，去火毒用）。 \n铅粉主治略同（亦名胡粉锡粉。李时珍曰∶铅粉亦可代铅丹熬膏，然未经盐矾火 。又 \n有豆粉、蛤粉杂之，只入气分，不能入血分也）。",g:"清热药"},
  "铜绿":{o:"铜绿",c:"\\x即铜青\\x \n宣，去风痰 \n酸平微毒。治风烂泪眼，恶疮疳疮，妇人血气心痛，吐风痰，合金疮，止血杀虫（治皆 \n肝胆之病，亦金胜木之义）。用醋制，铜刮用。",g:"驱虫药"},
  "银":{o:"银",c:"功用略同。",g:"其他"},
  "锁阳":{o:"锁阳",c:"补阳，滑肠 \n甘温补阴。益精兴阳，润燥养筋（强筋故能兴阳）。治痿弱，滑大便（便燥者啖之，可 \n代苁蓉，煮粥弥佳）。 \n鳞甲栉比，状类男阳。酥炙。",g:"补虚药"},
  "防己":{o:"防己",c:"通，行水，泻下焦血分湿热 \n大苦大寒（《本经》）平，《别录》温）。太阳（膀胱）经药。能行十二经，通腠理，利九 \n窍，泻下焦血分湿热，为疗风水之要药。 \n治肺气喘嗽（水湿），热气诸痫（降气下痰），湿症香港脚（足伤寒湿为香港脚。寒湿郁而为 \n热，湿则肿，热则痛。防己为主药。湿加苡仁、苍术、木瓜、木通，热加芩、柏，风加羌活、 \n萆，痰加竹沥、南星，痛加香附、木香，活血加四物，大便秘加桃仁、红花，小便秘加牛 \n膝、泽泻，痛连臂加桂枝、威灵仙，痛连胁加胆草。又有足跟痛者，属肾虚。不与香港脚同论 \n），水肿风肿，痈肿恶疮。或湿热流入十二经，致二阴不通者，非此不可。然性险而健，阴 \n虚及湿热在上焦气分者禁用",g:"祛风湿药"},
  "防风":{o:"防风",c:"宣，发表，胜湿 \n辛苦性温，升浮为阳。搜肝泻肺，散头目滞气、经络留湿。 \n主上部见血（用之为使，亦能治崩），上焦风邪，头痛目眩，脊痛项强，周身尽痛，太 \n阳（膀胱）经证（徐之才曰∶得葱白，能行周身）。又行脾胃二经，为去风胜湿之要药（凡 \n风药皆能胜湿。东垣曰∶卒伍卑贱之职，随所引而止，乃风药中润剂。若补脾胃，非此引用 \n不能行），散目赤、疮疡。若血虚痉急、头痛不因风寒（内伤头痛）、泄泻不因寒湿、火升发 \n嗽、阴虚盗汗、阳虚自汗者并禁用（同黄 、芍药，又能实表止汗；合黄 、白术，名玉屏 \n风散，固表圣药。黄 得防风而功益大，取其相畏而相使也）。 \n黄润者良。上部用身，下部用梢。畏萆 。恶干姜、白",g:"解表药"},
  "阳起石":{o:"阳起石",c:"重，补肾命 \n咸温。补右肾命门。治阴痿精乏，子宫虚冷，腰膝冷痹，水肿症瘕（寇宗 曰∶凡石药 \n冷热皆有毒，宜酌用。按∶经曰，石药发癫，芳草发狂。芳草之气美，石药之气悍。二者相 \n遇，恐内伤脾）。出齐州阳起山，云母根也。虽大雪遍境，此山独无。以云头、雨脚鹭鸶毛 \n、色白滋润者良（真者难得）。火 、醋淬七次，研粉，水飞用。亦有用烧酒、樟脑升炼取 \n粉者。桑螵蛸为使。恶泽泻、菌桂。畏菟丝子。忌羊血。",g:"补虚药"},
  "阴阳水":{o:"阴阳水",c:"\\x一名生熟水\\x \n宣、和阴阳 \n治霍乱吐泻有神功（阴阳不和而交争，故上吐下泻。而霍乱饮此辄定者，分其阴阳，使 \n和平也。按∶霍乱有寒、热二证，药中能治此者甚多，然未尝分别言之。仓卒患此，脉候未 \n审，慎勿轻投偏热、寒之剂。曾见有霍乱服姜汤而立毙者，唯饮阴阳水为最稳。霍乱邪在上 \n焦则吐，邪在下焦则泻，邪在中焦则吐泻兼作，此湿霍乱，症轻易治。又有心腹绞痛、不得 \n吐泻者，名干霍乱，俗名绞肠痧，其死甚速。古方用盐熬热，童便调饮，极为得治。勿与谷 \n食，即米汤下咽亦死）。以沸汤半钟，井水半钟和服。",g:"其他"},
  "阿胶":{o:"阿胶",c:"平补而润 \n甘平。清肺养肝，滋肾益气（肺主气，肾纳气），和血补阴（肝主血，血属阴），除风化 \n痰，润燥定喘，利大、小肠。治虚劳咳嗽，肺痿吐脓，吐血衄血，血淋血痔，肠风下痢（伤 \n暑伏热成痢者，必用之。妊娠血痢尤宜），腰酸骨痛，血痛血枯，经水不调，崩带胎动（或 \n妊娠下血，酒煎服）。痈疽、肿毒及一切风病、泻者忌用（大抵补血与液，为肺、大肠要药。 \n寇宗 曰∶驴皮煎胶，取其发散皮肤之外。用乌者，取其属水以制热则生风之义，故又治风 \n也。陈自明曰∶补虚用牛皮胶，去风用驴皮胶。杨士瀛曰∶小儿惊风后，瞳人不正者，以阿 \n胶倍人参服，最良。阿胶育神，人参益气也。按∶阿井乃济水伏流，其性趋下，用搅浊水则 \n",g:"补虚药"},
  "阿魏":{o:"阿魏",c:"泻，消积，杀虫 \n辛平（一日温）。入脾胃。消肉积，杀细虫，去臭气（谚曰∶黄芩无假，阿魏无真。刘 \n纯曰∶阿魏无真却有真，臭而止臭是为珍），解蕈菜，自死牛马肉毒。治心腹冷痛、疟痢（疟 \n痢多由积滞而起），传尸、疳劳疰虫。出西番。木脂熬成，极臭。试取少许，安铜器一宿， \n沾处白如银，汞者真（人多以胡蒜白赝之）。用钵研细，热酒器上熏过入药。",g:"驱虫药"},
  "附子":{o:"附子",c:"大燥，回阳，补肾命火，逐风寒湿 \n辛甘有毒，大热纯阳。其性浮而不沉，其用走而不守，通行十二经，无所不至。能引补 \n气药以复散之元阳，引补血药以滋不足之真阴，引发散药开腠理，以逐在表之风寒（同干姜 \n、桂枝，温经散寒发汗），引温暖药达下焦，以祛在里之寒湿（能引火下行，亦有津调贴足 \n心者。入八味丸内，亦从地黄等补阴）。 \n治三阴伤寒（吴绶曰∶附子阴证要药。凡伤寒传变三阴，中寒夹阴，身虽大热，而脉沉 \n细者；或厥阴腹痛，甚则唇青、囊缩者，急须用之。若待阴极阳竭而用之，已迟矣。东垣治 \n阴盛格阳，伤寒面赤目赤，烦渴引饮，脉七八至。但按之则散，用姜附汤加人参，投半斤， \n得汗而愈，此神圣之妙也），中寒",g:"温里药"},
  "陈皮":{o:"陈皮",c:"能燥能宣，有补有泻，可升可降 \n辛能散，苦能燥、能泻，温能补、能和。同补药则补，泻药则泻，升药则升，降药则降 \n。为脾、肺气分之药（脾为气母，肺为气龠。凡补药涩药，必佐陈皮以利气）。调中快膈， \n导滞消痰（大法治痰，以健脾顺气为主。洁古曰∶陈皮、枳壳利其气，而痰自下），利水破 \n症，宣通五脏，统治百病，皆取其理气燥湿之功（人身以气为主，气顺湿除，则百病散。《金 \n匮》云∶能解鱼毒、食毒）。多服久服，损人元气。入补养药则留白，入下气消痰药则去白 \n（《圣济》云∶不去白，反生痰）。 \n去白名橘红，兼能除寒发表（皮能发散皮肤）。核治疝痛。叶散乳痈（皆能入厥阴，行 \n肝气，消肿散毒。腰肾冷痛，橘核炒酒",g:"理气药"},
  "降真香":{o:"降真香",c:"\\x焚之能降诸真，故名\\x \n宣，辟恶、止血、生肌 \n辛温。辟恶气怪异，疗伤折金疮，止血定痛，消肿生肌（周崇逐寇被伤，血出不止，敷 \n花芯石散，不效。军士李高，用紫金藤散敷之，血止痛定，明日结痂无瘢，曾救万人。紫金 \n藤，即降真香之最佳者也）。",g:"其他"},
  "雄黄":{o:"雄黄",c:"重，解毒，杀虫 \n辛温有毒。得正阳之气，入肝经气分。搜肝强脾，散百节大风，杀百毒，辟鬼魅。治惊 \n痫痰涎，头痛眩晕，暑疟 痢，泄泻积聚（虞雍公道中冒暑，泄痢连月，梦至仙居，延之坐 \n。壁中有词云∶暑毒在脾，湿气连脚，不泄则痢，不痢则疟。独炼雄黄，蒸饼和药，甘草作 \n汤，食之安乐。别作治疗，医家大错。如方服之遂愈）。又能化血为水，燥湿杀虫，治劳疳 \n疮疥蛇伤。赤似鸡冠，明彻不臭，重三五两者良。醋浸，入莱菔汁煮，干用。生山阴者名雌 \n黄，功用略同。劣者名熏黄，烧之则臭，只堪熏疮疥，杀虫虱。",g:"清热药"},
  "雷丸":{o:"雷丸",c:"泻，消积，杀虫 \n苦寒有小毒。入胃、大肠经。功专消积杀虫（杨 得异疾，每发语，腹中有小声应之， \n久渐声大。有道士曰∶此应声虫也，但读本草，取不应者治之。读至雷丸，不应，服之而愈 \n）。竹之余气，得霹雳而生，故名。大小如栗，竹刀刮去黑皮。甘草水浸一宿，酒拌蒸，或 \n炮用。浓朴、芫花为使。恶葛根。",g:"驱虫药"},
  "露水":{o:"露水",c:"润肺 \n甘平。止消渴，宜煎润肺之药。秋露造酒最清冽，百花上露，令人好颜色（霜杀物，露 \n滋物，性随时异也。露能解暑，故白露降则处暑矣。疟必由于暑，故治疟药，露一宿服）。",g:"其他"},
  "露蜂房":{o:"露蜂房",c:"宣，解毒，杀虫 \n甘平有毒。治惊痫螈 ，附骨痈疽，根在脏腑（和蛇蜕、乱发、烧灰酒服。按∶附骨疽 \n不破，附骨成脓，故名。不知者，误作贼风治。附骨疽痛处发热，四体乍热乍寒，小便赤， \n大便秘而无汗，泻热发散则消。贼风痛处不热，亦不发寒热，觉身冷，欲得热熨则小宽，时 \n有汗，宜风药治之），涂瘰 成 （音漏。炙研，猪脂和涂），止风、虫牙痛（煎水含嗽。时 \n珍曰∶阳明药也，取其以毒攻毒，兼杀虫之功耳），敷小儿重舌（烧灰酒和敷舌下，日数次）， \n起阴痿（烧灰敷阴上）。取悬于树、受风露者，炙用（治痈肿，醋调涂。洗疮，煎用）。",g:"清热药"},
  "青皮":{o:"青皮",c:"泻肝，破气，散积 \n辛苦而温，色青气烈。入肝胆气分。疏肝泻肺（柴胡疏上焦肝气，青皮平下焦肝气。凡 \n泻气药，皆云泻肺），破滞削坚，除痰消痞。治肝气郁积，胁痛多怒，久疟结癖（入肝散邪， \n入脾除痰，疟家必用之品，故清脾饮以之为君），疟痛乳肿（丹溪曰∶乳房属阳阴，乳头属 \n厥阴。乳母或因忿怒郁闷，浓味酿积，致厥阴之气不行，故窍不得出。阳明之血腾沸，故热 \n甚而化脓。亦因其子有滞痰膈热，含乳而睡，嘘气致生结核者，初起便须忍痛揉软，吮令汁 \n透，自可消散。治法以青皮疏肝滞，石膏清胃热，甘草节行浊血，瓜蒌消肿导毒。或加没药、 \n橘叶、金银花、蒲公英、皂角刺、当归，佐以少酒，若于肿处灸三五壮尤捷。久则凹陷",g:"理气药"},
  "青盐":{o:"青盐",c:"\\x即戎盐\\x \n补肾，泻血热 \n甘咸而寒。入肾经，助水脏，平血热。治目痛赤涩，吐血溺血，齿舌出血，坚骨固齿（ \n擦牙良），明目乌须。余同食盐，出西羌。不假煎炼，方棱明莹色青者良。",g:"其他"},
  "青葙子":{o:"青葙子",c:"\\x一名草决明\\x \n泻肝，明目 \n味苦微寒。入厥阴（肝）。祛风热，镇肝明目。治青盲障翳，虫疥恶疮。瞳子散大者忌 \n服（能助相火）。 \n类鸡冠而穗尖长。",g:"清热药"},
  "青蒿":{o:"青蒿",c:"泻热，补劳 \n苦寒。得春木少阳之令最早（二月生苗），故入少阳、厥阴（肝胆）血分。 \n治骨蒸劳热（童便捣汁，取汁熬膏），蓐劳虚热（凡苦寒之药，多伤胃气。惟青蒿芳香 \n入脾，独宜于血虚有热之人，以其不犯胃气也），风毒热黄，久疟久痢，瘙疥恶疮，鬼气尸 \n疰（时珍曰∶《月令通纂》言伏内庚日，采蒿悬门庭，可辟邪。冬至元旦，各服一钱亦良， \n则青蒿之治鬼疰，盖亦有所伏也），补中明目。 \n童便浸叶用，熬膏亦良。使子勿使叶，使根勿使茎。",g:"清热药"},
  "青鱼胆":{o:"青鱼胆",c:"泻热，治目疾 \n苦寒色青。入肝胆。治目疾，点眼消赤肿障翳，咽津吐喉痹痰涎，涂火热疮，疗鱼骨哽 \n。腊月收，阴干。",g:"其他"},
  "青黛":{o:"青黛",c:"泻肝，散郁火 \n咸寒，色青泻肝。散五脏郁火，解中、下焦蓄蕴风热（《衍义》曰∶一妇患脐、腹、二 \n阴遍生湿疮，热痒而痛，出黄汁，二便涩。用鳗鲡、松脂、黄丹之类涂之，热痛愈甚。其妇 \n嗜酒，喜食鱼、虾发风之物。乃用马齿苋四两研烂，入青黛一两和涂，热痛皆去，仍服八正 \n散而愈。此中、下焦蓄蕴风热。毒瓦斯若不出，当作肠风、内痔。妇不能禁酒物，果仍发痔） \n。 \n治伤寒发斑，吐咯血痢（阴虚火炎者忌用。合杏仁研，置柿饼中煨食，名圣饼子，治咯 \n血）。小儿惊痫，疳热丹热，敷痈疮、蛇犬毒。 \n即靛花。取娇碧者，水飞净用（内多锻石，故须淘净）。",g:"其他"},
  "韭":{o:"韭",c:"补阳，散瘀 \n辛温微酸。肝之菜也，入血分而行气。归心益胃，助肾补阳（一名土钟乳，言温补也）， \n除胃热，充肺气，散瘀血，逐停痰。治吐衄损伤，一切血病（捣汁童便和服），噎膈反胃（能 \n消瘀血停痰在胃口，治反胃及胃脘痛。丹溪曰∶有食热物及郁怒，致死血留胃口作痛者，宜 \n加韭汁、桔梗入药，开提气血；有肾气上攻，致心痛者，宜韭汁和五苓散为丸，空心茴香汤 \n下。治反胃宜用牛乳加韭汁、姜汁，细细温服。盖韭汁散瘀，姜汁下气消痰和胃，牛乳解热 \n润燥补虚也。《单方总录》曰∶食不得入，是有火也；食久反出，是无火也。治法虽有寒、 \n热、虚、实之别，要以安其胃气为本。使阴阳升降平均，呕逆自顺而愈矣），解药毒，食毒 ",g:"理气药"},
  "预知子":{o:"预知子",c:"补劳，泻热 \n苦寒。补五劳七伤。 \n治 癖气块，天行温疾，蛇虫咬毒。杀虫疗蛊（缀衣领中，凡遇蛊毒，则闻其声而预知 \n之，故名），利便催生。 \n藤生，子如皂角，褐色光润。出蜀中，云亦难得。",g:"驱虫药"},
  "食盐":{o:"食盐",c:"泻热，润燥，补心，通二便，宣，引吐 \n咸甘辛寒。咸润下，故通大、小便；咸走血而寒胜热，故治目赤痈肿，血热热疾；咸补 \n心，故治心虚（以水制火，取既济之义，故补心药用盐炒。一人病笑不休，用盐 赤煎沸， \n饮之而瘳。经曰∶神有余则笑不休。神，心火也。用盐，水制火也。一妇病此半年，张子和 \n亦用此法而愈）；咸入肾而主骨（故补肾药用盐汤下），故坚肌骨，治骨病齿痛（擦牙亦佳， \n清火固齿。齿缝出血，夜以盐浓敷龈上，沥涎尽乃卧。或问咸能软坚，何以坚肌骨，不知骨 \n消筋缓，皆因湿热，热淫于内，治以咸寒，譬如生肉易溃，得盐性咸寒，则能坚久不坏也）； \n咸润燥而辛泄肺（煎盐用皂角收，故味微辛）故治痰饮喘逆（《本",g:"清热药"},
  "香薷":{o:"香薷",c:"宣，通，利湿，清暑 \n辛散皮肤之蒸，温解心腹之凝结。属金、水而主肺，为清暑之主药。肺气清，则小便行 \n而热降（暑必兼湿，治暑必兼利湿，若无湿，但为干热，非暑也）。 \n治呕逆水肿（熬膏服，小便利则消）、香港脚口气（煎汤含敷）。单服治霍乱转筋（时珍曰∶ \n暑月乘凉饮冷，致阳气为阴邪所遏，反中入内，遂病头痛，发热恶寒，烦躁口渴，吐泻霍乱 \n，宜用之，以发越阳气、散暑和脾则愈。若饮食不节、劳役作伤之人，伤暑大热大渴，汗出 \n如雨，烦躁喘促，或泻或吐者，乃内伤之证。宜用清暑益气汤、人参白虎汤之类，以泻火益 \n元可也。若用香薷，是重虚其表，而济之热矣。盖香薷乃夏月解表之药，如冬月之用麻黄， \n气虚者尤不宜",g:"解表药"},
  "香附":{o:"香附",c:"\\x一名莎草根\\x \n宣，调气开郁 \n性平气香，味辛能散，微苦能降，微甘能和。乃血中气药，通行十二经。八脉气分，主 \n一切气（人身以气为主，气盛则强，虚则衰，顺则平，逆则病，绝则死矣。经曰∶怒则气上 \n，恐则气下，喜则气缓，悲则气消，惊则气乱，思则气结，劳则气耗，此七情之气也。以香 \n附为君，随证而加升降消补之药。《素问》中仍有寒则气收，热则气泄，名九气）。利三焦 \n，解六郁（痰郁、火郁、气郁、血郁、湿郁、食郁），止诸痛（通则不痛）。 \n治多怒多忧，痰饮痞满，胸肿腹胀，饮食积聚，霍乱吐泻，肾气香港脚，痈疽疮疡（血凝 \n气滞所致。香附一味末服，名独胜丸，治痈疽由郁怒得者。如疮初作，以此代茶。溃后",g:"理气药"},
  "马兜铃":{o:"马兜铃",c:"泻肺，下气 \n体轻而虚。熟则四开象肺，故入肺。寒能清肺热。苦辛能降肺气（时珍曰∶钱乙补肺阿 \n胶散用之，非取其补肺，取其清热降气，则肺自安也。其中阿胶糯米，乃补肺之正药。昂按 \n∶清热降气，泻之即所以补之，若专一于补，适以助火而益嗽也）。 \n治痰嗽喘促，血痔 疮，大肠经热（ ，漏也，音闾，亦音漏。痔属大肠，大肠与肺为 \n表里。肺移热于大肠，故肠风痔 ，清脏热则腑热亦清矣。《千金》单服治水肿，以能泻肺 \n行水也），亦可吐蛊（汤剂中用之，多作吐）。 \n蔓生，实如铃，去筋膜，取子用。",g:"清热药"},
  "马勃":{o:"马勃",c:"轻，解热，外用敷疮 \n辛平轻虚。清肺解热（东垣普济消毒饮中用之），散血止嗽。 \n治喉痹咽痛（吹喉中良，或加白矾，或硝扫喉，取吐痰愈），鼻衄失音，外用敷诸疮良。 \n生湿地朽木上。状如肺肝，紫色虚软，弹之粉出，取粉用。",g:"其他"},
  "马蔺子":{o:"马蔺子",c:"\\x一名蠡实\\x \n泻湿热，解毒 \n甘平。 \n治寒疝喉痹，痈肿疮疖，妇人血气烦闷，血运崩带。利大、小肠。久服令人泻。 \n丛生，叶似薤而长浓，结角子如麻大，赤色有棱。炒用。治疝用醋拌。根、叶同功。",g:"清热药"},
  "马鞭草":{o:"马鞭草",c:"泻，破血，消胀，杀虫 \n味苦微寒。破血通经，杀虫消胀。 \n治气血症瘕，痈疮阴肿（捣汁涂敷）。 \n墟陌甚多。方茎，叶似益母对生，夏、秋开细紫花，穗如车前草，类蓬蒿而细，根白而 \n小。 \n用苗、叶。",g:"活血化瘀药"},
  "马齿苋":{o:"马齿苋",c:"\\x一名九头狮子草\\x \n泻热，散血 \n酸寒。散血解毒，祛风杀虫。治诸淋疳痢（《海上方》∶捣汁，和鸡子白服，治赤白痢） \n，血癖恶疮（多年恶疮，敷两三遍即瘥。烧灰煎膏，涂秃疮湿癣），小儿丹毒（捣汁饮，以 \n滓涂之），利肠滑产。叶如马齿，有大、小二种，小者入药。性至难燥，去茎用（亦忌鱼、 \n鳖同食）。",g:"清热药"},
  "驴溺":{o:"驴溺",c:"泻，杀虫 \n辛寒。杀虫，治反胃噎膈（须热饮之。张文仲《备急方》曰∶昔患反胃，奉敕调治，竟 \n不能疗。一卫士云∶服驴屎极验。遂服二合，只吐一半，再服二合，食粥便定。宫中患反胃 \n者五六人，同服之俱瘥）。",g:"驱虫药"},
  "骨碎补":{o:"骨碎补",c:"补肾，治折伤 \n苦温补肾，故治耳鸣（耳鸣必由肾虚），及肾虚久泻（研末，入猪肾煨熟，空心食之。 \n肾主二便，久泻多属肾虚，不可专责脾胃也）。肾主骨，故治折伤（以功命名，粥和敷伤处。 \n经曰∶肾者胃之关也。前阴利水，后阴利谷），牙痛（炒黑为末，擦牙，咽下亦良）。又入厥 \n阴（心包，肝），能破血止血（入血行伤，故治折伤，粥和末裹伤处）。 \n根似姜而扁长，去毛用，或蜜拌蒸。",g:"活血化瘀药"},
  "高良姜":{o:"高良姜",c:"宣，燥，暖胃散寒 \n辛热。暖胃散寒，消食醒酒。 \n治胃脘冷痛（凡心口一点痛，俗言心气痛，非也。乃胃脘有滞或有虫，及因怒、因寒而 \n起。以良姜酒洗七次，香附醋洗七次，焙研。因寒者，姜二钱，附一钱；因怒者，附二钱， \n姜一钱；寒怒兼者，每钱半，米饮加姜汁一匙，盐少许服。初梁绲患心脾痛，梦神授此方， \n二味等分服，后入各炒方用），霍乱泻痢，吐恶噎膈，瘴疟冷癖。肺胃热者忌之。 \n出岭南高州。 \n子，名红豆蔻，温肺散寒，醒脾燥湿，消食解酒（东垣脾胃药中常用之）。并东壁土炒 \n用。",g:"温里药"},
  "鲤鱼":{o:"鲤鱼",c:"通，行水 \n甘平。下水气，利小便。治咳逆上气，香港脚黄胆，妊娠水肿（古方治水肿，有鲤鱼汤、 \n鲤鱼粥。刘河间曰∶鲤之治水，鸭之利水，所谓因其气相感也）。 \n鲤鱼骨烧灰，疗鱼骨哽。",g:"利水渗湿药"},
  "鲫鱼":{o:"鲫鱼",c:"补土和胃 \n甘温。诸鱼属火，独鲫属土。土能制水，故有和胃、实肠、行水之功（作 食，治香港脚 \n及上气）。忌麦冬、芥菜、沙糖、猪肝。",g:"其他"},
  "鳖甲":{o:"鳖甲",c:"补阴，退热 \n咸平属阴，色青入肝。治劳瘦骨蒸，往来寒热，温疟疟母（疟必暑邪。类多阴虚之人， \n疟久不愈，元气虚羸，邪陷中焦，则结为疟母。鳖甲能益阴、除热而散结，故为治疟要药） \n，腰痛胁坚，血瘕痔核（咸能软坚），经阻产难，肠痈疮肿，惊痫斑痘，厥阴血分之病（时 \n珍曰∶介虫阴类，故皆补阴。或曰∶木物属金与土，故入脾、肺而治诸症）。色绿九肋。重 \n七两者为上。醋炙。若治劳，童便炙，亦可熬膏。 \n鳖肉凉血补阴，亦治疟痢（煮作羹食，加生姜、沙糖，不用盐、酱，名鳖糖汤）。恶矾 \n石。忌苋菜、鸡子（鳖色青，故走肝、益肾而退热；龟色黑，故通心、入肾而滋阴。阴性虽 \n同，所用略别）。 \n鳖胆味辣，可代椒解腥。",g:"补虚药"},
  "鳗鲡":{o:"鳗鲡",c:"补虚，杀虫 \n甘平。去风杀虫（按∶虫由风生，故风字从虫）。治骨蒸劳瘵，湿痹风瘙，阴户蚀痒（皆 \n有虫。张鼎云∶其骨烧烟，蚊化为水，熏竹木，辟蛀虫；置衣箱，辟诸蠹），补虚损（有病 \n瘵者，相染已死数人。乃取病者钉之棺中，弃于流水，永绝传染。渔人异之，开视，见一女 \n子尚活。取置渔舍，多食鳗鲡，病愈，遂以为妻。《圣惠方》∶鳗鲡淡炙食，治诸虫，心痛多 \n吐，冷气上攻满闷）。",g:"驱虫药"},
  "鳝鱼":{o:"鳝鱼",c:"宣，去风 \n甘温。补五脏，除风湿。 \n尾血，疗口眼 斜（少和麝香，左 涂右，右 涂左，正即洗去。《千金》云∶鳖血、 \n鸡冠血和伏龙肝，并治口 ），滴耳治耳痛，滴鼻治鼻衄，点目治痘后生翳（时珍曰∶鳝善 \n穿穴，与蛇同性。故能走经络，疗风邪及诸窍之病。风中血脉，用血主之，从其类也）。",g:"其他"},
  "鳢鱼胆":{o:"鳢鱼胆",c:"泻热 \n凡胆皆苦，惟鳢鱼胆甘（昂按∶味终带苦）。喉痹将死者，点入即瘥，病深者水调灌之。 \n俗名乌鱼，即七星鱼（首有七星，夜朝北斗，道家谓之水厌。雁为天厌，犬为地厌。《卫生 \n》歌云∶雁行有序犬有义，黑鱼拱北知臣礼，人无礼义反食之，天地鬼神皆不喜。杨拱《医 \n方摘要》云∶除夕黄昏时，取大黑鳢鱼一尾，小者二三尾，煮汤浴儿，遍身七窃俱到，能免 \n出痘。不可嫌腥，而以清水洗去也。如不信，留一手或一足不洗，遇出痘时，不洗处痘必多 \n。此乃异人所传，不可轻易。《食医心镜》∶鳢鱼一斤以上，和冬瓜、葱白作羹，治十种水 \n气）。",g:"其他"},
  "鸡":{o:"鸡",c:"补 \n属巽属木（故动风）。其肉甘温，补虚温中（日华曰∶黑雌鸡补产后虚劳。马益卿曰∶ \n妊妇宜食牡鸡，取阳精之全于天也。崔行功曰∶妇人产死，多是富贵扰攘，致产妇惊乱故耳。 \n屏人静产，更烂煮牡鸡汁作粳米粥与食，自然无恙。鸡汁性滑而濡，不食其肉，恐难化 \n也。 \n俗家每产后即食鸡啖卵，壮者幸无事，弱者因而致疾矣。龚云林曰∶四五年老母鸡，取 \n汤煮粥食，能固胎）。 \n鸡冠居清高之分，其血乃精华所聚，雄而丹者属阳。故治中恶惊忤（以热血 口、涂面 \n、吹鼻良）；本乎天者亲上，故涂口眼 斜。用老者取其阳气充足也。能食百虫，故治蜈蚣 \n、蚯蚓、蜘蛛咬毒。 \n鸡子甘平。镇心，安五脏，益气补血，清咽开音，散热定",g:"补虚药"},
  "鸡苏":{o:"鸡苏",c:"\\x一名水苏，一名龙脑薄荷\\x \n轻，宣，散热，理血 \n辛而微温。清肺下气理血，辟恶而消谷。 \n治头风目眩，肺痿血痢，吐衄崩淋，喉腥口臭，邪热诸病（《局方》有龙脑鸡苏丸）。 \n方茎中虚，似苏叶而微长，密齿面皱，气甚辛烈。",g:"其他"},
  "鸭":{o:"鸭",c:"补阴 \n甘冷。入肺、肾血分，滋阴补虚，除蒸止嗽，利水道，治热痢。白毛乌骨者，为虚劳圣 \n药，取金肃水寒之象也（葛可久有白凤膏）。老者良。酒或童便煮。热血解金、银、丹石、 \n砒霜诸毒及中恶、溺死者。 \n卵甘咸微寒。能滋阴，除心腹膈热。盐藏，食良。",g:"补虚药"},
  "鹤虱":{o:"鹤虱",c:"泻，杀虫 \n苦辛，有小毒。杀五脏虫，治蛔啮腹痛（面白唇红，时发时止者，为虫痛，肥肉汁调末 \n服）。 \n《沈存中笔记》云∶是杜牛膝子（或曰非也，别是一种）。最黏人衣。有狐气，炒热则香。",g:"驱虫药"},
  "鹿茸":{o:"鹿茸",c:"大补阳虚 \n甘温（一云咸热）纯阳。生精补髓，养血助阳，强筋健骨。治腰肾虚冷（《百一方》∶鹿 \n角屑熬黄为末，酒服，主腰脊虚冷刺痛），四肢酸痛，头眩眼黑，崩带遗精，一切虚损劳伤 \n。惟脉沉细、相火衰者宜之。鹿角初生，长二三寸，分歧如鞍，红如玛瑙。破之如朽木者良 \n（太嫩者，血气未足，无力）。酥涂微炙用（不酥涂则伤茸），或酒炙。不可嗅之，有虫恐入 \n鼻颡（猎人得鹿，絷之取茸，然后毙鹿，以血未散故也。最难得不破，未出血者。沈存中《笔 \n谈》云∶凡含血之物，血易长，筋次之，骨最难长。故人二十岁，骨髓方坚，麋、鹿角无两 \n月长至二十余斤，凡骨之长，无速于此，草木亦不及之。头为诸阳之会，钟于茸角，岂与凡 ",g:"补虚药"},
  "麝香":{o:"麝香",c:"宣，通窍 \n辛温香窜。开经络，通诸窍，透肌骨，暖水脏。治卒中诸风、诸气、诸血、诸痛，痰厥 \n惊痫（严用和云∶中风不醒者，以麝香清油灌之，先通其关。东垣曰∶风病在骨髓者宜之。 \n若在肌肉用之，反引风入骨，如油入面。时珍曰∶严氏言风病必先用，东垣谓必不可用，皆 \n非通论。若经络壅闭，孔窍不利者，安得不用为引导以开通之耶！但不可过耳。昂按∶据李 \n氏之言，似乃以严说为长。《广利方》中恶客忤垂死，麝香一钱，醋和灌之），症瘕瘴疟， \n鼻窒耳聋，目翳阴冷。辟邪解毒，杀虫堕胎。坏果败酒，故治果积、酒积（东垣曰∶麝香入 \n脾治肉，牛黄入肝治筋，冰片入肾治骨）。研用。凡使麝香，用当门子尤妙。忌蒜。不可近 \n鼻，",g:"开窍药"},
  "麦冬":{o:"麦门冬",c:"补肺，清心，泻热，润燥 \n甘微苦寒。清心润肺（东垣曰∶入手太阴气分），强阴益精，泻热除烦（微寒能泻肺 \n火，火退则金清，金旺则水生，阴得水养，则火降心宁而精益），消痰止嗽（午前嗽多属胃 \n火，宜芩、连、栀、柏、知母、石膏；午后嗽及日轻夜重者，多属阴虚，宜五味、麦冬、知 \n母、四物），行水生津（肺清则水道下行，故治浮肿；火降则肾气上腾，故又治消渴）。 \n治呕吐（胃火上冲则呕，宜麦冬。又有因寒、因食、因痰、因虚之不同），痿蹶（手足 \n缓纵曰痿蹶。阳明湿热上蒸于肺，故肺热叶焦，发为痿蹶。《经疏》曰∶麦冬实足阳明胃经 \n之正药），客热虚劳，脉绝短气（同人参、五味，名生脉散。盖心主脉，肺朝百脉，补肺清 ",g:"补虚药"},
  "麻黄":{o:"麻黄",c:"轻，发汗 \n辛温微苦（僧继洪曰∶中牟产麻黄，地冬不积雪，性热，故过服泄真气）。入足太阳（膀 \n胱），兼走手少阴、阳明（心、大肠）而为肺家专药。能发汗解肌，去营中寒邪、卫中风热。 \n调血脉，通九窍，开毛孔。 \n治中风伤寒（中，犹伤也），头痛温疟，咳逆上气（风寒郁于肺经。经曰∶诸气 郁， \n皆属于肺），痰哮气喘（哮证宜泻肺气，虽用麻黄，而不出汗，本草未载），赤黑斑毒（胃热。 \n一曰斑证，表虚不得再汗，非便闭亦不可下，只宜清解其热），毒风疹痹，皮肉不仁，目赤 \n肿痛，水肿风肿。过剂则汗多云阳，夏月禁用（汗者心之液，过汗则心血为之动摇，乃骁悍 \n之剂。丹溪以人参、麻黄同用，亦攻补法也。东垣曰∶十剂曰轻",g:"解表药"},
  "黄明胶":{o:"黄明胶",c:"\\x即牛皮胶\\x \n补虚 \n甘平。功与阿胶相近，亦可代用。同葱白煮粥，通大便（李时珍曰∶真阿胶难得，牛皮 \n胶亦可权用。其性味皆平补，宜于虚热之人。张仲景治泻痢，阿胶与黄胶、黄蜡并用。陈藏 \n器曰∶诸胶皆能疗风补虚止泄，驴皮主风为最。《经验方》云∶痈疽初起，酒顿黄明胶四两 \n，服尽，毒不内攻。《唐氏方》∶加穿山甲四片，烧存性用。昂谓∶此方若验，胜于服蜡矾 \n丸也）。",g:"其他"},
  "黄柏":{o:"黄柏",c:"泻相火，补肾水 \n苦寒微辛，沉阴下降。泻膀胱相火（足太阳引经药），补肾水不足，坚肾润燥（《发明》 \n曰∶非真能补也。肾苦燥，急食辛以润之，肾欲坚，急食苦以坚之也，相火退而肾固，则无 \n狂荡之患矣。按∶肾本属水，虚则热矣；心本属火，虚则寒矣），除湿清热。 \n疗下焦虚，骨蒸劳热（阴虚生内热），诸痿瘫痪（热胜则伤血，血不荣筋，则软短而为 \n拘。湿胜则伤筋，筋不束骨，则弛长而为痿。合苍术名二妙散，清热利湿，为治痿要药。或 \n兼气虚、血虚、脾虚、肾虚、湿痰、死血者，当随证加治），目赤耳鸣（肾火），消渴便闭， \n黄胆水肿（王善夫病便闭，腹坚如石，腿裂出水，饮食不下，治以利小便药，遍服不效。东 \n垣曰∶此奉",g:"清热药"},
  "黄精":{o:"黄精",c:"平补而润 \n甘平。补中益气，安五脏，益脾胃，润心肺，填精髓，助筋骨，除风湿，下三虫。以 \n其得坤土之精粹，久服不饥（气满则不饥。脂川有人虐使婢，婢逃入山，拔草根食之甚美， \n久食不饥。夜宿树下，见草动疑为虎，上树避之，及晓而下，凌空若飞鸟。家人采薪见之， \n告其主，设网捕不得。或曰∶此岂有仙骨？不过服食灵药耳。遂设酒馔于路，果来食之，食 \n讫遂不能去，擒而询之，指所食之草，乃黄精也）。 \n俗名山生姜，九蒸九晒用（仙家以为芝草之类，服之长生）。",g:"补虚药"},
  "黄芩":{o:"黄芩",c:"泻火，除湿 \n苦入心，寒胜热。泻中焦实火，除脾家湿热。 \n治 痢腹痛（便血曰 ，寒痛忌用。凡腹痛有寒热、虚实、食积，瘀血、痰湿之不同。 \n寒宜温，热宜清，虚宜补，实宜下，食宜消导，瘀血宜行散，痰湿宜化痰利湿。痛时手 \n不可按者为实痛，按之痛止者为虚痛），寒热往来（邪在少阳），黄胆五淋，血闭（实热在血 \n分）气逆，痈疽疮疡，及诸失血。消痰（丹溪以黄芩降痰，假其降火也。按痰因火动，当先 \n降火）利水，解渴安胎（胎孕宜清热凉血，血不妄行则胎安），养阴退阳，补膀胱水。 \n酒炒则上行，泻肺火，利胸中气（肺主气，热伤气，泻热所以保肺）。治上焦之风热、 \n湿热（丹溪曰∶黄芩上、中二焦药），火嗽喉腥（五臭，肺",g:"清热药"},
  "黄芪":{o:"黄",c:"补气，固表，泻火 \n甘温。生用固表，无汗能发，有汗能止（丹溪云∶黄 大补阳虚自汗，若表虚有邪， \n发汗不出者，服此又能自汗。朱震亨，号丹溪，着《本草补遗》）。温分肉，实腠理，泻阴火 \n，解肌热。炙用补中，益元气，温三焦，壮脾胃（脾胃一虚，土不能生金，则肺气先绝。脾 \n胃缓和，则肺气旺而肌表固实。补中即所以固表也）。生血生肌（气能生血、血充则肉长， \n经曰∶血生肉），排脓内托，疮痈圣药（毒瓦斯化则成脓，补气故能内托。痈疽不能成脓者， \n死不治，毒瓦斯盛而元气衰也，痘症亦然）。痘症不起，阳虚无热者宜之（新安汪机治痘症虚 \n寒不起，用四君子汤加黄 、紫草多效，间有枯萎而死者，自咎用药之不精，思之至忘",g:"补虚药"},
  "黄荠水":{o:"黄荠水",c:"宣，涌，吐 \n酸咸，吐痰饮、宿食。酸苦涌泄为阴也。",g:"其他"},
  "黄连":{o:"黄连",c:"泻火，燥湿 \n大苦大寒。入心泻火（王海藏曰∶泻心，实泻脾也。实则泻其子），镇肝凉血（凡治血， \n防风为上部之使，黄连为中部之使，地榆为下部之使），燥湿开郁，解渴（单用能治消渴） \n除烦，益肝胆，浓肠胃，消心瘀（能去心窍恶血），止盗汗（凉心）。 \n治肠 泻痢（便血曰 ，有脏连丸。湿热郁而为痢，黄连治痢要药。噤口者，热壅上焦 \n，同人参煎汤呷之，但得下咽便好。喻嘉言曰∶下痢，必先汗解其外，后调其内。首用辛凉 \n以解表，次用苦寒以攻里。《机要》云∶后重宜下，腹痛宜和，身重宜除湿，脉弦宜去风， \n风邪内结宜汗，身冷自汗宜温，脓血稠粘宜重剂以竭之。下痢，赤属血分，白属气分。戴氏 \n曰∶俗谓赤热、白寒者，",g:"清热药"},
  "黑大豆":{o:"黑大豆",c:"补肾，解毒 \n甘寒色黑。属水似肾，肾之谷也（豆有五色，各入五脏），故能补肾镇心（肾水足，则 \n心火宁），明目（肾水足则目明），利水下气（古方治水肿，每单用，或加他药），散热祛风 \n（炒热酒沃，饮其汁，治产后中风危笃及妊娠腰痛，兼能发表。《千金》云∶一以去风，一 \n以消血结），活血（《产书》云∶熬令烟绝，酒淋服，下产后余血）解毒（苏颂曰∶古称大豆 \n解百药毒，试之不然，又加甘草，其验乃奇），消肿止痛，捣涂一切肿毒，煮食稀痘疮。紧 \n小者良（小者名马料豆。每晨盐水吞，或盐水煮食，补肾）。畏五参、龙胆、猪肉。忌浓朴 \n（犯之动气），得前胡、杏仁、牡蛎、石蜜、诸胆汁良。",g:"清热药"},
  "鼠矢":{o:"鼠矢",c:"宣，调阴阳 \n甘而微寒。治伤寒劳复发热，男子阴易腹痛（妇人伤寒初愈，即与交接，毒中男人，名 \n阴易。若女人与伤寒男子交者，名阳易。《活人》有鼠矢汤）。两头尖者，为雄鼠屎。 \n鼠胆明目。汁滴耳中，治二十年老聋（陶弘景曰∶鼠胆随死辄消，不易得也）。 \n鼠肉治儿疳鼠 （河间曰∶鼠性善穿，而治疮 ，因其性为用也）。",g:"其他"},
  "龙眼肉":{o:"龙眼肉",c:"补心脾 \n甘温归脾。益脾长智（一名益智），养心补血（心为脾母），故归脾汤用之。治思虑劳心 \n脾，及汤风下血（心生血，脾统血。思虑过多，则心脾伤而血耗，致有健忘、怔忡、惊悸诸 \n病。归脾汤能引血归脾而生补之。肠风亦由血不归脾而妄行）。",g:"补虚药"},
  "龙胆草":{o:"龙胆草",c:"泻肝胆火，下焦湿热 \n大苦大寒，沉阴下行。益肝胆而泻火（相火寄于肝胆，有泻无补，泻其邪热，即所以补 \n火也），兼入膀胱、肾经。除下焦之湿热，与防己同功。酒浸亦能外行、上行。 \n治骨间寒热（肾主骨），惊痫邪气（肝经风火），时气温热，热痢疸黄、寒湿香港脚（足伤 \n湿热，则成香港脚。肿而痛者，为湿香港脚，宜清热利湿搜风。又有挛缩枯细，痛而不肿者，名 \n干香港脚，宜养血润燥），咽喉风热，赤睛 肉（泻肝胆火，能明目。元素曰∶柴胡为主，龙 \n胆为使，目疾要药。昂按∶若目疾初起，宜发散，忌用寒凉），痈疽疮疥。过服损胃。 \n甘草水浸一宿，曝用。小豆、贯众为使。忌地黄。",g:"补虚药"},
  "龙骨":{o:"龙骨",c:"涩，泻，固肠，镇惊 \n甘涩微寒。入手、足少阴（心、肾）、手阳明（大肠）、足厥阴（肝）经。能收敛浮越之 \n正气，涩肠益肾，安魂镇惊，辟邪解毒。治多梦纷纭，惊痫疟痢，吐衄崩带，遗精脱肛。利 \n大、小肠，固精止汗，定喘（气不归元则喘）敛疮，皆涩以止脱之义（《十剂》曰∶涩可去 \n脱。牡蛎、龙骨之属是也）。白地锦纹、舐之粘舌者良（人或以古矿灰伪之）。酒浸一宿，水 \n飞三度用，或酒煮、酥炙、火 ，亦有生用者。又云水飞，晒干，黑豆蒸过用（否则着人肠 \n胃，晚年作热）。忌鱼及铁。畏石膏、川椒、得人参、牛黄良（许洪云∶牛黄恶龙骨，而龙 \n骨得牛黄更良，有以制伏也）。",g:"安神药"},
  "龙齿":{o:"龙齿",c:"涩，镇惊 \n涩凉。镇心安魂。治大人痉癫狂热，小儿五惊十二痫（《卫生宝鉴》曰∶龙齿安魂，虎 \n睛定魄。龙属木，主肝，肝藏魂。虎属金，主肺，肺藏魄也）。治同龙骨。",g:"安神药"},
  "龟甲":{o:"龟板",c:"补阴，益血 \n甘平至阴，属金与水。补心益肾，滋阴资智（性灵，故资智、通心、益肾以滋阴）。治 \n阴血不足，劳热骨蒸，腰脚酸痛，久泻久痢（能益大肠），久嗽 疟（老疟也。或经数年， \n中有痞块，名疟母），症瘕崩漏，五痔产难（为末酒服，或加芎、归、 发），阴虚血弱之症 \n（益阴清热，故治之。时珍曰∶龟、鹿皆灵而寿。龟首常藏向腹，能通任脉，故取其甲，以 \n补精、补肾、补血，以养阴也。鹿首常还向尾，能通督脉。故取其角，以补命、补精、补气， \n以养阳也。昂按∶《本草》有鹿胶而不及龟胶，然板不如胶，诚良药也。合鹿胶，一阴一阳， \n名龟鹿二仙膏）。大者良。上、下甲皆可用。酥炙或酒炙、猪脂炙， 灰用。洗净槌碎，水",g:"补虚药"}
};